insert into public.cover_types (id,slug,title,description,hero_image,hero_album,sort_order) values
('818f66a4-a51e-4b8b-b515-691d9aba254d','portrait','Portrait','A single person is the subject: a face or figure, photographed or styled, that carries the record''s identity.','https://static.wixstatic.com/media/b519fa_2584aa9514c047319489b29f133a1a6b~mv2.jpg','Reasonable Doubt (Jay-Z)',1),
('27d91a37-0b27-477a-b65d-82e9697175da','photograph','Photograph','Photography whose subject isn''t the artist: objects, places, strangers and found images.','https://static.wixstatic.com/media/b519fa_332cbb74721c42ae8149107eecec7c8e~mv2.jpg','Paul''s Boutique (Beastie Boys)',2),
('6cbdce99-93a5-4ccd-adbc-b5e907e3ee7e','painting','Painting','Paintings in oil, acrylic, watercolour or ink, either commissioned for the record or borrowed from an existing work.','https://static.wixstatic.com/media/b519fa_999fbe8ae2e54c2fb73de38cb505612f~mv2.jpg','The Don Killuminati: The 7 Day Theory (Makaveli)',3),
('cac97ec2-47e9-4562-b1b0-ebb5ae534086','illustration','Illustration','Drawn artwork: line, comic, poster and airbrush illustration.','https://static.wixstatic.com/media/b519fa_b0f748194ceb4e3d986f1bfdfd3c2e41~mv2.jpg','Liquid Swords (GZA)',4),
('0eb085f8-d7ea-47e5-8c4a-bf504de1773f','group-photograph','Group photograph','The band or ensemble photographed together.','https://static.wixstatic.com/media/b519fa_59642bb05da04159b679c60d891204e0~mv2.jpg','Straight Outta Compton (N.W.A)',5),
('c0217d82-6644-4ea9-99d1-67b7e9dbe7a7','graphic-design','Graphic design','Covers built from shapes, symbols, layout and pure graphic form rather than a depicted scene.','https://static.wixstatic.com/media/b519fa_f5ee880f139d4cb6851fb4091ecebe21~mv2.jpg','The Chronic (Dr. Dre)',6),
('2a9002ef-8700-4b4b-bc97-eae22cc36802','collage','Collage','Covers assembled from many cut, layered or combined images.','https://static.wixstatic.com/media/b519fa_e0e49e28d7a14cca9c2c4ca15044c32a~mv2.jpg','Midnight Marauders (A Tribe Called Quest)',7),
('464ed954-6e08-4d0e-84ab-1a736b658cd3','digital-art','Digital art','Imagery made or heavily transformed with software: 3D rendering, digital manipulation and generated visuals.','https://static.wixstatic.com/media/b519fa_2bec2351e7894d238637cac279d7fc6f~mv2.jpg','Ghetto D (Master P)',8),
('4450e9cf-43d6-481d-b606-2e75cef9e7f9','typography','Typography','Covers where the lettering itself is the image.','https://static.wixstatic.com/media/b519fa_aaa4fa8c5ea045b9a952c300080b0407~mv2.jpg','If You''re Reading This It''s Too Late (Drake)',9),
('55ba40d7-5946-4af0-878f-e0d24ecb6f71','film-still','Film still','A frame taken from a film or television production.','https://static.wixstatic.com/media/b519fa_900f4582694649b283f39f300cd9645f~mv2.jpg','Donuts (J Dilla)',10),
('52e1479f-82f9-46b7-86e4-f22d676e06cc','childhood-photo','Childhood photo','A photograph of a child, usually the artist when young, often taken from a family album and used to frame the record as a story of where they came from.','https://static.wixstatic.com/media/b519fa_761368c584774181bcd36dddcd8d54b4~mv2.jpg','Illmatic (Nas)',11),
('fe0a06f7-7dc0-4ce2-a96b-221dbc0d00d9','sculpture','Sculpture','A physical object built or sculpted for the cover, from masks to giant inflatables, then photographed or shown as the artwork.','https://static.wixstatic.com/media/b519fa_4978ac1cde4b4150a7fd4eeaf721cc11~mv2.jpg','ASTROWORLD (Travis Scott)',12),
('dad05a73-56a1-4791-ba0a-64cfbc2ad929','archival-photo','Archival photo','An existing photograph licensed from an archive, news agency or private collection and reused as the cover, as opposed to one shot for the record.','https://static.wixstatic.com/media/b519fa_96638cc3ec664e1db720ccd05dbe04e9~mv2.jpg','DAYTONA (Pusha T)',13)
