insert into public.covers (id,slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,color,accent_color,image_url,image_width,image_height,spotify_album_id,spotify_url,apple_music_url,youtube_url,featured) values
('76e89b91-b1ca-4c2b-b63b-3678751eedfd','god-does-like-ugly','God Does Like Ugly','JID',2025,'2020s','Dreamville / Interscope','United States','6cbdce99-93a5-4ccd-adbc-b5e907e3ee7e',array['Southern hip-hop','Trap']::text[],'Painted by Luciano Maia','<p>The hand-painted cover of JID''s fourth album is the work of the artist Luciano Maia. Its style pays homage to Mati Klarwein''s painting for Miles Davis''s Bitches Brew, the 1970 jazz-fusion landmark, a debt Northern Transmissions pointed out when the album arrived. Like Klarwein''s work, it is a dense, surreal scene of bodies, sky and colour, with a pale central figure framed by radiating rays above a crowd of brightly coloured people.</p><p>The title flips the Southern saying "God don''t like ugly." JID took it from his late grandmother, who remarked after watching a chaotic news broadcast in 2019, "I guess God does like ugly if he letting this happen." Many listeners read the white figure at the centre of Maia''s painting as a god-like presence, possibly JID himself, watching over the people below, which ties the image to an album about faith, pain and the ugliness of the world. The title also echoes God Loves Ugly, the 2002 album by the Minneapolis group Atmosphere.</p><p>JID revealed the full artwork on 20 July 2025 in Washington Square Park in New York, where he also announced a run of small "Dollar & A Dream" concerts. The album was released on 8 August 2025 through Dreamville and Interscope.</p>','#EBDBBF','#AC8053','https://static.wixstatic.com/media/b519fa_869ba4d3c0754cbd9fae7fe73750a2d9~mv2.jpg',3000,3000,'2tU04u3hxtziB4sOVJKak3','https://open.spotify.com/album/2tU04u3hxtziB4sOVJKak3','https://music.apple.com/us/album/god-does-like-ugly/1812517697','https://www.youtube.com/results?search_query=JID+God+Does+Like+Ugly+full+album',false),
('7af8e8ce-e629-4ddd-87b9-67eaee6116d4','let-god-sort-em-out','Let God Sort Em Out','Clipse',2025,'2020s','Self-released / Roc Nation','United States','cac97ec2-47e9-4562-b1b0-ebb5ae534086',array['East Coast hip-hop','Coke rap']::text[],'Cover by KAWS; alternate covers by Verdy and Josh Sperling','<p>Clipse''s first album in 16 years reunited Pusha T and Malice with the artist KAWS, who had designed the cover of their 2009 album Til the Casket Drops. His painting shows his signature Companion character, the skull-and-crossbones figure with X eyes, being pieced together by two large cartoon hands, its bones laid out among the parts.</p><p>The image is a visual pun on the title. The Companion is literally being sorted out, assembled bone by bone by hands from above, a neat fit for an album about grief, faith and judgement made after the deaths of both brothers'' parents. The flat pink and violet palette keeps the morbid subject playful, in the style KAWS is known for in galleries.</p><p>Two alternate covers followed. The Japanese artist Verdy designed a variant package unveiled with the single "So Be It" in June 2025, and the American artist Josh Sperling announced his on 15 July, calling them "The Cross and the Anchor," with the cross "to represent sin, death and faith." The album was released on 11 July 2025, self-released through Roc Nation, to wide acclaim.</p>','#A37781','#C598B0','https://static.wixstatic.com/media/b519fa_7603f5af580548a5b3452a8d8fd30968~mv2.jpg',2500,2500,'17ScNnJ0lSWajodZaRpHdQ','https://open.spotify.com/album/17ScNnJ0lSWajodZaRpHdQ','https://music.apple.com/us/album/let-god-sort-em-out/1816313639','https://www.youtube.com/results?search_query=Clipse+Let+God+Sort+Em+Out+full+album',false),
('013d5ca7-7741-423b-9f6c-7d2e5b0d3e4f','chromakopia','CHROMAKOPIA','Tyler, the Creator',2024,'2020s','Columbia','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Alternative hip-hop','West Coast hip-hop']::text[],'Art direction by Shaun Llewellyn and Luis "Panch" Perez','<p>Tyler, the Creator usually makes colourful covers, so CHROMAKOPIA was a shock. The sepia-toned portrait shows him wearing a ceramic mask of his own face and stretching out his right hand towards whoever is behind the camera, introducing his new character, St. Chroma.</p><p>The cover''s art direction is credited to Shaun Llewellyn and Luis "Panch" Perez, Tyler''s collaborator of more than ten years. Perez told the Recording Academy that Tyler wanted it to feel like it came from a film noir of the 1930s and 1940s, and he told Mission magazine that Tyler shared old Hollywood studio test photos of actors for Hitchcock films as the reference. They shot it digitally because of the tight deadline, mixing continuous light and strobe.</p><p>CHROMAKOPIA was released on 28 October 2024 and debuted at number one. The masked portrait, about the gap between public persona and private self, earned a Grammy nomination for Best Album Cover.</p>','#1F1F1D','#BEBAA4','https://static.wixstatic.com/media/b519fa_9616564ff6a44cddbf650b97d4af179b~mv2.jpg',3000,3000,'0U28P0QVB1QRxpqp5IHOlH','https://open.spotify.com/album/0U28P0QVB1QRxpqp5IHOlH','https://music.apple.com/us/album/chromakopia/1776500452','https://www.youtube.com/results?search_query=Tyler%2C+the+Creator+CHROMAKOPIA+full+album',false),
('fc83a4d2-0515-4666-b5ea-34db47363f80','gnx','GNX','Kendrick Lamar',2024,'2020s','pgLang / Interscope','United States','27d91a37-0b27-477a-b65d-82e9697175da',array['West Coast hip-hop','Conscious hip-hop']::text[],'Photography and creative direction by Dave Free; design by Chris Burnett','<p>Kendrick Lamar released GNX without warning on 22 November 2024. The cover is a black-and-white photograph of him standing beside a 1987 Buick GNX, the dark car against a pale, hazy sky, with no title or text anywhere on the image.</p><p>The car is personal. Kendrick has said his father brought him home from the hospital in a 1987 Buick Regal, and the GNX is the high-performance version of the Regal from the year he was born. The photograph was taken by Dave Free, his longtime creative partner and pgLang co-founder, who shared creative direction with Kendrick, and the packaging was designed by Chris Burnett.</p><p>Burnett carried the car through the whole package, turning a wheel rim into the centre label of the vinyl. GNX debuted at number one, and its song "Not Like Us" went on to win the Grammy for Record of the Year.</p>','#DEDEDD','#181C20','https://static.wixstatic.com/media/b519fa_10114d8687f642e3a1a90095c7a3ca98~mv2.jpg',3000,3000,'0hvT3yIEysuuvkK73vgdcW','https://open.spotify.com/album/0hvT3yIEysuuvkK73vgdcW','https://music.apple.com/us/album/gnx/1781270319','https://www.youtube.com/results?search_query=Kendrick+Lamar+GNX+full+album',false),
('193f38f6-2ca6-43c0-88f7-b46e280c64c6','for-all-the-dogs','For All the Dogs','Drake',2023,'2020s','OVO / Republic','Canada','cac97ec2-47e9-4562-b1b0-ebb5ae534086',array['Canadian hip-hop','Trap']::text[],'Cover drawn by Adonis Graham, Drake''s son','<p>The cover of For All the Dogs is a child''s drawing: a scratchy white dog with long ears and glaring red eyes, standing on a black background. It was drawn by Drake''s son, Adonis Graham, who was five at the time, and Drake revealed it in August 2023 with the simple caption "Cover by Adonis."</p><p>Adonis described the drawing as "a carefree piece of work," and Drake linked it to his own past, calling it an inspiration from his 2016 album Views and dedicating it to a picture he had drawn in fifth grade of a cat with blue eyes. The choice suited a father whose relationship with his son had become a public subject after years of rumours and diss tracks.</p><p>The drawing quickly became merchandise, sticker sheets and fan art. For All the Dogs was released on 6 October 2023 and debuted at number one, and two unused alternative covers for the album later appeared in 2024.</p>','#070804','#999F9B','https://static.wixstatic.com/media/b519fa_8e04f610456148e29ffc145613191b4c~mv2.jpg',3000,3000,'4czdORdCWP9umpbhFXK2fW','https://open.spotify.com/album/4czdORdCWP9umpbhFXK2fW','https://music.apple.com/us/album/for-all-the-dogs/1710685602','https://www.youtube.com/results?search_query=Drake+For+All+the+Dogs+full+album',false),
('5423826e-c3b8-4437-a44f-eef6a68a293b','la-divina-commedia','La Divina Commedia','Tedua',2023,'2020s','Epic / Sony Music Italy','Italy','27d91a37-0b27-477a-b65d-82e9697175da',array['Italian hip-hop','Conscious hip-hop']::text[],'Photography by David LaChapelle','<p>The Genoese rapper Tedua built his album around Dante''s Divine Comedy, the poem that travels through Hell, Purgatory and Paradise. To shoot its covers he hired David LaChapelle, the American photographer famous for his lurid, theatrical images of celebrities, and the same artist behind Travis Scott''s ASTROWORLD.</p><p>LaChapelle produced two covers, one for Purgatorio and one for Inferno, revealed a week apart in May 2023. The Inferno cover was shot on the slopes of a Hawaiian volcano and shows Tedua in a torn work suit among the lava, a modern sinner in a landscape of fire.</p><p>Tedua presented the album as his own journey from hell towards paradise. La Divina Commedia was released on 2 June 2023, and the pairing of a young Italian rapper with one of the world''s best-known photographers made the covers an event in Italian rap.</p>','#142135','#DFAE2E','https://static.wixstatic.com/media/b519fa_c15383e88daf4dd7a243fc0be1be4c10~mv2.jpg',3000,3000,'4ir7AIjfrMVHTxZhnfzhWl','https://open.spotify.com/album/4ir7AIjfrMVHTxZhnfzhWl','https://music.apple.com/it/album/la-divina-commedia/1689797901','https://www.youtube.com/results?search_query=Tedua+La+Divina+Commedia+full+album',false),
('8b2fe929-d438-40a3-9339-193547156bc9','mass-country','Mass Country','AKA',2023,'2020s','Vth A / Sony Music Africa','South Africa','cac97ec2-47e9-4562-b1b0-ebb5ae534086',array['South African hip-hop','Amapiano']::text[],'Illustration by Karabo Poppy','<p>AKA revealed the cover of Mass Country on Instagram on 11 January 2023. It was drawn by the South African illustrator Karabo Poppy, known for her bright, patterned portraits, and shows AKA''s face surrounded by objects that stand for South African culture, including a ten-cent coin, a vintage BMW, a skull and a snake.</p><p>Like the album title, the drawing celebrates South Africa itself, with AKA at the centre of the things that made him.</p><p>Four weeks after the reveal, on 10 February 2023, AKA was shot dead outside a restaurant in Durban at the age of 35. Mass Country was released posthumously on 24 February 2023 and quickly went gold, and the cover became the last portrait of one of South Africa''s biggest rap stars.</p>','#C24326','#D8986D','https://static.wixstatic.com/media/b519fa_3667fe168fe142c3afb4e25536c3d431~mv2.jpg',3000,3000,'376vzaVcBQAbefjO1t7vu5','https://open.spotify.com/album/376vzaVcBQAbefjO1t7vu5','https://music.apple.com/za/album/mass-country/1664064205','https://www.youtube.com/results?search_query=AKA+Mass+Country+full+album',false),
('ba68ad1b-5f84-4ef0-9559-6ee1d30bda44','utopia','UTOPIA','Travis Scott',2023,'2020s','Cactus Jack / Epic','United States','27d91a37-0b27-477a-b65d-82e9697175da',array['Psychedelic rap','Trap']::text[],'Photography by Kristina Nagel; creative direction by Nicklas Bildstein Zaar (Sub); styling by Peri Rosenzweig and Hardstyle','<p>After years of delays, Travis Scott''s fourth album arrived with five different covers. The main one is almost entirely black, with a small figure of Travis falling into the darkness.</p><p>The main cover was photographed by Kristina Nagel, with Travis styled by Peri Rosenzweig and Nick Royal, known as Hardstyle, and belts by the designer Arlette. The creative director of all the covers and the UTOPIA zine was Nicklas Bildstein Zaar of the Berlin studio Sub, and the South African photographer Pieter Hugo shot two of the alternate covers.</p><p>UTOPIA was released on 28 July 2023 and debuted at number one. The idea of several covers for one record recalled Kanye''s My Beautiful Dark Twisted Fantasy, and several of the creatives had worked with Kanye before.</p>','#0C070C','#867878','https://static.wixstatic.com/media/b519fa_aa89f4928ade450d8c04ef8a9095f158~mv2.jpg',3000,3000,'18NOKLkZETa4sWwLMIm0UZ','https://open.spotify.com/album/18NOKLkZETa4sWwLMIm0UZ','https://music.apple.com/us/album/utopia/1699712635','https://www.youtube.com/results?search_query=Travis+Scott+UTOPIA+full+album',false),
('c8d36404-13c1-4a65-90c2-c6a60b51dd90','mr-morale-the-big-steppers','Mr. Morale & the Big Steppers','Kendrick Lamar',2022,'2020s','pgLang / Top Dawg / Aftermath / Interscope','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['West Coast hip-hop','Conscious hip-hop']::text[],'Photography by Renell Medrano','<p>Renell Medrano photographed Kendrick Lamar at home with his family for the cover of his fifth album. Kendrick stands in a white T-shirt wearing a crown of thorns, holding his and Whitney Alford''s daughter, while Alford sits on the bed behind them cradling an infant, in a warm, dimly lit bedroom with dark walls.</p><p>The album, released after a five-year gap, deals with therapy, generational trauma, infidelity and the burden of being treated as a saviour. The crown of thorns places that burden on Kendrick''s head in plain sight, and putting his partner and children on the cover made his private life part of the subject. The Line of Best Fit called the record "so vulnerable and exposing (including using his family for the artwork)."</p><p>The artwork was revealed on 11 May 2022, two days before the album came out on pgLang, Top Dawg, Aftermath and Interscope. It debuted at number one and later won the Grammy for Best Rap Album, and Medrano''s family portrait stands among the most discussed covers in Kendrick''s catalogue.</p>','#53321A','#6D5944','https://static.wixstatic.com/media/b519fa_75fa428dd2e645b2b01a0202d8c6d8f8~mv2.jpg',3000,3000,'79ONNoS4M9tfIA1mYLBYVX','https://open.spotify.com/album/79ONNoS4M9tfIA1mYLBYVX','https://music.apple.com/us/album/mr-morale-the-big-steppers/1623854804','https://www.youtube.com/results?search_query=Kendrick+Lamar+Mr.+Morale+and+the+Big+Steppers+full+album',false),
('5bb108d4-7216-482a-87fe-3b09744cfe15','call-me-if-you-get-lost','Call Me If You Get Lost','Tyler, the Creator',2021,'2020s','Columbia Records','United States','c0217d82-6644-4ea9-99d1-67b7e9dbe7a7',array['West Coast hip-hop','Jazz rap']::text[],'Art direction by Darren Vongphakdy and Wolf Haley; photography by Luis "Panch" Perez','<p>The cover of Call Me If You Get Lost is an identity card. It belongs to "Tyler Baudelaire," the globe-trotting character Tyler created for the album, and shows a passport-style photo of him in a light-blue hat, next to fields of personal details, stamps and a signature on a perforated, cream-coloured card.</p><p>The design was inspired by passports and travel cards from the early 1900s, matching an album about a wealthy traveller who boats and flies around the world. The surname Baudelaire comes from the orphaned siblings in Lemony Snicket''s A Series of Unfortunate Events. Darren Vongphakdy and Tyler, under his alias Wolf Haley, directed the art, with photography by Luis "Panch" Perez.</p><p>Tyler revealed the cover on 17 June 2021, and different streaming services carried versions of the card in different colours. Released on 25 June 2021 through Columbia, the album debuted at number one and won the Grammy for Best Rap Album, and fans made their own versions of the travel card online.</p>','#FEFEFD','#8FB8CF','https://static.wixstatic.com/media/b519fa_0e7249755dc04c0d95deabcdcc3b0fd1~mv2.jpg',3000,3000,'45ba6QAtNrdv6Ke4MFOKk9','https://open.spotify.com/album/45ba6QAtNrdv6Ke4MFOKk9','https://music.apple.com/us/album/call-me-if-you-get-lost/1573484415','https://www.youtube.com/results?search_query=Tyler,+the+Creator+Call+Me+If+You+Get+Lost+full+album',false),
('7872e0e6-8b44-4b5d-a7e6-b9635c62d101','civilisation','Civilisation','Orelsan',2021,'2020s','7th Magnitude / 3e Bureau / Wagram','France','c0217d82-6644-4ea9-99d1-67b7e9dbe7a7',array['French hip-hop','Conscious hip-hop']::text[],'Flag designed by Rægular; photography by Alice Moitié','<p>For his fourth album, Orelsan invented a country. The cover is built around a new flag for an imaginary micronation, and Orelsan described himself stepping back behind that symbol. The graphic designer Rægular drew the flag from his ideas and went through around a hundred versions before reaching the final one, and Alice Moitié is credited with the photography.</p><p>Every part of the flag has a meaning. The blue and red come from the French flag and can also point to the colours of Caen, Orelsan''s city. The white was left out, since royalty was not the point. A green band stands for the provinces and nature, and a grey and white checkerboard copies Photoshop''s empty transparent background, so anyone can make the flag their own. A black rectangle stands for respect, and a white shape combines a shuriken for defence with a star for hope and the diversity of beliefs.</p><p>Civilisation was released on 19 November 2021, and on the later Civilisation perdue edition Moitié''s photo was replaced by a flat black field with only the flag''s star kept.</p>','#356E96','#138F54','https://static.wixstatic.com/media/b519fa_2457977e18294cd786fd32944da7d6ca~mv2.jpg',3000,3000,'2o2GBOfy2GG9oKYZgfZkur','https://open.spotify.com/album/2o2GBOfy2GG9oKYZgfZkur','https://music.apple.com/us/album/civilisation/1788304818','https://www.youtube.com/results?search_query=Orelsan+Civilisation+full+album',false),
('9795e8b3-b5df-4e53-8a77-272dc3e31681','flop','Flop','Salmo',2021,'2020s','Machete Empire / Columbia','Italy','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Italian hip-hop','Rap rock']::text[],'After Alexandre Cabanel''s painting The Fallen Angel (1847)','<p>The Sardinian rapper Salmo recreated one of the most famous paintings of the 19th century for his 2021 album. The cover is a close-up of Salmo''s face posed as Lucifer in Alexandre Cabanel''s The Fallen Angel, the 1847 canvas in which the beautiful rebel angel, just cast out of heaven, glares over his folded arm with eyes full of tears and rage.</p><p>Salmo copies the pose and the look, his face half hidden behind his arm and his eyes staring sideways, against a patch of blue sky. Italian critics and art blogs pointed out the quotation at once.</p><p>The image fits the title, which means failure, and an album about success, pride and falling from grace. Flop was released on 1 October 2021 on his label Machete Empire and Columbia, and the fallen-angel portrait became one of the most discussed Italian covers of the year.</p>','#2F231D','#3E6CBA','https://static.wixstatic.com/media/b519fa_7d58895fd2eb4b9c888ca14d9451d72c~mv2.jpg',3000,3000,'7DvK67C21i6go7olhjvLgT','https://open.spotify.com/album/7DvK67C21i6go7olhjvLgT','https://music.apple.com/us/album/flop/1587171881','https://www.youtube.com/results?search_query=Salmo+Flop+full+album',false),
('c23ae502-f18b-42d4-ae58-7da4925f21b1','historias-da-minha-area','Histórias da Minha Área','Djonga',2020,'2020s','A Quadrilha','Brazil','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['Brazilian hip-hop','Conscious hip-hop']::text[],'Photography by Daniel Assis (176 Studio); art by Alvaro B. Junior (Caverna Studios)','<p>Djonga, the rapper from Belo Horizonte, released an album every March for several years in a row, and the cover of his fourth is one of his hardest images. In a narrow favela alley, young Black men stand and sit together, some alive and wearing football shirts, others lying on the ground with bullet wounds.</p><p>The photograph is by Daniel Assis of 176 Studio, with art by Alvaro B. Junior, known as Alvinho, of Caverna Studios. Placing the living and the dead in the same frame makes the cover''s message plain: without opportunities, the future for boys in poor neighbourhoods can end in an early death.</p><p>The title means stories from my area, and the album tells them one by one. Histórias da Minha Área came out on 16 March 2020, and its cover reads as a portrait of police violence and everyday loss in Brazil''s peripheries.</p>','#13171C','#69504A','https://static.wixstatic.com/media/b519fa_fc88b45acdb34a7cbc323f4b054df595~mv2.jpg',2500,2500,'3NjTHK6FovpR3rHceaT5FE','https://open.spotify.com/album/3NjTHK6FovpR3rHceaT5FE','https://music.apple.com/br/album/hist%C3%B3rias-da-minha-%C3%A1rea/1502146741','https://www.youtube.com/results?search_query=Djonga+Histórias+da+Minha+Área+full+album',false),
('27b58720-0925-4142-97fc-a7d0a9c0f104','pray-for-paris','Pray for Paris','Westside Gunn',2020,'2020s','Griselda Records','United States','2a9002ef-8700-4b4b-bc97-eae22cc36802',array['East Coast hip-hop','Boom bap']::text[],'Cover by Virgil Abloh, adapting Caravaggio''s David with the Head of Goliath','<p>Westside Gunn announced Pray for Paris after attending Virgil Abloh''s Off-White show in Paris on 18 January 2020, and Abloh, a close friend, made the cover. He took a cropped detail of Caravaggio''s David with the Head of Goliath, the version held in Vienna''s Kunsthistorisches Museum, in which the young David holds out the severed head of the giant.</p><p>Abloh then made one change. Westside Gunn''s signature chains are photoshopped around David''s neck, turning a Baroque masterpiece into a Griselda album cover. The Ringer described the chains as "clumsily Photoshopped," and the rough join is part of the point: high art and street jewellery pasted together with no attempt to hide the seam.</p><p>The image suits a rapper who fills his records with references to fashion and art auctions, and The Ringer heard the album itself as a David taking a defiant step forward against the Goliaths behind him. Gunn revealed the artwork on 3 April 2020, and the album was released on 17 April 2020 through Griselda and Empire.</p>','#10100F','#6D5840','https://static.wixstatic.com/media/b519fa_20fd433ff4a84ac8a82c5fce2ddfea52~mv2.jpg',3000,3000,'6nfJMRoIjyRwk3ZTHNm0PY','https://open.spotify.com/album/6nfJMRoIjyRwk3ZTHNm0PY','https://music.apple.com/us/album/pray-for-paris/1506521703','https://www.youtube.com/results?search_query=Westside+Gunn+Pray+for+Paris+full+album',false),
('346ed847-6919-42ae-b8e2-7d379f905081','whole-lotta-red','Whole Lotta Red','Playboi Carti',2020,'2020s','AWGE','United States','c0217d82-6644-4ea9-99d1-67b7e9dbe7a7',array['Rage','Experimental hip-hop']::text[],'Design by Art Dealer','<p>The Whole Lotta Red cover is designed like a punk fanzine. It pays homage to Slash, the late-1970s Los Angeles fanzine, and specifically to the issue that put David Vanian of the Damned on its cover. Playboi Carti appears in a stark black-and-white photograph with the word "Red" scrawled above his head in blood-red ink.</p><p>The text along the side, next to the Parental Advisory label, completes the illusion of a magazine. It reads "Volume One Number One Of Red" and "The Wonderful World of Red/Mayday Issue 12/25," presenting the album as the first issue of a fictional publication from Carti''s Opium imprint.</p><p>The design was created by Art Dealer. Journalists noted that the album''s imagery and merchandise drew on heavy metal aesthetics alongside the punk references of the cover, matching the distorted, aggressive sound of the record. Whole Lotta Red was released on 25 December 2020.</p>','#FEFEFE','#CB1B2B','https://static.wixstatic.com/media/b519fa_31a7d331bfcf46468eee76e96a7d537c~mv2.jpg',3000,3000,'2QRedhP5RmKJiJ1i8VgDGR','https://open.spotify.com/album/2QRedhP5RmKJiJ1i8VgDGR','https://music.apple.com/us/album/whole-lotta-red/1546163603','https://www.youtube.com/results?search_query=Playboi+Carti+Whole+Lotta+Red+full+album',false),
('a28f9e93-75db-4382-afc1-7bc1eb665774','amarelo','AmarElo','Emicida',2019,'2010s','Laboratório Fantasma','Brazil','27d91a37-0b27-477a-b65d-82e9697175da',array['Brazilian hip-hop','MPB']::text[],null,'<p>The cover of AmarElo is a small black-and-white photograph of young Black men in a street, set inside a wide white border, with the title and Emicida''s name below in a thin rainbow of colours.</p><p>The São Paulo rapper made the album as a celebration of Black Brazilian history and joy. Its title song samples Belchior''s "Sujeito de Sorte" and features Majur and Pabllo Vittar, and the album won a Latin Grammy in 2020, followed by the Netflix documentary AmarElo: It''s All for Yesterday.</p><p>The simple, documentary photograph and the bright lettering capture the album''s mix of memory and hope. AmarElo became one of the most important Brazilian records of its time, linking rap to samba, MPB and the country''s Black cultural movement.</p>','#FDFDFD','#1A1A1A','https://static.wixstatic.com/media/b519fa_1cbe8873ad8047a38986014c75498ba8~mv2.jpg',1400,1400,'22ltKhPdKZ4IuFrna73xPG','https://open.spotify.com/album/22ltKhPdKZ4IuFrna73xPG','https://music.apple.com/us/album/amarelo/1484562276','https://www.youtube.com/results?search_query=Emicida+AmarElo+full+album',false),
('42038f4d-781e-4877-adce-21ea8a71fd9a','igor','IGOR','Tyler, the Creator',2019,'2010s','Columbia','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Alternative hip-hop','Neo soul']::text[],'Cover by Tyler, the Creator; alternate portrait by Lewis Rossignol','<p>The cover of IGOR is a stark black-and-white portrait of Tyler, the Creator in a blond bowl-cut wig, set against a flat pink background with tiny text. It introduced Igor, the lovesick character whose story runs through the album.</p><p>Each of Tyler''s albums has two covers, one by Tyler himself and one by another artist, and for IGOR the second came from Lewis Rossignol, an illustrator in Portland, Maine. Tyler contacted Rossignol on Instagram about six months before the album''s announcement, saying it was for an art project, and sent him reference photos of the blond wig, sunglasses, suit and gold teeth. Rossignol went through several versions, with Tyler''s handwriting added to the jacket, and Tyler then told him: "I know I said it was going to be for an art [project], but I think I''d rather use it for my album."</p><p>IGOR was released on 17 May 2019, debuted at number one and won the Grammy for Best Rap Album. Rossignol''s portrait was used for the vinyl edition.</p>','#EFAFC3','#393633','https://static.wixstatic.com/media/b519fa_71b2a0b14c7c475b96774c369a2427b3~mv2.jpg',3000,3000,'5zi7WsKlIiUXv09tbGLKsE','https://open.spotify.com/album/5zi7WsKlIiUXv09tbGLKsE','https://music.apple.com/us/album/igor/1463409338','https://www.youtube.com/results?search_query=Tyler%2C+the+Creator+IGOR+full+album',false),
('b6494978-a5fd-4374-9766-11cd7d0ede3e','les-etoiles-vagabondes','Les Étoiles vagabondes','Nekfeu',2019,'2010s','Seine Zoo / Polydor','France','c0217d82-6644-4ea9-99d1-67b7e9dbe7a7',array['French hip-hop','Conscious hip-hop']::text[],'Graphic design by Rægular','<p>Nekfeu''s third album arrived with its film. Les Étoiles vagabondes was first presented as an "album au cinéma," a documentary directed by Syrine Boulanouar and Nekfeu that followed the making of the record through Paris, Japan, Greece and the United States. It was shown once, in nearly 200 cinemas across France, Belgium, Morocco, Switzerland and Canada, and drew more than 100,000 people, a French record for a single screening of a music documentary.</p><p>The packaging was designed to feel like something carried home from the trip. Rægular handled the graphic design, and the original CD was sold in a sealed plastic sleeve that served as the whole package, limited to 100,000 copies. The cover shows exactly that: a shiny, crinkled pouch with the disc pressed inside.</p><p>About two weeks later Nekfeu followed up with Expansion, adding 16 new songs for 34 tracks in total. Its physical edition came in a padded bubble-wrap mailer, another piece of packaging that turned an everyday object into the artwork.</p>','#010508','#545663','https://static.wixstatic.com/media/b519fa_c10386dd45da4b1ea176c38e0cdfd2b0~mv2.jpg',640,640,'5eLZYtCXkFIsOmpVc7vrI2','https://open.spotify.com/album/5eLZYtCXkFIsOmpVc7vrI2','https://music.apple.com/fr/album/les-%C3%A9toiles-vagabondes-expansion/1468503258','https://www.youtube.com/results?search_query=Nekfeu+Les+Étoiles+vagabondes+full+album',false),
('d1a01a19-e464-4a56-9e3f-e0c8c238170e','nothing-great-about-britain','Nothing Great About Britain','slowthai',2019,'2010s','Method Records','United Kingdom','27d91a37-0b27-477a-b65d-82e9697175da',array['UK hip-hop','Grime']::text[],'Concept by Crowns & Owls; creative direction by Lewis Levi; set and art direction by James Hamilton; graphic design by George Smith; produced by Andy Picton','<p>slowthai''s debut album cover puts the Northampton rapper naked in a wooden pillory, the medieval stocks used for public shaming, flanked by Union flags and grinning straight at the camera. The concept came from the creative studio Crowns & Owls, with Lewis Levi as creative director and James Hamilton building the set.</p><p>The shoot took place on the Spring Boroughs estate in Northampton, in front of the block where slowthai grew up, a building whose residents had been given eviction notices and which was later demolished. Placing the stocks there tied an old punishment to modern public shaming, including the kind dealt out on social media, and to a country he felt had left places like his behind.</p><p>The title spells out the joke and the anger at once, on an album released on 17 May 2019, in the middle of the Brexit years. The record was shortlisted for the Mercury Prize, and the image of a naked rapper locked in the stocks outside his childhood home became one of the most talked-about British album covers of the decade. George Smith handled the graphic design, and Andy Picton produced the shoot.</p>','#685346','#B48350','https://static.wixstatic.com/media/b519fa_3cb24ea1610a4eb7bebdbaf8feda5653~mv2.jpg',3000,3000,'5Ki4YFQrUx7hCcQx1LJUQb','https://open.spotify.com/album/5Ki4YFQrUx7hCcQx1LJUQb','https://music.apple.com/us/album/nothing-great-about-britain/1457181800','https://www.youtube.com/results?search_query=slowthai+Nothing+Great+About+Britain+full+album',false),
('7a1b21a7-1883-42ba-9211-c0f2fad705f6','psychodrama','PSYCHODRAMA','Dave',2019,'2010s','Neighbourhood','United Kingdom','464ed954-6e08-4d0e-84ab-1a736b658cd3',array['British hip-hop','Conscious hip-hop']::text[],null,'<p>The cover of PSYCHODRAMA shows a dark figure whose head has been replaced by a burning blue flame, under the title in jagged blue letters, an image of a mind on fire.</p><p>The south London rapper framed his debut album as a series of therapy sessions, moving through songs about race, family, love and his brother''s imprisonment, including "Black" and the eleven-minute story "Lesley." Released on 8 March 2019, it debuted at number one and won the Mercury Prize.</p><p>The burning head turns the title into an image of inner pressure. PSYCHODRAMA was praised as one of the most ambitious British rap albums ever made and made Dave one of the defining voices of his generation.</p>','#010203','#0D7FE4','https://static.wixstatic.com/media/b519fa_9c5ed9ba8e6a4fcc8bf93f4341d8cb2e~mv2.jpg',1400,1400,'4GrFuXwRmEBJec22p58fsD','https://open.spotify.com/album/4GrFuXwRmEBJec22p58fsD','https://music.apple.com/us/album/psychodrama/1839406091','https://www.youtube.com/results?search_query=Dave+PSYCHODRAMA+full+album',false),
('075091e0-3d68-4460-82bb-07afa00b7038','astroworld','ASTROWORLD','Travis Scott',2018,'2010s','Cactus Jack Records','United States','fe0a06f7-7dc0-4ce2-a96b-221dbc0d00d9',array['Psychedelic rap','Trap']::text[],'Photography by David LaChapelle','<p>ASTROWORLD is named after the Six Flags AstroWorld theme park in Houston, which closed and was demolished. "They tore down AstroWorld to build more apartment space," Travis Scott said. For the cover, photographer David LaChapelle built a new entrance for the lost park: a giant golden inflatable of Scott''s head, its open mouth serving as the gateway.</p><p>The day version shows children, parents and park staff gathered in front of the golden head. An alternate night version shows the same entrance after dark, with the family-friendly crowd replaced by adult-themed content, in LaChapelle''s lurid, carefully staged style.</p><p>The night cover caused a stir before release. On 1 August 2018, transgender model Amanda Lepore, a frequent LaChapelle collaborator, asked why she had been left off the final version. LaChapelle said she had upstaged the other models, and Scott responded that he respects the LGBTQ community. The album was released on 3 August 2018.</p>','#9EB7C8','#477DAC','https://static.wixstatic.com/media/b519fa_4978ac1cde4b4150a7fd4eeaf721cc11~mv2.jpg',3000,3000,'41GuZcammIkupMPKH2OJ6I','https://open.spotify.com/album/41GuZcammIkupMPKH2OJ6I','https://music.apple.com/us/album/astroworld/1421241217','https://www.youtube.com/results?search_query=Travis+Scott+ASTROWORLD+full+album',false),
('48b19049-9c2e-4638-b3b9-f1e5c48fcba8','daytona','DAYTONA','Pusha T',2018,'2010s','GOOD Music','United States','dad05a73-56a1-4791-ba0a-64cfbc2ad929',array['East Coast hip-hop','Hardcore hip-hop']::text[],'Cover photograph from Splash News; cover design by Akeem Smith','<p>The cover of DAYTONA is a photograph of the bathroom of the late singer Whitney Houston, its counter cluttered with drug paraphernalia. It replaced the album''s original artwork only a few days before release, and the image was licensed for $85,000, a fee paid by Kanye West, who produced the album.</p><p>The choice was deliberately provocative for a record steeped in drug-dealing imagery. The cover design was credited to Akeem Smith, with the photograph itself credited to the agency Splash News.</p><p>It drew immediate criticism. Houston''s former husband, Bobby Brown, said the cover was in "really really bad taste." DAYTONA was released on 25 May 2018 by GOOD Music and Def Jam, and its sleeve remains one of the most debated covers of the decade.</p>','#968B82','#6F605C','https://static.wixstatic.com/media/b519fa_96638cc3ec664e1db720ccd05dbe04e9~mv2.jpg',3000,3000,'07bIdDDe3I3hhWpxU6tuBp','https://open.spotify.com/album/07bIdDDe3I3hhWpxU6tuBp','https://music.apple.com/us/album/daytona/1388853738','https://www.youtube.com/results?search_query=Pusha+T+DAYTONA+full+album',false),
('20a2d36f-3d9a-4f1a-bfb1-e91956bb2f77','die-lit','Die Lit','Playboi Carti',2018,'2010s','AWGE / Interscope','United States','27d91a37-0b27-477a-b65d-82e9697175da',array['Trap','Rage']::text[],'Photography by Nick Walker','<p>Nick Walker photographed Playboi Carti in mid-air, diving off a stage into a packed crowd of fans with outstretched arms. The image is high-contrast black and white, with Carti in white at the top of the frame and the crowd swallowed in grain and shadow below, and the idea came from a reference photo of an old punk rock show.</p><p>That punk feeling matched the album, whose chaotic shows made Carti one of the most exciting live acts in rap. A$AP Rocky revealed the cover on 10 May 2018, the day before the album came out on AWGE and Interscope. Fans soon fixated on a bearded, long-haired man in the crowd who many thought looked like Dave Grohl.</p><p>In 2023 the man was identified as the actor Francisco Marcano, who said he had been unaware that his image would be used. The mystery added to the photo''s legend, and the stage-dive shot has become one of the defining images of the rage era that Die Lit helped launch.</p>','#020202','#8A8A8A','https://static.wixstatic.com/media/b519fa_a0c78c10e73640979e44b892a58c23bc~mv2.jpg',3000,3000,'7dAm8ShwJLFm9SaJ6Yc58O','https://open.spotify.com/album/7dAm8ShwJLFm9SaJ6Yc58O','https://music.apple.com/us/album/die-lit/1381553184','https://www.youtube.com/results?search_query=Playboi+Carti+Die+Lit+full+album',false),
('fda721f8-6334-4984-9283-e71ae5eedd69','gigantes','Gigantes','BK''',2018,'2010s','Pirâmide Perdida Records','Brazil','6cbdce99-93a5-4ccd-adbc-b5e907e3ee7e',array['Brazilian hip-hop','Conscious hip-hop']::text[],'Painting by Maxwell Alexandre','<p>The Rio de Janeiro rapper BK'' asked the painter Maxwell Alexandre, an artist from the Rocinha favela whose work has since entered museums such as MASP in São Paulo and the Reina Sofía in Madrid, to paint the cover of his second album. The canvas fills a warm yellow field with figures, rooftops and scenes from the streets of Lapa in Rio.</p><p>At the bottom of the painting stand Black children, and as the eye moves up they grow into giants, all wearing masks of the Deus do Furdunço. The painting turns the album''s title into an image of Black pride and of young Black people growing into their own power, the central theme of the record.</p><p>Gigantes was released on 13 October 2018 on BK''s label Pirâmide Perdida. The cover tied Brazilian rap directly to one of the country''s most celebrated young painters, at the moment his career was taking off.</p>','#D6A844','#8C744D','https://static.wixstatic.com/media/b519fa_2099ff234e8d43008dd519e4efb1af55~mv2.jpg',3000,3000,'4W2IL1NXpcbsYmGdAjeJGg','https://open.spotify.com/album/4W2IL1NXpcbsYmGdAjeJGg','https://music.apple.com/br/album/gigantes/1439659556','https://www.youtube.com/results?search_query=BK''+Gigantes+full+album',false),
('dfef6a04-fda7-428a-b3ff-ddb04e1598ce','kids-see-ghosts','Kids See Ghosts','Kids See Ghosts',2018,'2010s','GOOD Music','United States','cac97ec2-47e9-4562-b1b0-ebb5ae534086',array['Psychedelic rap','Progressive rap']::text[],'Creative direction, artwork and calligraphy by Takashi Murakami; original drawing direction by Chieri Nakano','<p>Takashi Murakami, who had drawn the Dropout Bear for Graduation, returned for Kanye West and Kid Cudi''s joint album. His pastel, psychedelic scene shows a ghostly figure riding a sharp-toothed creature with haunted eyes, shaped like a sperm, as it flies through a forest with a mountain behind.</p><p>The background is based on Hokusai''s Thirty-six Views of Mount Fuji, and the credits list View of Mt. Fuji (1847) as its source. The two rappers appear as animals: West as a bear and Cudi as a fox. Cudi had suggested a dog, but West preferred the fox once he saw an early sketch. Murakami said his team followed a "very rudimental plan," sketching ideas on paper with West and his assistants.</p><p>West first teased a black-and-white version in April 2018, with only a few touches in colour, and captioned it "Murakami vibes." Murakami is credited for creative direction, artwork and calligraphy, with original drawing direction by Chieri Nakano. The album was released on 8 June 2018.</p>','#A8BCBC','#C24F5E','https://static.wixstatic.com/media/b519fa_15da5331352945aba69c712a8a6be3f2~mv2.jpg',3000,3000,'6pwuKxMUkNg673KETsXPUV','https://open.spotify.com/album/6pwuKxMUkNg673KETsXPUV','https://music.apple.com/us/album/kids-see-ghosts/1396710872','https://www.youtube.com/results?search_query=Kanye+West+Kid+Cudi+Kids+See+Ghosts+full+album',false),
('6e140fe7-4b33-4dd1-9bd4-7df6eaeb6233','rockstar','Rockstar','Sfera Ebbasta',2018,'2010s','Def Jam / Universal Music Italia','Italy','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Italian hip-hop','Trap']::text[],null,'<p>Sfera Ebbasta poses on the cover of Rockstar with bright red hair, white sunglasses and a pink fur coat against a yellow background, a loud pop-star image for a trap record.</p><p>The rapper from Cinisello Balsamo, near Milan, made the album with his producer Charlie Charles. Released on 19 January 2018, it gathered 35 million streams in its first week, put all eleven tracks in the top twelve of the Italian singles chart at once and made him the first Italian artist on Spotify''s global top 100.</p><p>The flamboyant cover matched an artist who treated trap as pop stardom. Rockstar was the best-selling Italian album of 2018 and showed that Italian trap could compete with the biggest international releases.</p>','#E07A86','#F8B806','https://static.wixstatic.com/media/b519fa_5b393b8dc8d64631afd47ec55b17523c~mv2.jpg',3000,3000,'5YXyBqtxW2APQNBCscATw0','https://open.spotify.com/album/5YXyBqtxW2APQNBCscATw0','https://music.apple.com/it/album/rockstar/1440909949','https://www.youtube.com/results?search_query=Sfera+Ebbasta+Rockstar+full+album',false),
('4ecab9f9-afb1-4181-9230-60a8c45bfbcb','touch-my-blood','Touch My Blood','AKA',2018,'2010s','Beam Group','South Africa','c0217d82-6644-4ea9-99d1-67b7e9dbe7a7',array['South African hip-hop','Pop rap']::text[],'Front cover by Nicky Heat and Johnny Malepa (fan design contest winners); back cover by Taonga','<p>For his third album, the Johannesburg rapper AKA let his fans design the cover. On 20 April 2018 he announced the "Touch My Blood Challenge," inviting anyone to submit artwork, and he later narrowed the entries down to a top ten.</p><p>The winning front cover, a bold silhouette of AKA''s head against a flat red background, came from Nicky Heat and Johnny Malepa, and the official artwork was unveiled on 8 May 2018. The runner-up, a visual artist from Rustenburg in the North West province known as Taonga, designed the back cover and was rewarded with an internship at AKA''s company, Beam Group.</p><p>The contest turned the album''s release into a shared project with his audience. Touch My Blood was released on 15 June 2018, after a short delay so AKA could finish videos and plan his tour.</p>','#0D0302','#D3534F','https://static.wixstatic.com/media/b519fa_814d7ffdd4314ffe8b2c6e8ed56c8876~mv2.jpg',3000,3000,'2Upg5l79vSVNVS9v8vDqUa','https://open.spotify.com/album/2Upg5l79vSVNVS9v8vDqUa','https://music.apple.com/us/album/touch-my-blood/1391157689','https://www.youtube.com/results?search_query=AKA+Touch+My+Blood+full+album',false),
('550509f0-025e-447e-87ba-ee75911e6f60','ye','ye','Kanye West',2018,'2010s','GOOD Music','United States','27d91a37-0b27-477a-b65d-82e9697175da',array['Progressive rap','Alternative hip-hop']::text[],'Photograph by Kanye West','<p>Kanye West took the cover of ye himself, on his iPhone, on the way to the album''s listening party on 31 May 2018, only hours before release, as Kim Kardashian revealed. The photo shows the Teton Range near Jackson Hole, Wyoming, where the album was recorded.</p><p>Across the mountains he scrawled a line in neon green handwriting: "I hate being Bi-Polar its awesome." The words turned a quick landscape snapshot into a statement about his mental health, the subject at the centre of the album, and the same lettering was reused for the lyric videos of "All Mine" and "Violent Crimes."</p><p>The phone photo replaced an earlier idea. In April 2018 West''s planned cover featured Jan Adams, the surgeon who had operated on his mother, and Adams objected publicly, asking West to "cease and desist using my photo or any image of me to promote your album." ye was released on 1 June 2018.</p>','#132332','#5FE05F','https://static.wixstatic.com/media/b519fa_bac841e9eed4413d834e08a2d06d4744~mv2.jpg',3000,3000,'5EBGCvO6upi3GNknMVe9x9','https://open.spotify.com/album/5EBGCvO6upi3GNknMVe9x9','https://music.apple.com/us/album/ye/1441460375','https://www.youtube.com/results?search_query=Kanye+West+ye+full+album',false),
('50c8540c-2503-4e54-9520-f5f2df5ba01c','culture','Culture','Migos',2017,'2010s','Quality Control / 300','United States','2a9002ef-8700-4b4b-bc97-eae22cc36802',array['Trap','Atlanta hip-hop']::text[],'Cover design by Stole "Moab" Stojmenov','<p>Migos'' second album, the record that made the Atlanta trio of Quavo, Offset and Takeoff the biggest group in rap, wraps their faces in a dense collage on a black background. Gold, flames, money and city landmarks pile up around them, with the title set in gold at the bottom.</p><p>The cover was designed by Stole "Moab" Stojmenov, a young graphic designer based in Milan, and it was meant to show what Migos had given to hip-hop and to Atlanta, from music to fashion. Years later Offset explained one of the symbols that runs through the Culture covers. Speaking on Amazon Music''s Connected With Wayno in 2021, he said the doves represent the group''s grandmothers: "That''s grandma on them album covers."</p><p>Culture was released on 27 January 2017, debuted at number one and carried "Bad and Boujee" to the top of the Billboard Hot 100. It defined the sound of trap at the height of its takeover, and Takeoff''s death in 2022 has given the dove symbol a sadder weight.</p>','#0E0D0D','#896448','https://static.wixstatic.com/media/b519fa_fd3599d5e9d4489394242da9ee4af502~mv2.jpg',3000,3000,'4JTOxuvM2jcSqAvEZtZsOO','https://open.spotify.com/album/4JTOxuvM2jcSqAvEZtZsOO','https://music.apple.com/us/album/culture/1615495955','https://www.youtube.com/results?search_query=Migos+Culture+full+album',false),
('9cd849db-b8d8-404b-b48b-2f1fcbb3528f','damn','DAMN.','Kendrick Lamar',2017,'2010s','Top Dawg Entertainment','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Conscious rap','Trap']::text[],'Design by Vladimir Sepetov; photography by Roberto Reyes and Dave Free; creative direction by Kendrick Lamar, Vladimir Sepetov and Dave Free','<p>Vlad Sepetov, who also designed To Pimp a Butterfly, called the DAMN. cover "loud and abrasive." Kendrick Lamar stands against a brick wall in a plain white T-shirt, his expression weary, while the title runs across the top in huge red capital letters.</p><p>Sepetov said the cover is less overtly political than To Pimp a Butterfly but just as energetic. Even the Parental Advisory label was placed with care: it sits off-centre, towards the right of the frame, so that it works as part of the design and does not look like an "afterthought."</p><p>Lamar unveiled the cover on 11 April 2017, three days before the album''s release. Billboard included it among the best covers of 2017, praising it as both memorable and easy to turn into a meme. Vladimir Sepetov designed the cover, Roberto Reyes and Dave Free took the photographs, and creative direction is credited to Kendrick Lamar, Sepetov and Free.</p>','#73404D','#AE2228','https://static.wixstatic.com/media/b519fa_6ebcaaf12c0a47658127a787dfac1a12~mv2.jpg',3000,3000,'4eLPsYPBmXABThSJ821sqY','https://open.spotify.com/album/4eLPsYPBmXABThSJ821sqY','https://music.apple.com/us/album/damn/1440881047','https://www.youtube.com/results?search_query=Kendrick+Lamar+DAMN.+full+album',false),
('525a3fd3-f312-4ba9-838a-93b0018b7a62','everybody','Everybody','Logic',2017,'2010s','Visionary Music Group / Def Jam','United States','6cbdce99-93a5-4ccd-adbc-b5e907e3ee7e',array['Conscious hip-hop','East Coast hip-hop']::text[],'Painting by Sam Spratt','<p>Logic had just seen Paolo Veronese''s huge Renaissance canvas The Wedding at Cana at the Louvre when he asked the painter Sam Spratt to make something like it. Spratt, who had painted his earlier covers, built a crowded classical scene of columns, arches, statues and stairways, filled with around 80 of Logic''s closest friends and inspirations.</p><p>Spratt admitted the scale was new to him: "Fuck, well, I''ve never done anything like that." The finished painting hides details tied to Logic''s ongoing story, and Spratt warned fans that some would make sense only later, saying "people literally won''t understand until they listen to Ultra 85." A fan named Josh, who has osteogenesis imperfecta, won a contest to be painted into the crowd.</p><p>Spratt said he was "pretty happy with how it turned out." Everybody, an album built around the idea that all people are equal, was released on 5 May 2017 and debuted at number one, and its cover remains one of the most detailed paintings ever used on a rap record.</p>','#4E3B36','#CCAF96','https://static.wixstatic.com/media/b519fa_92fb613c298e4bf3995912cd2a072004~mv2.jpg',3000,3000,'3hwnyNkxe0IVqZhQfn9xmc','https://open.spotify.com/album/3hwnyNkxe0IVqZhQfn9xmc','https://music.apple.com/us/album/everybody/1440896552','https://www.youtube.com/results?search_query=Logic+Everybody+full+album',false),
('500588b1-183d-42dd-851c-1080de7221d6','flower-boy','Flower Boy','Tyler, the Creator',2017,'2010s','Columbia Records','United States','6cbdce99-93a5-4ccd-adbc-b5e907e3ee7e',array['Jazz rap','Alternative hip-hop']::text[],'Painting by Eric White','<p>Tyler, the Creator''s manager introduced him to Eric White, a Michigan-born painter. At their first meeting Tyler showed him sketches and photos that captured the mood he wanted, and the two went back and forth over text and phone for several weeks before White produced a detailed composition.</p><p>The finished painting places Tyler in a field of sunflowers under a tangerine sky, with rolling hills behind him and a swarm of oversized bees circling around him. It is bright and warm, yet slightly unsettling, which suits an album about loneliness, longing and growing up. After some minor fine-tuning, Tyler approved the design and left White to finish the painting on his own.</p><p>Tyler has never seen the finished piece in person. Billboard''s Tatiana Cirisano included White''s cover among the best of 2017 and called it "surreal." A second, physical cover was designed by Tyler himself. Flower Boy was released on 21 July 2017.</p>','#F8A12E','#E4551F','https://static.wixstatic.com/media/b519fa_1a2fe440e9a54431872c85b02073455a~mv2.jpg',1500,1500,'2nkto6YNI4rUYTLqEwWJ3o','https://open.spotify.com/album/2nkto6YNI4rUYTLqEwWJ3o','https://music.apple.com/us/album/flower-boy/1254572564','https://www.youtube.com/results?search_query=Tyler,+the+Creator+Flower+Boy+full+album',false),
('0d57a6be-0e04-40d5-9f36-eae2c5434ec5','gang-signs-prayer','Gang Signs & Prayer','Stormzy',2017,'2010s','#Merky','United Kingdom','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['Grime','British hip-hop']::text[],null,'<p>Stormzy sits at the centre of a long table on the cover of his debut album, surrounded by men in balaclavas, in a dark scene that recreates Leonardo da Vinci''s Last Supper, with his name and the title in small type at the top.</p><p>The south London MC moved between hard grime and gospel on the album, from "Big for Your Boots" to "Blinded by Your Grace." Released on 24 February 2017 on his own #Merky label, Gang Signs & Prayer became the first grime album to reach number one in the UK.</p><p>The Last Supper image joins the two halves of the title, the street and the church, in one picture. It made Stormzy one of Britain''s biggest stars and prepared the way for his historic headline set at Glastonbury in 2019.</p>','#040501','#484546','https://static.wixstatic.com/media/b519fa_f550d650544e467a9a8347eb20b42953~mv2.jpg',1500,1500,'5fkFWJ9LZizXE4yPenNGuy','https://open.spotify.com/album/5fkFWJ9LZizXE4yPenNGuy','https://music.apple.com/us/album/gang-signs-prayer/1673768631','https://www.youtube.com/results?search_query=Stormzy+Gang+Signs+%26+Prayer+full+album',false),
('ac15f1af-12c8-473b-985f-150f958f1a7d','atrocity-exhibition','Atrocity Exhibition','Danny Brown',2016,'2010s','Warp','United States','464ed954-6e08-4d0e-84ab-1a736b658cd3',array['Experimental hip-hop','Alternative hip-hop']::text[],'Artwork by Timothy Saccenti','<p>Danny Brown took the title of his fourth album from Joy Division''s song "Atrocity Exhibition," itself borrowed from J.G. Ballard''s novel, and the cover is as unsettling as the name. It shows a portrait of Danny Brown warped into deep purples and blacks, set inside a grey frame.</p><p>The artwork was created by Timothy Saccenti, the photographer and filmmaker who has also worked on Run the Jewels'' covers. The picture is circuit-bent, made by deliberately rewiring electronics so that the image breaks down, and on one side of the rapper''s face the skin appears to be peeled back to the bone.</p><p>Atrocity Exhibition was released on 27 September 2016 on the British label Warp. Its glitching, decaying cover matched an album about addiction and anxiety, often named among the most daring rap records of the decade.</p>','#0D0A1B','#675F74','https://static.wixstatic.com/media/b519fa_8b5d57a03d694b96b44107e36493cc45~mv2.jpg',1400,1400,'3A1vnUJDPz0xYMful9pO4I','https://open.spotify.com/album/3A1vnUJDPz0xYMful9pO4I','https://music.apple.com/us/album/atrocity-exhibition/1142690534','https://www.youtube.com/results?search_query=Danny+Brown+Atrocity+Exhibition+full+album',false),
('cddd29ff-6659-46da-9c0c-a196ab94b6ff','coloring-book','Coloring Book','Chance the Rapper',2016,'2010s','Independent','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Chicago hip-hop','Gospel rap']::text[],'Cover art by Brandon Breaux','<p>Chance the Rapper''s third mixtape shows him from the shoulders up in a black cap with a white number 3, looking up and smiling into a glowing pink and red sky. The 3 marks it as his third project, and the bright, soft colours suit a joyful record full of gospel choirs.</p><p>The cover was made by the Chicago artist Brandon Breaux, who also created the art for Chance''s 10 Day and Acid Rap, and he planned the three covers as one sequence tracing Chance''s rise. Breaux chose digital painting so people would care about the artist''s hand, and he worked by stripping things away. His early idea of surrounding Chance with vices was dropped, and the only text he kept was Chance''s name. As he put it to The Hundreds, "the art is the brand."</p><p>Coloring Book was released on 13 May 2016, first as an Apple Music exclusive, and the image went up on billboards, bus stops and walls across the country with no slogans or logos. In 2017 it became the first streaming-only release to win a Grammy, taking Best Rap Album.</p>','#F25261','#2B55A9','https://static.wixstatic.com/media/b519fa_bf8b70c5de4949a2930e1fa37d12868e~mv2.jpg',3000,3000,'71QyofYesSsRMwFOTafnhB','https://open.spotify.com/album/71QyofYesSsRMwFOTafnhB','https://music.apple.com/us/album/coloring-book/1113239004','https://www.youtube.com/results?search_query=Chance+the+Rapper+Coloring+Book+full+album',false),
('5436ad51-e6b3-488c-a68a-000cf94bb15c','dans-la-legende','Dans la légende','PNL',2016,'2010s','QLF','France','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['French hip-hop','Cloud rap']::text[],null,'<p>The brothers Ademo and N.O.S of PNL face each other on the cover of Dans la légende, both in sunglasses, their faces glowing in a smooth gradient of orange, pink and blue, with no text on the image at all.</p><p>The duo from Corbeil-Essonnes, south of Paris, released their music independently on their own label, QLF, gave almost no interviews and built their following through striking music videos. Released on 16 September 2016, Dans la légende mixed dreamy, melancholy production with Auto-Tuned verses about the estate they grew up on, and it became a huge commercial success.</p><p>The wordless, colourful portrait matches a group that spoke mainly through images. PNL changed the sound and the look of French rap, and the mirrored faces of the two brothers became one of its most recognisable covers.</p>','#E9A9A5','#ED9917','https://static.wixstatic.com/media/b519fa_9489b1c8c4194df9b7a42929e333982e~mv2.jpg',1440,1440,'5GFHFEASZeJF0gyWuDDjGE','https://open.spotify.com/album/5GFHFEASZeJF0gyWuDDjGE','https://music.apple.com/fr/album/dans-la-l%C3%A9gende/1663880916','https://www.youtube.com/results?search_query=PNL+Dans+la+l%C3%A9gende+full+album',false),
('64d04c4a-aa0e-47c0-bd95-854a1490563a','hitler-wears-hermes-4','Hitler Wears Hermes 4','Westside Gunn',2016,'2010s','Griselda Records','United States','2a9002ef-8700-4b4b-bc97-eae22cc36802',array['East Coast hip-hop','Boom bap']::text[],'Creative direction by Westside Gunn; designer not credited','<p>Westside Gunn named his long-running mixtape series as a play on The Devil Wears Prada, swapping the devil for the most notorious dictator of the twentieth century and Prada for Hermès. He described the style he was after as "some of the grimiest but flyest shit I could come up with." Hitler Wears Hermes 4, the fourth installment, arrived on Halloween 2016 through his Buffalo label Griselda Records, with every beat produced by Daringer and guest verses from Conway, Benny, Smoke DZA, Stalley and Tiona D.</p><p>The cover takes the title literally. A black-and-white photograph of Hitler''s head sits on a cut-paper body, and the collage defaces it piece by piece: pasted-in eyes, one ringed in gold, a red tear running down the cheek, glossy red lips set beneath the moustache, and a soft bow at the collar. An orange Hermès tag, in the fashion house''s signature colour, is stuck across the chest like a price label. Respect magazine called it an "unbalanced, disproportioned digital collage" with a transparent mid-section, and judged it possibly the most visually experimental Griselda cover up to that point. Gunn handled the creative direction himself, while the designer who assembled the collage is not credited in any release listing.</p><p>The image turns a dictator into a mocked, overdressed mannequin, which suits a series built on pairing street-level crime rhymes with luxury fashion. Gunn, who launched his own clothing brand Fashion Rebels in 2012, grew more ambitious with his artwork after this release: for Hitler Wears Hermes 6 in 2018 he commissioned an oil painting from the artist Isaac Pelayo for a reported $10,000. In 2017 the UK label Daupe! pressed Hitler Wears Hermes 4 on limited vinyl, including a black edition of 250 copies.</p>','#FFFFFF','#ED621F','https://static.wixstatic.com/media/b519fa_7b94fb4c0efc4cbea1ea2bc3790d0d6b~mv2.jpg',3000,3000,'7M28Ejbd7r4lT46KhpRwhj','https://open.spotify.com/album/7M28Ejbd7r4lT46KhpRwhj','https://music.apple.com/us/album/hitler-wears-hermes-4/1169799145','https://www.youtube.com/results?search_query=Westside+Gunn+Hitler+Wears+Hermes+4+full+album',false),
('3884bc1a-1dd8-44b1-976a-54a1f60031f1','jeffery','JEFFERY','Young Thug',2016,'2010s','300 / Atlantic','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Trap','Atlanta hip-hop']::text[],'Photography by Garfield Larmond; dress by Alessandro Trincone','<p>On the cover of JEFFERY, Young Thug stands against a plain white background in a flowing, ruffled lavender dress and a wide brimmed hat that hides his face. Released under his birth name, the mixtape turned one of trap''s most unpredictable voices into a fashion statement, and the image started a debate about masculinity in rap that ran for months.</p><p>The photograph was taken by Garfield Larmond, who told The FADER that Thug had already done one cover shoot in Atlanta and disliked the results. In New York, VFILES founder Julie Anne Quay showed him a piece from the Italian designer Alessandro Trincone''s Annodami collection, inspired by Japanese kimonos, and Thug said, "I want that for the cover." Dressing him took about an hour and a half, and fitting the hat another thirty minutes. When Thug saw the first frames he said, "This is it. This is what we needed from the beginning."</p><p>JEFFERY was released on 26 August 2016, with each song named after one of Thug''s idols, from Wyclef Jean to Kanye West. Trincone''s dress became one of the most famous garments in hip-hop, and the cover remains a landmark in how rappers present themselves.</p>','#FEFEFE','#585A85','https://static.wixstatic.com/media/b519fa_b34322284f8a4c32812c3c2bf8a2631e~mv2.jpg',1425,1425,'7EpUpNUkkEGnaCvkcn1j4H','https://open.spotify.com/album/7EpUpNUkkEGnaCvkcn1j4H','https://music.apple.com/us/album/jeffery/1146718343','https://www.youtube.com/results?search_query=Young+Thug+JEFFERY+full+album',false),
('2d67f2a6-cf84-42b9-8660-33ae067da252','konnichiwa','Konnichiwa','Skepta',2016,'2010s','Boy Better Know','United Kingdom','c0217d82-6644-4ea9-99d1-67b7e9dbe7a7',array['Grime','British hip-hop']::text[],null,'<p>The cover of Konnichiwa looks like a letter from Japan: a plain white surface with a red square stamp and a black round postmark, and the title written by hand, as if the album had arrived in the post.</p><p>Skepta, the Tottenham grime MC, released the album himself on his Boy Better Know label on 6 May 2016, carried by "Shutdown" and "That''s Not Me." Its Japanese title and launch show in Tokyo reflected his global ambitions, and it won the Mercury Prize, a landmark for grime.</p><p>The postal stamp fits an album about sending grime around the world. After Konnichiwa, Skepta and grime were celebrated far beyond London, and the cover''s simple, independent look matched a record made without a major label.</p>','#E0DFE3','#88100E','https://static.wixstatic.com/media/b519fa_da46be1299054401813808e90a0a457a~mv2.jpg',1500,1500,'6s4vWWWxNrGcKhrOFYRZzk','https://open.spotify.com/album/6s4vWWWxNrGcKhrOFYRZzk','https://music.apple.com/us/album/konnichiwa/1168936007','https://www.youtube.com/results?search_query=Skepta+Konnichiwa+full+album',false),
('31638b80-019d-4871-bda9-ecd5d900b43d','the-life-of-pablo','The Life of Pablo','Kanye West',2016,'2010s','GOOD Music','United States','2a9002ef-8700-4b4b-bc97-eae22cc36802',array['Gospel rap','Art pop']::text[],'Design by Peter De Potter','<p>Kanye West turned to Belgian artist Peter De Potter for The Life of Pablo, a less famous name than earlier collaborators such as George Condo and Takashi Murakami. De Potter''s orange cover repeats the album title over and over in uneven formatting, a restless stack of words that matches an album West kept changing after release.</p><p>Two photographs are set into the type: a small family picture and a cropped image of British model Sheniz Halil, reportedly chosen by Kim Kardashian. The cover also carries the phrase "which one," which had appeared on the notepad holding the album''s final tracklist. "I couldn''t be more flattered and honoured," Halil said.</p><p>West revealed two versions of the design on 11 February 2016, days before the album premiered as a streaming exclusive on Tidal on 14 February. Some speculated that the collaboration came through designer Raf Simons, who had worked with De Potter and whom West cited as an influence.</p>','#F28B55','#C1764F','https://static.wixstatic.com/media/b519fa_08356f0a19054583bc83942200785279~mv2.jpg',3000,3000,'7gsWAHLeT0w7es6FofOXk1','https://open.spotify.com/album/7gsWAHLeT0w7es6FofOXk1','https://music.apple.com/us/album/the-life-of-pablo/1443063578','https://www.youtube.com/results?search_query=Kanye+West+The+Life+of+Pablo+full+album',false),
('b512ca05-8e6e-4db0-a912-a33cec23698d','untitled-unmastered','untitled unmastered.','Kendrick Lamar',2016,'2010s','Top Dawg Entertainment','United States','c0217d82-6644-4ea9-99d1-67b7e9dbe7a7',array['Jazz rap','Conscious rap']::text[],'Design by Vladimir Sepetov','<p>untitled unmastered. arrived with almost no warning on 4 March 2016, a set of unfinished demos from the sessions for To Pimp a Butterfly, and its cover looks as raw as the music. NPR described it as "an unadorned, almost industrial green field," with the title in small lowercase letters and a full stop.</p><p>The sleeve was designed by Vlad Sepetov, who also made the covers for To Pimp a Butterfly and DAMN. Every song on the record is titled "untitled" plus a number and a date, and the plain green square follows the same logic, presenting the project like a folder of working files.</p><p>The release followed months of demand. Kendrick had performed untitled songs on The Colbert Report, The Tonight Show and at the 2016 Grammys, and LeBron James publicly urged Top Dawg Entertainment''s Anthony Tiffith to put them out. The collection debuted at number one on the Billboard 200. The cover was designed by Vladimir Sepetov, the art director behind much of Kendrick''s visual work.</p>','#353301','#6B6A1A','https://static.wixstatic.com/media/b519fa_690773cddb1a40c7b54b1e0a39c4e15a~mv2.jpg',3000,3000,'0kL3TYRsSXnu0iJvFO3rud','https://open.spotify.com/album/0kL3TYRsSXnu0iJvFO3rud','https://music.apple.com/us/album/untitled-unmastered/1440844834','https://www.youtube.com/results?search_query=Kendrick+Lamar+untitled+unmastered.+full+album',false),
('7c69f9c1-bd19-42dc-8190-4c4efd353fcf','vibe','Vibe','Fler',2016,'2010s','Maskulin Music Group','Germany','27d91a37-0b27-477a-b65d-82e9697175da',array['German hip-hop','Trap']::text[],'Photography by Katja Kuhl','<p>The photographer Katja Kuhl shot Fler at night in front of a graffiti wall in Berlin, using a long exposure that turned the background into streaks of colour while he stands still in an Alpha Industries bomber jacket and cap, looking down. The single white word "Vibe" sits in the centre of the frame. The album had originally been called Carlo Escobar, before Fler changed the title in May 2016.</p><p>Fans quickly compared the cover to YG''s Still Brazy, released the same summer, which also uses a blurred, motion-smeared portrait. Fler denied copying it. "Kenne den Typen nich mal," he answered, I don''t even know the guy, adding that his cover was a real long exposure while YG''s was a cheap effect.</p><p>Vibe was released on 2 September 2016 on Fler''s own Maskulin label and debuted at number one in Germany, Austria and Switzerland, his second German number-one album.</p>','#303D38','#4A665C','https://static.wixstatic.com/media/b519fa_c9363365ed2147de8e17928cb407dfa1~mv2.jpg',640,640,'7EBmwHYrrAlw2BH8bjzKS6','https://open.spotify.com/album/7EBmwHYrrAlw2BH8bjzKS6','https://music.apple.com/de/album/vibe/1824481570','https://www.youtube.com/results?search_query=Fler+Vibe+full+album',false),
('7b05350d-c0f5-4091-8bcc-6886b6b159b8','views','Views','Drake',2016,'2010s','Young Money / Cash Money / Republic','Canada','27d91a37-0b27-477a-b65d-82e9697175da',array['Canadian hip-hop','Pop rap']::text[],'Photography by Caitlin Cronenberg; art direction and design by Nicky Orenstein','<p>Drake built his fourth album around Toronto, and the cover put him on top of the city''s best-known landmark. The image shows him sitting alone on the edge of the CN Tower, legs hanging over the drop, under a grey sky. Toronto photographer Caitlin Cronenberg shot the cover and booklet, with art direction and design by Nicky Orenstein.</p><p>Drake revealed the artwork on 24 April 2016, after the last stop of his Toronto pop-up store. People noticed at once that he looked far too big for the tower. The Toronto Star wrote about "Drake''s towering view of The 6," and The Verge ran a tongue-in-cheek "scientific investigation" into how tall he would have to be. The CN Tower''s own account confirmed the image had been photoshopped.</p><p>The picture turned into one of the most copied memes of the year, with fans pasting a tiny Drake onto every tall object they could find. Views came out on 29 April 2016 and spent 13 weeks at number one in the United States, and its cover became the defining image of Drake as the city''s self-appointed giant.</p>','#47535A','#657278','https://static.wixstatic.com/media/b519fa_cf9ed3a4cd9b40b988b44c36c68719d8~mv2.jpg',3000,3000,'40GMAhriYJRO1rsY4YdrZb','https://open.spotify.com/album/40GMAhriYJRO1rsY4YdrZb','https://music.apple.com/us/album/views/1440841363','https://www.youtube.com/results?search_query=Drake+Views+full+album',false),
('f4db7414-50e4-4817-8dcc-907961d15d4b','if-you-re-reading-this-it-s-too-late','If You''re Reading This It''s Too Late','Drake',2015,'2010s','OVO Sound','Canada','4450e9cf-43d6-481d-b606-2e75cef9e7f9',array['Canadian hip-hop','Trap']::text[],'Cover art by Jim Joe','<p>The cover of If You''re Reading This It''s Too Late is just seven unpunctuated words in black on a white background, written in jerky, angular capitals that slope downward. Many people first assumed Drake had scrawled it himself. It was the work of Jim Joe, an anonymous graffiti writer who began tagging in Montreal and became known in New York for plain, one-colour text.</p><p>Jim Joe already had ties to Kanye West''s creative circle, and his art had appeared on the Yeezus iTunes page. For Drake, he was given the whole cover. The project dropped by surprise late on 12 February 2015, and fans immediately pored over the words, with some reading them as a message aimed at Birdman and Cash Money.</p><p>As Hazlitt put it, "the cover alone was an overnight hit." Fans built free fonts and online generators to make their own versions, the design spread across Etsy merchandise, and Pusha T name-checked Jim Joe on a 2015 track. The album debuted at number one with 535,000 units in its first week.</p>','#FEFEFE','#111111','https://static.wixstatic.com/media/b519fa_aaa4fa8c5ea045b9a952c300080b0407~mv2.jpg',1500,1500,'0ptlfJfwGTy0Yvrk14JK1I','https://open.spotify.com/album/0ptlfJfwGTy0Yvrk14JK1I','https://music.apple.com/us/album/if-youre-reading-this-its-too-late/1440839718','https://www.youtube.com/results?search_query=Drake+If+You''re+Reading+This+It''s+Too+Late+full+album',false),
('df7724ee-e539-4516-a746-f44a0362e4e2','rodeo','Rodeo','Travis Scott',2015,'2010s','Grand Hustle Records','United States','fe0a06f7-7dc0-4ce2-a96b-221dbc0d00d9',array['Trap','Psychedelic rap']::text[],'Action figure sculpted by Dan Chung','<p>The cover of Rodeo is a photograph of an action figure. Travis Scott wanted a toy version of himself, and he commissioned Dan Chung, a specialist figure maker and former film worker who had collaborated with Spike Lee on Clockers. "He wanted this to happen and would not be denied," Chung said.</p><p>Chung built it entirely by hand. "No software, no scanning, no 3D printing," he explained. He sculpted the head in wax from reference photos, made a silicone mould, cast the figure in resin and painted it, used real hair for the braids, reworked the body to match Scott''s slim build and tailored custom clothes. "Process-wise, I''m old school," he said.</p><p>The figure was photographed so that viewers would wonder whether it was real. The standard cover is a close-up, while the deluxe edition pulls back to show the figure on top of a monster truck. Rodeo was released on 4 September 2015, and three years later ASTROWORLD returned to the idea of Scott as a giant, unreal object.</p>','#2A2F2E','#917163','https://static.wixstatic.com/media/b519fa_eff638ba2fbf4b739aae762a59107fc0~mv2.jpg',3000,3000,'4PWBTB6NYSKQwfo79I3prg','https://open.spotify.com/album/4PWBTB6NYSKQwfo79I3prg','https://music.apple.com/us/album/rodeo/1456176981','https://www.youtube.com/results?search_query=Travis+Scott+Rodeo+full+album',false),
('e32350c7-7aa0-4943-a1af-e79df50043c7','tetsuo-youth','Tetsuo & Youth','Lupe Fiasco',2015,'2010s','1st & 15th / Atlantic','United States','6cbdce99-93a5-4ccd-adbc-b5e907e3ee7e',array['Conscious hip-hop','Alternative hip-hop']::text[],'Painting by Lupe Fiasco','<p>Lupe Fiasco painted the cover of Tetsuo & Youth himself. The abstract canvas sets a heavy diagonal band of purple and white across fields of red, pink and white, with thick brushwork and a small raised shape pressed into the red at the lower left. It sits on a white border like a photograph of a painting hanging in a gallery.</p><p>The album had been delayed for years by disputes with Atlantic, and Lupe treated it as an art object in every sense. The title borrows from Tetsuo Shima, the troubled teenager in Akira, and the record moves through the seasons, with instrumental interludes named Summer, Fall, Winter and Spring dividing its long, dense songs.</p><p>Grantland noted that Lupe painted the artwork, a rare case of a major-label rapper handing over his own canvas as the cover. Released on 20 January 2015 through 1st & 15th and Atlantic, the album was his last for the label and was welcomed as a return to form, with the painting standing for its ambition.</p>','#F9F5F5','#D62014','https://static.wixstatic.com/media/b519fa_1e85c056379a4859be8e1ddf3b6bfa38~mv2.jpg',1425,1425,'7F58zK8t8whSFjX5X09d28','https://open.spotify.com/album/7F58zK8t8whSFjX5X09d28','https://music.apple.com/us/album/tetsuo-youth/948344511','https://www.youtube.com/results?search_query=Lupe+Fiasco+Tetsuo+and+Youth+full+album',false),
('00a6b596-8929-4ed1-9222-5d20c85ed7db','to-pimp-a-butterfly','To Pimp a Butterfly','Kendrick Lamar',2015,'2010s','Top Dawg / Aftermath / Interscope','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['Jazz rap','Conscious hip-hop','Funk']::text[],'Cover photography by Denis Rouvre and Roberto "retOne" Reyes; art direction by Dave Free, Kendrick Lamar and Vlad Sepetov','<p>The cover of To Pimp a Butterfly looks like a victory party in the wrong place. In a black-and-white photograph by the French photographer Denis Rouvre, a crowd of shirtless young Black men and children celebrates on the lawn in front of the White House, waving stacks of cash and bottles of champagne. Kendrick Lamar stands near the centre holding a baby. At their feet lies a white judge, his eyes crossed out with an X.</p><p>The image was directed by Lamar and Dave Free, with Vlad Sepetov on art direction, and it carries the album''s arguments about money, power, race and survival in a single frame. Lamar described it more simply: he was "just taking a group of the homies who haven''t seen the world" to the places they had only seen on television. The setting matters. Vice called the White House "a landmark of black oppression", a building raised partly by enslaved labour, and here it becomes a backdrop for people who were never meant to party on its grass.</p><p>The release was as sudden as the image. The album was due on 23 March 2015 but appeared on 15 March, eight days early, apparently because of a mistake at Interscope. The cover''s mix of celebration and threat matched a record that moved through jazz, funk and spoken word, and it remains one of the most debated hip-hop covers of the century. The cover photography is credited to Denis Rouvre and Roberto "retOne" Reyes, with art direction by Dave Free, Kendrick Lamar and Vladimir Sepetov.</p>','#818080','#444243','https://static.wixstatic.com/media/b519fa_96a924778b4a4d4ca27911f9411d5000~mv2.jpg',1500,1500,'7ycBtnsMtyVbbwTfJwRjSP','https://open.spotify.com/album/7ycBtnsMtyVbbwTfJwRjSP','https://music.apple.com/us/album/to-pimp-a-butterfly/1440828886','https://www.youtube.com/results?search_query=Kendrick+Lamar+To+Pimp+a+Butterfly+full+album',false),
('16ced337-6988-44e3-bc1f-2c887f85770f','2014-forest-hills-drive','2014 Forest Hills Drive','J. Cole',2014,'2010s','Dreamville / Roc Nation / Columbia','United States','27d91a37-0b27-477a-b65d-82e9697175da',array['Conscious hip-hop','Southern hip-hop']::text[],'Photography by Anthony Blasko; art and creative direction by Justin Thomas Kay; illustrations by Jason Jägel','<p>The title of J. Cole''s third album is an address: the house in Fayetteville, North Carolina, where he spent his formative years. The family lost it to foreclosure when he was 18, and Cole later bought it back. On the cover he sits on the roof of that house at dusk, looking down into the camera.</p><p>The rooftop shot was Cole''s own idea, and he climbed up to the second story to get it. It was taken by the documentary photographer Anthony Blasko during a five-day shoot in Fayetteville, with art and creative direction by Justin Thomas Kay and illustrations inside the package by Jason Jägel. Kay kept the crew to three people so the sessions stayed relaxed.</p><p>2014 Forest Hills Drive was released on 9 December 2014. It went platinum with no guest features, which became a running joke among fans, and the house on the cover turned into a landmark that fans travel to see.</p>','#282D28','#8D9FB5','https://static.wixstatic.com/media/b519fa_331f8a54f3ed40b7a1fa415ce9adea2b~mv2.jpg',3000,3000,'0UMMIkurRUmkruZ3KGBLtG','https://open.spotify.com/album/0UMMIkurRUmkruZ3KGBLtG','https://music.apple.com/us/album/2014-forest-hills-drive/1600766204','https://www.youtube.com/results?search_query=J.+Cole+2014+Forest+Hills+Drive+full+album',false),
('b67a66c5-0e57-4b14-92f6-1f71f039013a','convoque-seu-buda','Convoque Seu Buda','Criolo',2014,'2010s','Oloko Records','Brazil','2a9002ef-8700-4b4b-bc97-eae22cc36802',array['Brazilian hip-hop','Alternative hip-hop']::text[],'Art direction by Denis Cisma; graphic design by Lucas Rampazzo','<p>Criolo, the São Paulo rapper who rose from the Grajaú district to national fame, followed his breakthrough album Nó na Orelha with a record that mixes rap with samba, Afro-Brazilian rhythms and psychedelia. Its cover is a crowded, colourful collage by art director Denis Cisma and graphic designer Lucas Rampazzo.</p><p>Illustrations, photographs, insects, plants and patterns are stacked together around Criolo''s name, written vertically in tall green letters. Among the pieces is a figure of an official from the Javanese court in Indonesia, one of the borrowed images that give the cover its dreamlike, faraway feel.</p><p>The title means summon your Buddha, an invitation to inner calm in the middle of chaos. Released on 13 November 2014, the album and its experimental collage matched each other, and the cover is often named among the most creative in Brazilian rap.</p>','#988A6C','#BEAA87','https://static.wixstatic.com/media/b519fa_4c4b2cae1bfd40b1bf1abb8372af5265~mv2.jpg',1400,1400,'5xnpDQuOSNPG5IuyqnEqVS','https://open.spotify.com/album/5xnpDQuOSNPG5IuyqnEqVS','https://music.apple.com/br/album/convoque-seu-buda/1690463415','https://www.youtube.com/results?search_query=Criolo+Convoque+Seu+Buda+full+album',false),
('7bc0fdb6-fe20-42be-9831-86879b6e3a98','les-yeux-plus-gros-que-le-monde','Les Yeux plus gros que le monde','Black M',2014,'2010s','Wati B / Jive / Epic','France','2a9002ef-8700-4b4b-bc97-eae22cc36802',array['French hip-hop','Pop rap']::text[],'Artwork and photography by Fifou','<p>Black M, a member of the group Sexion d''Assaut, made his solo debut with a cover that looks straight back to Michael Jackson. Fifou, the photographer and art director behind many of the biggest French rap covers, created the artwork and photography: a dense circus of ornaments, globes, masks, animals and symbols arranged around Black M''s face in the centre.</p><p>The resemblance to Jackson''s 1991 album Dangerous, with its packed gold carnival of images around Jackson''s eyes, was impossible to miss, and it set off a debate about plagiarism. Black M answered that the cover was a big wink to the original, "un gros clin d''œil," an open homage to one of his idols.</p><p>The homage fitted an album whose title means the eyes bigger than the world, about ambition and dreams. Les Yeux plus gros que le monde was released on 31 March 2014.</p>','#1A1619','#3C5E8A','https://static.wixstatic.com/media/b519fa_9264bb560bd948daac52e9a8d7e2b13b~mv2.jpg',1500,1500,'1D2Rs9qcENebbiDR5wk88T','https://open.spotify.com/album/1D2Rs9qcENebbiDR5wk88T','https://music.apple.com/fr/album/les-yeux-plus-gros-que-le-monde/1057641068','https://www.youtube.com/results?search_query=Black+M+Les+Yeux+plus+gros+que+le+monde+full+album',false)
insert into public.covers (id,slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,color,accent_color,image_url,image_width,image_height,spotify_album_id,spotify_url,apple_music_url,youtube_url,featured) values
('83cb1fe5-4fdd-4c81-a54c-4e1df7efd1da','pinata','Piñata','Freddie Gibbs & Madlib',2014,'2010s','Madlib Invazion','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Gangsta rap','Jazz rap']::text[],'Cover photography by Peter Beste; photography by Matthew Scott','<p>Piñata paired Freddie Gibbs, the street rapper from Gary, Indiana, with Madlib, the cult producer from Oxnard, California. The cover shows Gibbs sitting in a neighbourhood park in a black Adidas tracksuit, framed by a loud zebra-print border that turns an ordinary snapshot into something out of a 1970s blaxploitation poster.</p><p>The cover photograph is credited to Peter Beste, the Houston photographer best known for his books documenting Norwegian black metal and the Houston rap scene, with further photography by Matthew Scott. Beste''s documentary eye keeps Gibbs relaxed and unposed, while the border carries the album''s love of vintage soul and film.</p><p>Piñata was released on 18 March 2014 on Madlib''s label Madlib Invazion. It was quickly hailed as one of the best rap albums of the decade, and Gibbs and Madlib followed it with Bandana in 2019.</p>','#191715','#EDEDEC','https://static.wixstatic.com/media/b519fa_4d2a174126a84dca8adc308f50c02cb8~mv2.jpg',1400,1400,'6PhUHgMnUCSCgrjfc2lDF0','https://open.spotify.com/album/6PhUHgMnUCSCgrjfc2lDF0','https://music.apple.com/us/album/pi%C3%B1ata/1705349861','https://www.youtube.com/results?search_query=Freddie+Gibbs+%26+Madlib+Pi%C3%B1ata+full+album',false),
('b89a26a5-a992-40a0-bb27-15ab44eba0f2','run-the-jewels-2','Run the Jewels 2','Run the Jewels',2014,'2010s','Mass Appeal','United States','cac97ec2-47e9-4562-b1b0-ebb5ae534086',array['Alternative hip-hop','Political hip-hop']::text[],'Cover illustration by Nick Gazin; art direction by El-P','<p>Every Run the Jewels album puts the same image on its cover in place of a portrait of the rappers: one hand making a fist and another making a gun. On the second album the two hands are wrapped and glinting in gold, floating on a flat red background.</p><p>The illustrator Nick Gazin drew the first two covers and helped develop the original hand logo, with El-P leading the visuals. El-P has described the group''s design process as an art collective, with Killer Mike, Gazin and the photographer Tim Saccenti each adding pieces. Gazin told The Verge that the image is about coming back after having been beaten down.</p><p>Run the Jewels 2 was released in October 2014, first as a free download, and was named one of the best albums of the year. The fist and gun went on to appear on tattoos, murals and protest signs, and became one of the most recognisable logos in modern rap.</p>','#E22A2A','#5E4920','https://static.wixstatic.com/media/b519fa_86b8453e452643c69d5188a9a62875ce~mv2.jpg',1400,1400,'6WBUyDe1Xy8QRwF6wzhJsY','https://open.spotify.com/album/6WBUyDe1Xy8QRwF6wzhJsY','https://music.apple.com/us/album/run-the-jewels-2/1862913140','https://www.youtube.com/results?search_query=Run+the+Jewels+Run+the+Jewels+2+full+album',false),
('8b9410a1-4b10-4461-9f71-22c5db2bee7f','confundindo-sabios','Confundindo Sábios','Rashid',2013,'2010s','Independent','Brazil','27d91a37-0b27-477a-b65d-82e9697175da',array['Brazilian hip-hop','Conscious hip-hop']::text[],'Art by Marcelo Lima; photography by Enio César','<p>The cover of Rashid''s debut album is a black-and-white photograph of a boy in Brasilândia, in the north zone of São Paulo, pulling a black ski mask up off his own face and grinning underneath it. The art is by Marcelo Lima and the photography by Enio César, and the picture was taken in the neighbourhood itself.</p><p>A ski mask on a boy from the periphery is an image loaded with fear and suspicion in Brazil. Rashid explained the idea directly: "O menino da capa do disco representa a desmarginalização." The boy on the cover stands for de-marginalisation, a child taking off the label society puts on him and showing the face underneath.</p><p>The title, confusing the wise, comes from the biblical idea of the humble outsmarting the learned. Released on 24 September 2013, the album established Rashid as one of the leading voices of São Paulo rap.</p>','#423E3E','#605F5F','https://static.wixstatic.com/media/b519fa_aed0486c76544fb199fba3a9fac36961~mv2.jpg',1476,1476,'73vP5dotg2gtDXVl1VoLYU','https://open.spotify.com/album/73vP5dotg2gtDXVl1VoLYU','https://music.apple.com/us/album/confundindo-s%C3%A1bios/703960320','https://www.youtube.com/results?search_query=Rashid+Confundindo+Sábios+full+album',false),
('d6e9b374-7ffd-4d0a-a565-2b3ea9a53b96','doris','Doris','Earl Sweatshirt',2013,'2010s','Tan Cressida / Columbia','United States','27d91a37-0b27-477a-b65d-82e9697175da',array['Alternative hip-hop','Abstract hip-hop']::text[],'Photography by Jason Dill; art direction and design by Anita Marisa Boriboon; illustrations by Kunle Martins','<p>Earl Sweatshirt became a legend while he was missing. At 16 he disappeared from Odd Future, and fans chanted "Free Earl" until it emerged he had been sent to a therapeutic school in Samoa. Doris, his debut album, was the first full statement after his return, and its cover is a plain, quiet black-and-white photograph of Earl beside a crucifix on a white wall.</p><p>The album credits photography to Jason Dill, the professional skateboarder and photographer, with art direction and design by Anita Marisa Boriboon and illustrations by Kunle Martins, the New York graffiti artist. A loose handwritten scrawl runs across the top of the image.</p><p>Doris was released on 20 August 2013 on Earl''s Tan Cressida label through Columbia, and it debuted at number five in the United States. The stark, homemade-looking cover matched its dense, inward-looking songs.</p>','#DAD2CD','#3A3635','https://static.wixstatic.com/media/b519fa_825eefd6802c41d3b6e40ec3879e6e89~mv2.jpg',1500,1500,'5vRfIDOPJHy3W2wHWbzLlE','https://open.spotify.com/album/5vRfIDOPJHy3W2wHWbzLlE','https://music.apple.com/us/album/doris/669700847','https://www.youtube.com/results?search_query=Earl+Sweatshirt+Doris+full+album',false),
('af9cb3cf-9a19-43d0-bda9-71222c804ff8','my-name-is-my-name','My Name Is My Name','Pusha T',2013,'2010s','GOOD Music / Def Jam','United States','c0217d82-6644-4ea9-99d1-67b7e9dbe7a7',array['East Coast hip-hop','Coke rap']::text[],'Creative direction by Virgil Abloh and Capricorn Clark; art direction by Justin Saunders; photography by Fabien Montique; layouts by Joe Perez and DONDA','<p>The cover of Pusha T''s solo debut on GOOD Music is a black barcode on a plain white field, with no name, no title and no photograph. The team behind it, creative directors Virgil Abloh and Capricorn Clark with art director Justin Saunders, began with the idea of a thumbprint as a mark of identity, and the barcode grew out of it, which The Fader described as "a 21st century version of the thumbprint."</p><p>The goal was something stark and minimal, a product label for a rapper who had spent a career describing the drug trade in the language of business. For the photography, the team looked to Eve Arnold, Gordon Parks and Howard Bingham, and to old Big Daddy Kane images.</p><p>Inside, Fabien Montique''s photographs fill out the story, including a crocodile image Kanye West chose for its eerie, evil feel and a "not equal" sign Pusha painted by hand on glass. Joe Perez and the DONDA design team turned the ideas into layouts. The album was released on 8 October 2013, and its barcode remains one of the starkest covers in modern rap.</p>','#FEFEFE','#111111','https://static.wixstatic.com/media/b519fa_7ca14ee53f3549989d6f90989dd1c156~mv2.jpg',1500,1500,'0IoiCReUTgS8veAp98cHIA','https://open.spotify.com/album/0IoiCReUTgS8veAp98cHIA','https://music.apple.com/us/album/my-name-is-my-name/1440822381','https://www.youtube.com/results?search_query=Pusha+T+My+Name+Is+My+Name+full+album',false),
('170a50e0-54d1-4513-bccc-0d4d1ed5e05a','nothing-was-the-same','Nothing Was the Same','Drake',2013,'2010s','OVO Sound','Canada','6cbdce99-93a5-4ccd-adbc-b5e907e3ee7e',array['Canadian hip-hop','Pop rap']::text[],'Painting by Kadir Nelson; art direction and design by Donald Hearn and Isa Saalabi','<p>Drake wanted a signature painting for Nothing Was the Same, something that did not look like a typical hip-hop cover. He turned to Kadir Nelson, a Southern California artist who had painted the cover of Michael Jackson''s posthumous album Michael. Nelson made several sketches, the two chose one together, and Nelson listened to Drake''s music in the studio as he worked.</p><p>The result came in two versions, sold side by side so buyers could choose. Both are oil paintings of Drake in profile against a cloudy blue sky. One shows him as a child with an afro comb in his hair, the other as an adult wearing a gold chain. Drake said the artwork captured "my most clear, concise thoughts from now" alongside his best memory of his younger self.</p><p>Critics compared the childhood version to the covers of Illmatic, Ready to Die and Tha Carter III, and Complex ranked it the fourth-best cover of 2013. Nelson gave Drake a full-size painting of the cover. The album was released on 24 September 2013. Donald Hearn and Isa Saalabi handled the art direction and design around Nelson''s paintings.</p>','#7BB6DF','#0771B6','https://static.wixstatic.com/media/b519fa_1501cf4231ea4de88d27e984359a3817~mv2.jpg',1500,1500,'3PAv4PLPv9V68fstzIqhyb','https://open.spotify.com/album/3PAv4PLPv9V68fstzIqhyb','https://music.apple.com/us/album/nothing-was-the-same-deluxe/1440829462','https://www.youtube.com/results?search_query=Drake+Nothing+Was+the+Same+full+album',false),
('a39be2e3-3381-4d01-93b2-4c336149eea0','unknown-death-2002','Unknown Death 2002','Yung Lean',2013,'2010s','YEAR0001','Sweden','4450e9cf-43d6-481d-b606-2e75cef9e7f9',array['Cloud rap','Alternative hip-hop']::text[],null,'<p>The cover of Unknown Death 2002 is a slab of dark grey marble, streaked with white veins, with Yung Lean''s name and the title in thin yellow letters and the Japanese characters for "unknown death."</p><p>Yung Lean was a teenager in Stockholm when he and his Sad Boys collaborators Yung Sherman and Yung Gud made this mixtape. Released on 16 August 2013, it mixed hazy, melancholy beats with internet imagery, Arizona Iced Tea and anime, and songs like "Ginseng Strip 2002" went viral.</p><p>The cold stone and the Japanese text capture the album''s strange, sad internet mood. Yung Lean became a cult figure, and the cloud rap and online aesthetics he helped popularise shaped artists from Bladee and Drain Gang to a whole generation of SoundCloud rappers.</p>','#1D2329','#869499','https://static.wixstatic.com/media/b519fa_cd0fa1d90a71473cbc04bcca1279af8a~mv2.jpg',3000,3000,'2u07QZy2B5vzr0s5pBbKga','https://open.spotify.com/album/2u07QZy2B5vzr0s5pBbKga','https://music.apple.com/nz/album/unknown-death-2002/1616529900','https://www.youtube.com/results?search_query=Yung+Lean+Unknown+Death+2002+full+album',false),
('a3503580-c4d7-466c-bc08-877236331a67','yeezus','Yeezus','Kanye West',2013,'2010s','Def Jam Recordings','United States','c0217d82-6644-4ea9-99d1-67b7e9dbe7a7',array['Industrial rap','Experimental hip-hop']::text[],'Artwork by DONDA, Kanye West''s creative company, with Virgil Abloh','<p>Yeezus has no cover image in the usual sense. The physical CD came in a clear jewel case with no artwork, sealed with a strip of red tape and a sticker on the back carrying the sample credits and barcode. The digital cover simply shows that object: a bare disc in a transparent case with a red strip along one edge.</p><p>West wanted every bit of attention on the music, and he later explained the idea to the BBC''s Annie Mac: "this is an open casket for the CD." Virgil Abloh, who worked on the project through West''s creative company DONDA, said the image "represented the death of a CD," a tribute to a format they had grown up with, and added, "we kinda outdid ourselves in a way."</p><p>The minimal design drew comparisons. The Source noted its resemblance to a 2001 packaging concept by Peter Saville for New Order''s single "Crystal," and designer David Rudnick said it was noticeably similar to his artwork for a 2011 release by Boys Noize and Erol Alkan. Yeezus was released on 18 June 2013.</p>','#F6F8F7','#FA140C','https://static.wixstatic.com/media/b519fa_540d8c8bfe1b45be88efbaa1bfd05be7~mv2.jpg',1500,1500,'7D2NdGvBHIavgLhmcwhluK','https://open.spotify.com/album/7D2NdGvBHIavgLhmcwhluK','https://music.apple.com/us/album/yeezus/1440873068','https://www.youtube.com/results?search_query=Kanye+West+Yeezus+full+album',false),
('5c11edf1-adb4-457d-9b5f-1d1e60952939','finally-rich','Finally Rich','Chief Keef',2012,'2010s','Glory Boyz / Interscope','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Drill','Chicago hip-hop']::text[],null,'<p>Chief Keef, then 17, appears on the cover of his debut album with long dreadlocks, blowing smoke against a dark background, one hand raised, with his name in large metallic letters below.</p><p>Keef''s raw, chanted songs from Chicago''s South Side, recorded with producers like Young Chop, spread online in 2012, and "I Don''t Like" was remixed by Kanye West. Finally Rich, released on 18 December 2012, carried "Love Sosa" and "I Don''t Like" and brought Chicago drill to the world.</p><p>The young, defiant portrait matches the moment a teenager from the block became a national figure. Drill went on to spread to London, Brooklyn and beyond, and the producers and rappers of those scenes have pointed back to Finally Rich as the starting point.</p>','#100F0E','#CEC3BA','https://static.wixstatic.com/media/b519fa_53663b9c37124fe19473865b4bc7531a~mv2.jpg',1500,1500,'108j4R9oEcFUaVRzE8RZKI','https://open.spotify.com/album/108j4R9oEcFUaVRzE8RZKI','https://music.apple.com/us/album/finally-rich/1440853396','https://www.youtube.com/results?search_query=Chief+Keef+Finally+Rich+full+album',false),
('7fc74d01-073a-4c47-b8b5-c509409c6e79','good-kid-m-a-a-d-city','good kid, m.A.A.d city','Kendrick Lamar',2012,'2010s','Top Dawg Entertainment','United States','52e1479f-82f9-46b7-86e4-f22d676e06cc',array['West Coast hip-hop','Conscious rap']::text[],'Art direction by Kendrick Lamar; photography by Dan Monick; cover handwriting by ScHoolboy Q','<p>The cover of good kid, m.A.A.d city is an old family snapshot. It shows Kendrick Lamar as a small child with two of his uncles and his grandfather, and it carries the line "a short film by Kendrick Lamar," handwritten for the sleeve by ScHoolboy Q.</p><p>The adults'' eyes are blacked out and Kendrick''s are left visible. He explained that the story is told through his eyes, drawn from his own experiences growing up in Compton. The details are telling: the uncle holding the young Kendrick is throwing a Crips gang sign, and a poster on the wall above shows Kendrick with his father.</p><p>Complex named it the best album cover of 2012, and Pitchfork included it among the year''s 20 best. Kendrick took the art direction himself, with photography by Dan Monick. The album was released on 22 October 2012.</p>','#7B7F63','#ACA991','https://static.wixstatic.com/media/b519fa_04811e7175a34065a1957470a56ae6db~mv2.jpg',1500,1500,'6PBZN8cbwkqm1ERj2BGXJ1','https://open.spotify.com/album/6PBZN8cbwkqm1ERj2BGXJ1','https://music.apple.com/us/album/good-kid-m-a-a-d-city/1471263898','https://www.youtube.com/results?search_query=Kendrick+Lamar+good+kid,+m.A.A.d+city+full+album',false),
('576f378c-2822-41c1-af3d-a85f77be866a','the-money-store','The Money Store','Death Grips',2012,'2010s','Third Worlds / Epic','United States','cac97ec2-47e9-4562-b1b0-ebb5ae534086',array['Experimental hip-hop','Industrial hip-hop']::text[],'Artwork by Sua Yoo','<p>Death Grips, the Sacramento trio led by the shouting MC Ride, made a major-label debut as abrasive as anything rap had produced. The cover matches it: a black-and-white image of a masochist with the band''s name carved into her chest, held on a leash by a smoking sadist in a cap.</p><p>The image is by the artist Sua Yoo, who had worked with the band before. It first appeared in a zine, and the carved "Death Grips" lettering was added later for the album. The clean version, the one shown here and on streaming services, covers the figure''s chest with a white bar carrying the album''s title.</p><p>The Money Store was released in April 2012 on Epic, and its distorted, aggressive sound made it one of the most influential experimental rap records of its decade. The band reused the same artwork in 2015 for their soundtrack album Fashion Week.</p>','#FBFBFB','#2C2927','https://static.wixstatic.com/media/b519fa_0dab230b8c1449dface9c280a9227d8b~mv2.jpg',600,600,'1PQDjdBpHPikAodJqjzm6a','https://open.spotify.com/album/1PQDjdBpHPikAodJqjzm6a','https://music.apple.com/us/album/the-money-store/515449028','https://www.youtube.com/results?search_query=Death+Grips+The+Money+Store+full+album',false),
('f2d34092-de22-4b4b-b081-fa7f61d38cec','live-love-a-ap','LIVE.LOVE.A$AP','A$AP Rocky',2011,'2010s','A$AP Worldwide / Polo Grounds / RCA','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Cloud rap','East Coast hip-hop']::text[],null,'<p>A$AP Rocky stands in front of an American flag in black and white on the cover of his first mixtape, in a plaid shirt and a cap, looking straight into the camera with the title running down the side.</p><p>The Harlem rapper mixed New York swagger with the slowed-down, syrupy sound of Houston and the hazy production of Clams Casino on songs like "Peso" and "Purple Swag." Released for free on 31 October 2011, the mixtape helped Rocky sign a major-label deal and made A$AP Mob one of the most talked-about crews in rap.</p><p>The colourless flag gives the patriotic symbol a cooler, darker edge, a fitting image for a rapper who blended regional styles into something new and helped turn rap fashion into high fashion in the 2010s.</p>','#363636','#DFDFDF','https://static.wixstatic.com/media/b519fa_a148bb444d3940f0b23cba6e35e318f2~mv2.jpg',3000,3000,'4l6EPpP9hjQrLb8qNB9eC5','https://open.spotify.com/album/4l6EPpP9hjQrLb8qNB9eC5','https://music.apple.com/us/album/live-love-a%24ap/1591647717','https://www.youtube.com/results?search_query=A%24AP+Rocky+LIVE.LOVE.A%24AP+full+album',false),
('6d21d545-68b0-4025-b0cd-f885f919518c','take-care','Take Care','Drake',2011,'2010s','Young Money / Cash Money / Universal Republic','Canada','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Canadian hip-hop','Alternative R&B']::text[],'Artwork and design by Martin "Drop" Wong; photography by Hyghly Alleyne and Lamar Taylor','<p>On the cover of his second album, Drake sits alone at a table in a dark, wood-panelled room, slumped over a golden goblet, with a tall candlestick and gold ornaments around him. It is an image of a man surrounded by wealth with no one to share it with, which suits an album full of late-night regret and lonely success.</p><p>Drake posted the official artwork on his October''s Very Own blog on 23 September 2011. Listeners quickly pointed out its close resemblance to Labi Siffre''s 1975 album Remember My Song, which also shows a man brooding at a table, and the comparison has followed the cover ever since. Drake has sampled and championed older soul records throughout his career.</p><p>The liner notes credit Martin "Drop" Wong for artwork and design, with photography by Hyghly Alleyne and Lamar Taylor. Take Care was released on 15 November 2011 and won the Grammy for Best Rap Album, and its gloomy gold portrait remains one of the most recognisable images of his career.</p>','#0A0C0E','#845A3C','https://static.wixstatic.com/media/b519fa_43cb932528a04051a4a294cc6a8c076a~mv2.jpg',1500,1500,'6X1x82kppWZmDzlXXK3y3q','https://open.spotify.com/album/6X1x82kppWZmDzlXXK3y3q','https://music.apple.com/us/album/take-care-deluxe-version/1440642493','https://www.youtube.com/results?search_query=Drake+Take+Care+full+album',false),
('a7a2eeac-d9ba-4959-b49a-d1d35d2c6873','watch-the-throne','Watch the Throne','Jay-Z & Kanye West',2011,'2010s','Roc-A-Fella Records','United States','c0217d82-6644-4ea9-99d1-67b7e9dbe7a7',array['East Coast hip-hop','Pop rap']::text[],'Artwork by Riccardo Tisci for Givenchy','<p>Jay-Z and Kanye West asked Riccardo Tisci, then creative director of Givenchy, to design and direct the artwork for Watch the Throne, after he had already created the cover for their 2010 single "H.A.M." The cover is a dense field of gold, heavily gilded and perfectly symmetrical, which a Givenchy representative described as looking embroidered, while the inside artwork appears painted and printed.</p><p>Tisci filled the design with his signature motifs: geometric patterns, animal faces and surreal religious imagery, arranged to give the package a ritualistic, majestic feel. Its bold colour and sharp angles were meant to reflect the masculinity of the two rappers, and the gold suits an album about luxury and success at the very top.</p><p>"I am honored to have been asked to be part of this incredible music moment with such amazing artists," Tisci said. "We share the same way of working: like a family." The album was released on 8 August 2011.</p>','#BFA372','#937547','https://static.wixstatic.com/media/b519fa_604e8b0c1d624756b428726df53706c4~mv2.jpg',1500,1500,'0OcMap99vLEeGkBCfCwRwS','https://open.spotify.com/album/0OcMap99vLEeGkBCfCwRwS','https://music.apple.com/us/album/watch-the-throne/1440848092','https://www.youtube.com/results?search_query=Jay-Z+and+Kanye+West+Watch+the+Throne+full+album',false),
('edf23b58-2664-457f-817d-7b5c0f9074db','my-beautiful-dark-twisted-fantasy','My Beautiful Dark Twisted Fantasy','Kanye West',2010,'2010s','Def Jam / Roc-A-Fella','United States','6cbdce99-93a5-4ccd-adbc-b5e907e3ee7e',array['Art pop','Progressive rap','Maximalism']::text[],'Paintings by George Condo','<p>George Condo knew more about old-school rap than about Kanye West when West turned up at his New York studio in 2010 and played him the new album for hours. Over the next few days the painter produced eight or nine works in response. West had one specific request: a phoenix. What he got was stranger. The main cover, framed by a thick red border, shows West slumped on a blue couch with a green beer bottle while a nude, armless, winged creature with a long spotted tail straddles him. Condo called her "a kind of fragment, between a sphinx, a phoenix, a haunting ghost, a harpy."</p><p>According to Condo, the provocation was the plan. West wanted an image explicit enough for retailers to refuse, and in October 2010 he tweeted "Yoooo they banned my album cover!!!!! Banned in the USA!!!", asking why Nirvana''s naked baby was acceptable when he could not have "a PAINTING of a monster with no arms and a polka dot tail and wings." Walmart said it had never rejected the record. Either way, the stunt worked: the cover became news before the music was heard.</p><p>The album ended up with six faces. Condo painted five covers, all of them sold with the record: the couch scene; a pale ballerina in a black tutu holding a drink, first meant for the single "Runaway"; a Cubist portrait of West with four mouths full of bulging and gold teeth; his crowned, severed head pierced by a sword against a cloudy sky; and The Priest, a drab portrait of West dressed as a reverend. The sixth is the version shown here, a pixelated censor of the main painting used on some shipped copies and on the digital release. Billboard later ranked the artwork the 30th best album cover of all time.</p>','#EC2540','#787862','https://static.wixstatic.com/media/b519fa_2abf2ce5af574926b556d049e4ed98de~mv2.jpg',1500,1500,'20r762YmB5HeofjMCiPMLv','https://open.spotify.com/album/20r762YmB5HeofjMCiPMLv','https://music.apple.com/us/album/my-beautiful-dark-twisted-fantasy/1440742903','https://www.youtube.com/results?search_query=Kanye+West+My+Beautiful+Dark+Twisted+Fantasy+full+album',false),
('15d6cc28-8f0b-4b7c-89de-7a4714151f9b','man-on-the-moon-the-end-of-day','Man on the Moon: The End of Day','Kid Cudi',2009,'2000s','Dream On / GOOD Music / Universal Motown','United States','cac97ec2-47e9-4562-b1b0-ebb5ae534086',array['Alternative hip-hop','Psychedelic rap']::text[],'Illustrations by Bill Sienkiewicz; art direction and design by Scott Sandler','<p>Kid Cudi''s debut album is a concept record about dreams, loneliness and escape, and its cover makes him part of the sky. His face in profile dissolves into a huge glowing moon in shades of orange, red and violet.</p><p>The illustrations are by Bill Sienkiewicz, the celebrated comic book artist known for his painterly work on Marvel titles such as Elektra: Assassin and The New Mutants, with art direction and design by Scott Sandler. Sienkiewicz''s airbrushed, dreamlike style gave the album the feel of a cosmic comic, a fitting look for a record built as a journey through a single night''s dream.</p><p>Man on the Moon: The End of Day was released on 15 September 2009. Songs like "Day ''n'' Nite" and "Pursuit of Happiness" made Cudi a voice for listeners dealing with depression, and the moon became the symbol of a trilogy he completed in 2020.</p>','#EA7B5D','#804076','https://static.wixstatic.com/media/b519fa_a2550f30917c4c62af3b46c6df93d857~mv2.jpg',3000,3000,'47y3PbX8oIDCkYAFylCJz0','https://open.spotify.com/album/47y3PbX8oIDCkYAFylCJz0','https://music.apple.com/us/album/man-on-the-moon-the-end-of-day/1440744775','https://www.youtube.com/results?search_query=Kid+Cudi+Man+on+the+Moon%3A+The+End+of+Day+full+album',false),
('baaf0efc-37b0-4907-a272-4b4469fe29d7','808s-heartbreak','808s & Heartbreak','Kanye West',2008,'2000s','Roc-A-Fella / Def Jam','United States','c0217d82-6644-4ea9-99d1-67b7e9dbe7a7',array['Electropop','Alternative hip-hop']::text[],null,'<p>The cover of 808s & Heartbreak is almost empty: a deflated red heart-shaped balloon, crumpled and lying on a pale grey background, with the title and Kanye''s name in tiny pastel type.</p><p>Kanye made the album after the death of his mother, Donda West, in 2007 and the end of his engagement. Released on 24 November 2008, it swapped rapping for singing through Auto-Tune over cold Roland TR-808 drums, and songs like "Love Lockdown" and "Heartless" shocked fans who expected the soul samples of his first three records.</p><p>The deflated heart turned the title into one simple image of loss. The album''s sound went on to shape a generation of rappers who sang about their feelings, from Drake and Kid Cudi to Travis Scott and the emo rap of the late 2010s.</p>','#D8D9D1','#B73F39','https://static.wixstatic.com/media/b519fa_1f9daca0d4dd4430829420c52fd3e356~mv2.jpg',1400,1400,'3WFTGIO6E3Xh4paEOBY9OU','https://open.spotify.com/album/3WFTGIO6E3Xh4paEOBY9OU','https://music.apple.com/us/album/808s-heartbreak/1441410287','https://www.youtube.com/results?search_query=Kanye+West+808s+%26+Heartbreak+full+album',false),
('e7d09a82-4c55-4283-8052-61d475f99039','tha-carter-iii','Tha Carter III','Lil Wayne',2008,'2000s','Cash Money Records','United States','52e1479f-82f9-46b7-86e4-f22d676e06cc',array['Southern hip-hop','Pop rap']::text[],'Creative direction by Sandy Brummels; art direction by Scott Sandler','<p>Art director Scott Sandler was asked to draft the Tha Carter III cover in 2008, when Lil Wayne was widely expected to break through. He submitted many ideas, including one he assumed would be thrown out: a baby photo of Wayne with his adult face tattoos added. That was the one chosen.</p><p>The picture shows the infant Dwayne Carter in a smart little suit, staring at the camera with tattoos across his face. Sandler explained the humour behind it: "Rap at that time was very serious. Nobody really had much of a sense of humor." The cover also nods to Nas''s Illmatic and the Notorious B.I.G.''s Ready to Die, which both used childhood images.</p><p>The album sold about a million copies in its first week and won three Grammys. For its tenth anniversary, Spotify had Chance the Rapper, Wiz Khalifa, Migos, Lil Yachty and Lil Uzi Vert recreate the cover with their own baby photos, and Wayne''s childhood photo has returned on later records, including Tha Carter VI in 2025. Sandy Brummels was the creative director on the package, with Scott Sandler as art director.</p>','#080807','#8E7461','https://static.wixstatic.com/media/b519fa_cba2d836d9c34d358f99081809c010f1~mv2.jpg',906,900,'1Do3y8IAcbYOToYQJnGwSO','https://open.spotify.com/album/1Do3y8IAcbYOToYQJnGwSO','https://music.apple.com/us/album/tha-carter-iii/1440737099','https://www.youtube.com/results?search_query=Lil+Wayne+Tha+Carter+III+full+album',false),
('0746700c-d9e1-414a-ba75-0414a5703dd3','untitled','Untitled','Nas',2008,'2000s','Def Jam / Columbia','United States','27d91a37-0b27-477a-b65d-82e9697175da',array['East Coast hip-hop','Political hip-hop']::text[],'Photography by Mieeno Peluce; illustration and design by Tavon Sampson and Eric Altenburger','<p>Nas planned to call his ninth album by the most charged slur in the English language, as a statement about who owns that word. The title drew a storm of protest. Some retailers threatened to refuse it, and New York politicians including Hakeem Jeffries pressed the state pension fund over its investment in the album''s distributor. On 19 May 2008 the title was dropped.</p><p>The cover kept the original idea alive. Mieeno Peluce photographed Nas from behind, shirtless, his back covered in raised whipping scars that form a large letter N, the mark of a lash turned into an initial. Tavon Sampson and Eric Altenburger handled the illustration and design, and Nas''s name sits in red in the corner.</p><p>The image ties the withdrawn title directly to the history of slavery, so the album says with a picture what it was no longer allowed to say with words. As Nas put it, "the people will always know what the real title of this album is and what to call it." The album, officially untitled, was released on 15 July 2008 and debuted at number one.</p>','#050607','#7F4B4B','https://static.wixstatic.com/media/b519fa_506aa41c509646988a83a98b47d91fe9~mv2.jpg',3000,3000,'5dMmFu9NCxSjDk3ekggogc','https://open.spotify.com/album/5dMmFu9NCxSjDk3ekggogc','https://music.apple.com/us/album/nas/1443258592','https://www.youtube.com/results?search_query=Nas+Untitled+full+album',false),
('5a01f708-9049-4880-8444-4ecee149793e','graduation','Graduation','Kanye West',2007,'2000s','Roc-A-Fella Records','United States','cac97ec2-47e9-4562-b1b0-ebb5ae534086',array['Pop rap','Progressive rap']::text[],'Art direction by Takashi Murakami and Kanye West; artwork by Takashi Murakami','<p>For Graduation, Kanye West visited Takashi Murakami''s Kaikai Kiki studio in Asaka, Japan, and the two worked together on the art direction. "The cover is based on Kanye''s theme of student life. School," Murakami said. The artwork redraws the Dropout Bear as a cartoon in Murakami''s bright, pastel Superflat style, influenced by manga and anime.</p><p>The images tell a story. On a rainy morning the bear rushes to a graduation ceremony at a fictional college in Universe City, a futuristic metropolis, and on the back cover he is shot out of a cannon into the sky. Production took several weeks, with West constantly emailing new ideas to Murakami and his team.</p><p>Rolling Stone named it the fifth-best album cover of 2007. Murakami later turned the artwork into animation for the "Good Morning" video and went on to create the cover of Kids See Ghosts in 2018. Graduation was released on 11 September 2007.</p>','#A14A84','#CCC4B2','https://static.wixstatic.com/media/b519fa_51d31d2dbda644c28597269655f2ad48~mv2.jpg',1500,1500,'4SZko61aMnmgvNhfhgTuD3','https://open.spotify.com/album/4SZko61aMnmgvNhfhgTuD3','https://music.apple.com/us/album/graduation/1451901307','https://www.youtube.com/results?search_query=Kanye+West+Graduation+full+album',false),
('0c216bf5-f1ea-4d89-acad-2632bfc0029a','donuts','Donuts','J Dilla',2006,'2000s','Stones Throw Records','United States','55ba40d7-5946-4af0-878f-e0d24ecb6f71',array['Instrumental hip-hop','Abstract hip-hop']::text[],'Photography (video still) by Andrew Gura; design by Jeff Jank','<p>The cover of Donuts is a frame from a videotape. In 2005 the director Andrew Gura was filming at the shoot for MED''s "Push" video when he caught J Dilla in a cap with a Detroit D and a striped shirt, looking down and breaking into a wide smile. Stones Throw designer Jeff Jank turned that still into the sleeve, with nothing but the name and title above it.</p><p>Dilla was already very ill. Much of the album was assembled while he was in and out of Cedars-Sinai hospital in Los Angeles, and it was released on 7 February 2006, his 32nd birthday. He died three days later, on 10 February, from complications of TTP and lupus. A blurry, joyful moment from a video set became the last image of him most fans would see.</p><p>His mother, Maureen "Ma Dukes" Yancey, said the picture perfectly captured his spirit. Donuts has since become one of the most influential instrumental hip-hop records ever made, and the soft, grainy video still on its front is now one of the most recognisable portraits in the music.</p>','#191312','#3E2F27','https://static.wixstatic.com/media/b519fa_900f4582694649b283f39f300cd9645f~mv2.jpg',3000,3000,'5fMlysqhFE0itGn4KezMBW','https://open.spotify.com/album/5fMlysqhFE0itGn4KezMBW','https://music.apple.com/us/album/donuts/108233171','https://www.youtube.com/results?search_query=J+Dilla+Donuts+full+album',false),
('5e335902-9f55-403b-896d-6745982538e8','ouest-side','Ouest Side','Booba',2006,'2000s','Tallac Records / Barclay','France','818f66a4-a51e-4b8b-b515-691d9aba254d',array['French hip-hop','Gangsta rap']::text[],'Concept and photography by Armen','<p>Booba''s third album cover shows the rapper in a vest, his heavily tattooed arm raised as he peers out through the slats of a window blind, ready for whatever is coming. The idea came from the photographer Armen, who also shot it, and it is a deliberate homage to one of the most famous images of the civil rights era.</p><p>The reference is the 1964 photograph of Malcolm X holding a rifle as he looks out of his window. Armen knew that KRS-One had already reused the image for Boogie Down Productions, and he suggested a French version to Booba, who was won over immediately. Booba''s picture changes the weapon, the gaze and the clothes, while keeping the watchful pose.</p><p>VICE France described the result as arrogant, provocative and divisive, which suits Booba''s public image. Ouest Side, named after his home turf of Boulogne in the west of Paris, was released on 13 February 2006 and became one of his best-selling records.</p>','#030405','#495558','https://static.wixstatic.com/media/b519fa_8a365c9f26064c769e9afaea0065fcf3~mv2.jpg',3000,3000,'5DEorR03yrZwQHhfem7KV2','https://open.spotify.com/album/5DEorR03yrZwQHhfem7KV2','https://music.apple.com/fr/album/ouest-side/1442232307','https://www.youtube.com/results?search_query=Booba+Ouest+Side+full+album',false),
('860477fa-b79d-40db-b72e-a67e60ecabd9','late-registration','Late Registration','Kanye West',2005,'2000s','Roc-A-Fella / Def Jam','United States','27d91a37-0b27-477a-b65d-82e9697175da',array['Chicago hip-hop','Chipmunk soul']::text[],'Art direction and packaging design by Morning Breath, Inc.; creative direction by Louis Marino; photography by Sarah A. Friedman and Kris Yiengst','<p>Kanye West''s second album continues the college story he began with The College Dropout. On the cover his mascot, the Dropout Bear, stands at the size of a small child between two huge wooden doors at Princeton University, dressed in a blazer with a school crest, a tiny figure at the entrance of an institution.</p><p>The art direction and packaging were designed by the Brooklyn studio Morning Breath, Inc., with creative direction by Louis Marino and photography by Sarah A. Friedman and Kris Yiengst. The bear, first drawn by the designer Sam Hansen for the debut, was redesigned for this album with googly eyes and perky ears, the first of several makeovers it would get on Kanye''s records.</p><p>Late Registration was released on 30 August 2005 and won the Grammy for Best Rap Album. The bear went on to its graduation two years later, on a cover by Takashi Murakami, closing the trilogy that the Princeton doors had opened.</p>','#0A0505','#AABCC7','https://static.wixstatic.com/media/b519fa_f096b55440734336a062e146fe6ffe29~mv2.jpg',1423,1412,'0Ds6i3h0F9RcYIKAD5Olum','https://open.spotify.com/album/0Ds6i3h0F9RcYIKAD5Olum','https://music.apple.com/us/album/late-registration/1440668749','https://www.youtube.com/results?search_query=Kanye+West+Late+Registration+full+album',false),
('ae6fa632-a61b-4c49-98d5-653d0f2ca77c','modal-soul','Modal Soul','Nujabes',2005,'2000s','Hydeout Productions','Japan','6cbdce99-93a5-4ccd-adbc-b5e907e3ee7e',array['Jazz rap','Instrumental hip-hop']::text[],null,'<p>The cover of Modal Soul is an abstract painting of soft red, blue and white blocks, like a weathered wall or a sunset over water, with the title in small type in the lower corner.</p><p>Nujabes, the Tokyo producer Jun Seba, built gentle, piano and jazz-driven hip-hop that reached the world through the anime Samurai Champloo. Modal Soul, released on 11 November 2005, includes "Feather" with Cise Starr and Akin and "Luv(sic) Part 3" with Shing02.</p><p>The quiet, painterly cover matches music made for calm reflection. Nujabes died in a car accident in 2010, and his sound became the foundation of the lo-fi hip-hop playlists and live streams that millions now study and relax to.</p>','#C44D42','#C97060','https://static.wixstatic.com/media/b519fa_19cd2d67519e4d16b26c82f86149e1b0~mv2.jpg',1700,1484,'1RJDe9Eo8473Kg4pdUVGDM','https://open.spotify.com/album/1RJDe9Eo8473Kg4pdUVGDM','https://music.apple.com/us/album/modal-soul/1078914477','https://www.youtube.com/results?search_query=Nujabes+Modal+Soul+full+album',false),
('d2468756-0905-4020-a9bb-5d215215ba70','peines-de-maures-arc-en-ciel-pour-daltoniens','Peines de Maures / Arc-en-ciel pour daltoniens','La Caution',2005,'2000s','Kerozen Music','France','52e1479f-82f9-46b7-86e4-f22d676e06cc',array['French hip-hop','Alternative hip-hop']::text[],'Artwork by Hi-Tek; photography by Nicolas Despis','<p>La Caution is a duo of two brothers from Noisy-le-Sec, Hi-Tek and Nikkfurie, and the cover of their second album is an old photo of the two of them as small children, posed side by side in front of a flowered wallpaper with serious faces. The group''s logo floats across the top in curling white letters.</p><p>Slate.fr, writing about the many childhood photos on rap covers, described it as the kind of picture you could imagine hanging proudly in the family living room. The double title adds a second layer: Peines de Maures is a pun on "peine de mort," the death penalty, and on the Moors, while Arc-en-ciel pour daltoniens means a rainbow for the colour-blind.</p><p>The artwork is credited to Hi-Tek himself, with photography by Nicolas Despis. Released on 17 October 2005 on Kerozen Music, the album is one of the most inventive records in French alternative rap, and its family portrait keeps the brothers'' story at the centre.</p>','#0A0404','#BB9780','https://static.wixstatic.com/media/b519fa_0cd25fddee7b44099c147f5e523b8a00~mv2.jpg',2400,2400,'3t7jR4CHdzu4zLLcpQW3Yr','https://open.spotify.com/album/3t7jR4CHdzu4zLLcpQW3Yr','https://music.apple.com/us/album/peines-de-maures-arc-en-ciel-pour-daltoniens/963222169','https://www.youtube.com/results?search_query=La+Caution+Peines+de+Maures+Arc-en-ciel+pour+daltoniens+full+album',false),
('8635ecd6-77e7-410d-ad05-796113274ce2','tha-carter-ii','Tha Carter II','Lil Wayne',2005,'2000s','Cash Money / Universal','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Southern hip-hop','New Orleans hip-hop']::text[],null,'<p>Lil Wayne sits shirtless on the front of a luxury car on the cover of Tha Carter II, in a crisp black-and-white photograph, his tattoos on show, with the title written in elegant script at the top.</p><p>Released in December 2005, a few months after Hurricane Katrina devastated his home city of New Orleans, Tha Carter II marked the start of Wayne''s claim to be "the best rapper alive." Songs like "Fireman" and "Hustler Musik" showed a sharper, more inventive rapper, and his run of mixtapes in the years that followed made him the most influential voice in rap.</p><p>The relaxed, regal pose fits the album''s swagger. The black-and-white photo gave a classic look to a rapper who had grown up on Cash Money as a teenager, and the cover marked his move from child star to king of the label.</p>','#ACAAAF','#232227','https://static.wixstatic.com/media/b519fa_333dc443805b458585fd837370eebfe1~mv2.jpg',1500,1488,'5qyUw6x9fjZPoQHUwuDu39','https://open.spotify.com/album/5qyUw6x9fjZPoQHUwuDu39','https://music.apple.com/us/album/tha-carter-ii/1443918957','https://www.youtube.com/results?search_query=Lil+Wayne+Tha+Carter+II+full+album',false),
('50858662-ac41-4a4c-9c85-5f0a851e671c','babylon-by-gus-vol-1-o-ano-do-macaco','Babylon by Gus, Vol. 1: O Ano do Macaco','Black Alien',2004,'2000s','Deckdisc','Brazil','52e1479f-82f9-46b7-86e4-f22d676e06cc',array['Brazilian hip-hop','Alternative hip-hop']::text[],'Cover by Ricardo Fernandes','<p>Black Alien, the rapper Gustavo Ribeiro from Niterói, had already made his name in the group Planet Hemp before his solo debut. For its cover, the designer Ricardo Fernandes used a childhood photo of the rapper, a smiling curly-haired boy, set against warm vintage orange and gold, with his name written across the top like an old soft-drink logo.</p><p>The choice was a nod to Nas''s Illmatic, the 1994 album whose cover put Nas''s own childhood photo over a picture of his neighbourhood. Black Alien''s version carries the same idea, the boy who would become the rapper, and roots the album in where he came from.</p><p>The title combines Babylon with his nickname Gus and with the Chinese Year of the Monkey. Released on 8 September 2004 by Deckdisc, the album is considered one of the best Brazilian rap records of the 2000s.</p>','#E5930F','#8C3A2E','https://static.wixstatic.com/media/b519fa_866778a564bd4cab95adcddb76b3c24d~mv2.jpg',1500,1500,'5J9RW8lwdU6dIU2vdfbI7s','https://open.spotify.com/album/5J9RW8lwdU6dIU2vdfbI7s','https://music.apple.com/us/album/babylon-by-gus-vol-1-o-ano-do-macaco/977460213','https://www.youtube.com/results?search_query=Black+Alien+Babylon+by+Gus,+Vol.+1+O+Ano+do+Macaco+full+album',false),
('f35a8f5d-c652-4648-b175-6ab9d661c1cf','la-fierte-des-notres','La Fierté des nôtres','Rohff',2004,'2000s','Delabel','France','818f66a4-a51e-4b8b-b515-691d9aba254d',array['French hip-hop','Hardcore hip-hop']::text[],'Photography by Jonathan Mannion; artwork by Funcographics','<p>Rohff, the rapper from Vitry-sur-Seine, sits in a white tracksuit and sneakers on top of the Arc de Triomphe, Paris''s monument to national glory, looking down at the camera with the avenue stretching away behind him. The photograph was taken by Jonathan Mannion, the American photographer behind covers for Jay-Z, DMX and Eminem, with artwork by Funcographics.</p><p>Rohff explained the image in a June 2004 interview on Skyrock. He said the Arc de Triomphe is France''s greatest pride, and that putting himself on top of it was meant to grab attention and to say that people matter more than monuments. The title, the pride of our people, made it a statement on behalf of the suburbs he came from.</p><p>La Fierté des nôtres was released on 18 June 2004, and VICE France later called it the best album of his career. The picture of a young man from the banlieue enthroned on the Arc became one of the most famous images in French rap.</p>','#595E60','#B9BCB6','https://static.wixstatic.com/media/b519fa_c8d6d4290bae4ad78b84d9cb77708621~mv2.jpg',1400,1400,'5Cp07JiZnqruQBNZb88OCf','https://open.spotify.com/album/5Cp07JiZnqruQBNZb88OCf','https://music.apple.com/fr/album/la-fiert%C3%A9-des-n%C3%B4tres/693103816','https://www.youtube.com/results?search_query=Rohff+La+Fierté+des+nôtres+full+album',false),
('7989f8b3-05bb-4d9b-919a-9a9ce2e051e7','madvillainy','Madvillainy','Madvillain',2004,'2000s','Stones Throw Records','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Alternative hip-hop','Jazz rap','Experimental hip-hop']::text[],'Photography by Eric Coleman; design by Jeff Jank','<p>MF DOOM spent his career hiding behind a metal mask, and the cover of Madvillainy put that mask in close-up. Photographer Eric Coleman shot DOOM at the Stones Throw house in Los Angeles, and the label''s art director Jeff Jank turned the picture into a grainy black-and-white square. The mask fills the frame, its cold metal catching the light, while the man behind it stays unreadable.</p><p>Jank wanted a picture of the man behind the mask. "I really wanted to get a shot of him on the cover, just to make a definitive ''Doom cover''," he said. He drew on the cover of King Crimson''s In the Court of the Crimson King, and only after finishing noticed that his design also resembled Madonna''s debut album. He kept it anyway and called the result the "rap version of Beauty and the Beast."</p><p>The last touch was a small orange square in the top right corner, added because the artwork "needed something distinctive," Jank said, comparing it to the orange letter on that Madonna sleeve. Released on 23 March 2004, the album became a cult classic and the cover became an icon. Marvel paid tribute in 2015 with a variant cover of The Mighty Thor showing Jane Foster behind the mask, with Thor''s hammer in an orange square.</p>','#E3E3E3','#A59F9B','https://static.wixstatic.com/media/b519fa_187545a2ecee4b57aa9fc1bbc6496419~mv2.jpg',1500,1500,'19bQiwEKhXUBJWY6oV3KZk','https://open.spotify.com/album/19bQiwEKhXUBJWY6oV3KZk','https://music.apple.com/us/album/madvillainy/887699504','https://www.youtube.com/results?search_query=Madvillain+Madvillainy+full+album',false),
('29a896c1-ee77-48a9-8496-5d8022d4c29d','mm-food','MM..FOOD','MF DOOM',2004,'2000s','Rhymesayers Entertainment','United States','6cbdce99-93a5-4ccd-adbc-b5e907e3ee7e',array['Alternative hip-hop','Underground hip-hop']::text[],'Painting by Jason Jägel; art direction and design by Jeff Jank; design and layout by Adam R. Garcia','<p>Jeff Jank, then art director at Stones Throw Records, brought painter Jason Jägel onto MM..FOOD. There was no contract, no agreed fee and no guarantee the work would be used. Jägel played a CD-R demo of the album on repeat and made the piece on his own. "I made one pencil sketch and then I made the painting," he said.</p><p>The painting shows DOOM in his metal mask sitting at a kitchen table with a bowl of cereal, surrounded by food packaging and the view from a city window, a bright, detailed scene that fits an album built around food. There were no drafts and no revisions. DOOM and his wife Jasmine liked it immediately and commissioned the back cover and the art for the single "Hoe Cakes." The original painting included a blunt, which was later edited out.</p><p>At the time, most rap covers were photographs or photo collages, and the commissioned painting is now seen as a turning point for hip-hop album art. "I was pretty excited about it, to be honest with you," Jägel said. The album was released on 16 November 2004. Adam R. Garcia handled the design and layout alongside Jank.</p>','#604D4A','#D2C9BF','https://static.wixstatic.com/media/b519fa_f0a9045a8ba24779835d70b61f63ec97~mv2.jpg',1400,1400,'1UcS2nqUhxrZjrBZ3tHk2N','https://open.spotify.com/album/1UcS2nqUhxrZjrBZ3tHk2N','https://music.apple.com/us/album/mm-food/1516750770','https://www.youtube.com/results?search_query=MF+DOOM+MM..FOOD+full+album',false),
('0b6f3de2-2b91-47b4-87ab-5f3dfffadc29','the-college-dropout','The College Dropout','Kanye West',2004,'2000s','Roc-A-Fella Records','United States','27d91a37-0b27-477a-b65d-82e9697175da',array['Conscious rap','Chipmunk soul']::text[],'Design by Eric Duvauchelle','<p>Before the album had artwork, Kanye West had already taken pictures of himself dressed as the Dropout Bear, the mascot who would follow him through his early records. Eric Duvauchelle, then part of Roc-A-Fella''s in-house design team, picked the shot of the bear sitting alone on a set of bleachers.</p><p>Duvauchelle was drawn to the loneliness of the scene in what is supposed to be "the most popular representation of a school." He framed the photo in gold ornaments taken from a 16th-century illustration book. West wanted those flourishes to "bring a sense of elegance and style to what was typically a gangster-led image of rap artists."</p><p>The idea continued inside, where the booklet is laid out like a college yearbook with childhood photos of the featured artists. The original release used a brown background, and later remasters switched to white. The College Dropout was released on 10 February 2004.</p>','#AA6A2C','#D4B27B','https://static.wixstatic.com/media/b519fa_342bb2a2187a4976a61d92cd08938d5f~mv2.jpg',1500,1500,'4Uv86qWpGTxf7fU7lG5X6F','https://open.spotify.com/album/4Uv86qWpGTxf7fU7lG5X6F','https://music.apple.com/us/album/the-college-dropout/1412872568','https://www.youtube.com/results?search_query=Kanye+West+The+College+Dropout+full+album',false),
('46ccf126-b15b-4aaf-84da-7d73af87ce91','boy-in-da-corner','Boy in da Corner','Dizzee Rascal',2003,'2000s','XL Recordings','United Kingdom','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Grime','UK hip-hop']::text[],'Photography by Dean Chalkley; cover and logo design by Ben Drury','<p>The title becomes the picture. On the cover of Boy in da Corner, a teenage Dizzee Rascal crouches in the lower corner of a vast field of hazard-yellow, dressed in a black tracksuit and Nike Air Max trainers, small against all that empty colour.</p><p>Photographer Dean Chalkley, who had shot for NME, Mixmag and Dazed & Confused, spent a day with Dizzee and his manager Nick "Cage" Denton at Street Studios near Shoreditch in early 2003, shooting on film. "There was no pretense or anything," he said, and the clothes were what Dizzee would have worn anyway. The sleeve was designed by Ben Drury, known for his work with the Mo'' Wax label, who also created the album''s rugged, futuristic logo.</p><p>Boy in da Corner was released by XL Recordings on 21 July 2003 and won the Mercury Prize that year. Its stark yellow cover became one of the defining images of grime.</p>','#FEE01B','#898342','https://static.wixstatic.com/media/b519fa_2ae3947d37aa4e3d98e1261d59aa06ec~mv2.jpg',3000,3000,'16m3S8uDo5ZNLEekcnOSxf','https://open.spotify.com/album/16m3S8uDo5ZNLEekcnOSxf','https://music.apple.com/us/album/boy-in-da-corner/465625689','https://www.youtube.com/results?search_query=Dizzee+Rascal+Boy+in+da+Corner+full+album',false),
('16dda0a1-787d-4fee-910e-e7cea34f98b0','get-rich-or-die-tryin','Get Rich or Die Tryin''','50 Cent',2003,'2000s','Shady Records','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Gangsta rap','East Coast hip-hop']::text[],'Design by Julian Alexander and Sacha Waldman; photography by Sacha Waldman','<p>The cover of Get Rich or Die Tryin'' is a single, direct portrait. 50 Cent stands shirtless behind a pane of broken glass, wearing a heavy chain, his body warm-toned against a red background and his stare fixed on the viewer.</p><p>The image was photographed by Sacha Waldman and designed by Waldman with Julian Alexander. Its bare torso and cracked glass suggest toughness and survival, themes that run through an album made by a rapper who had famously been shot nine times before he got his major-label deal.</p><p>It has been described as among the most recognisable album covers in rap history. Released on 6 February 2003 by Shady, Aftermath and Interscope, the album became one of the biggest-selling debuts of its decade, and the shirtless pose became 50 Cent''s signature.</p>','#8D6A4E','#AD2B29','https://static.wixstatic.com/media/b519fa_1e5382ca3c2c45d3b52af91830cb3e07~mv2.jpg',3000,3000,'5G5rgQHzdQnw32SI0WjIo5','https://open.spotify.com/album/5G5rgQHzdQnw32SI0WjIo5','https://music.apple.com/us/album/get-rich-or-die-tryin-bonus-track-version/1440841450','https://www.youtube.com/results?search_query=50+Cent+Get+Rich+or+Die+Tryin''+full+album',false),
('44dde968-a969-4f27-a68a-fb47cb549439','the-black-album','The Black Album','Jay-Z',2003,'2000s','Roc-A-Fella Records','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['East Coast hip-hop','Hardcore hip-hop']::text[],'Photography by Jonathan Mannion; art direction and design by Robert Sims','<p>The Black Album was advertised as Jay-Z''s final record before retiring, and he wanted its cover to match. "Creatively, he wanted an all black album cover, with nothing on it, pure blackness," photographer Jonathan Mannion recalled. What fans got was almost that: Jay-Z''s face and cap barely emerging from the dark.</p><p>The picture was older than the album. Mannion took it during the photo sessions for The Blueprint in 2001, and the original is a colourful shot of Jay-Z in an oversized football jersey and his Roc-A-Fella chain. Heavy editing pushed it down to near-black. "We had the cover completed two albums prior to The Black Album''s release," Mannion said, and although he and Def Jam tried new images, "there was something magical about THAT image."</p><p>Mannion later shared the original on Instagram with the caption "THE ORIGINATOR. Photographed for The Blueprint in 2001. It became the actual blueprint for The Black Album." Art direction and design were by Robert Sims. The album was released on 14 November 2003 and debuted at number one.</p>','#040404','#2B2B2B','https://static.wixstatic.com/media/b519fa_a7ed377ab13946bfa4b7ffb8b63f338e~mv2.jpg',1424,1492,'4FWvo9oS4gRgHtAwDwUjiO','https://open.spotify.com/album/4FWvo9oS4gRgHtAwDwUjiO','https://music.apple.com/us/album/the-black-album/1440785433','https://www.youtube.com/results?search_query=Jay-Z+The+Black+Album+full+album',false),
('aa7449f4-10bb-49cc-87c1-2599a6542463','trap-muzik','Trap Muzik','T.I.',2003,'2000s','Grand Hustle / Atlantic','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Trap','Southern hip-hop']::text[],null,'<p>T.I. stands in a white T-shirt in front of a weathered house on the cover of his second album, looking calmly at the camera, with his name in big red and white letters and the title below.</p><p>The Atlanta rapper used the word "trap," slang for a house where drugs are sold, to describe his music, and Trap Muzik, released on 19 August 2003, gave the style its name. Songs like "24''s" and "Rubber Band Man" mixed street stories with big, bouncing Southern production.</p><p>The house behind him on the cover is the trap of the title, and the image turned a local word into a genre. Within a decade, trap had become the dominant sound of popular rap around the world, and T.I. was one of the stars who carried it there.</p>','#0A0B0C','#B5B8BD','https://static.wixstatic.com/media/b519fa_fadedccf6903418db6ef47f61e6f0bc4~mv2.jpg',1600,1600,'3I16wXzIVlaeb8ulHTxCXd','https://open.spotify.com/album/3I16wXzIVlaeb8ulHTxCXd','https://music.apple.com/us/album/trap-muzik/1258990795','https://www.youtube.com/results?search_query=T.I.+Trap+Muzik+full+album',false),
('c4af288b-3aad-421b-9381-ee9708376a4d','vom-bordstein-bis-zur-skyline','Vom Bordstein bis zur Skyline','Bushido',2003,'2000s','Aggro Berlin','Germany','818f66a4-a51e-4b8b-b515-691d9aba254d',array['German hip-hop','Gangsta rap']::text[],'Art direction and design by Specter; photography by Olli.NBK','<p>Bushido''s debut album, From the Kerb to the Skyline, made him one of the first big stars of the Berlin label Aggro Berlin. The cover is a dark portrait of the rapper in a cap, staring out from the shadows in front of a wall, with his name spelled in bright green capitals and a large black B beside it. That green and that B became his trademark for years.</p><p>The cover was designed by Specter, the Aggro Berlin co-founder who shaped the label''s look, with photography by Olli.NBK. Years later, a tweet that posted the unedited originals of classic German rap covers revealed a comic detail behind the hard image: in the untouched photo, Bushido was wearing an unusual pair of corduroy trousers.</p><p>Released on 14 July 2003, the album is regarded as a cornerstone of German gangsta rap, and Bushido returned to its title years later with Von der Skyline zum Bordstein zurück. The version on streaming services today is a 2021 re-release.</p>','#030307','#756F67','https://static.wixstatic.com/media/b519fa_60aaffbdfdd0453a8b3f6a7fe71eb0d1~mv2.jpg',3000,3000,'1jEoprw8f8UDwGF7gLLeCJ','https://open.spotify.com/album/1jEoprw8f8UDwGF7gLLeCJ','https://music.apple.com/de/album/vom-bordstein-bis-zur-skyline-re-release/1605974970','https://www.youtube.com/results?search_query=Bushido+Vom+Bordstein+bis+zur+Skyline+full+album',false),
('23d91644-bff0-47c8-8549-ff4c64da13e5','lord-willin','Lord Willin''','Clipse',2002,'2000s','Star Trak / Arista','United States','6cbdce99-93a5-4ccd-adbc-b5e907e3ee7e',array['Coke rap','East Coast hip-hop']::text[],'Art direction by Courtney Walter; concept by Malice','<p>The debut album by Clipse, the Virginia Beach brothers Pusha T and Malice, is the record that turned cocaine-dealing rap into its own sharp, cold style. Its cover is a painting: the brothers cruise down a sunny neighbourhood street in a long black convertible, past houses and onlookers, with the group''s name spelled out in red boxed letters.</p><p>Pusha T told Life+Times that his brother Malice came up with the idea. They wanted an image that represented the album''s title and felt like "Sugar Shack," the Ernie Barnes painting of a crowded dance hall made famous by the closing credits of the sitcom Good Times. That led them to a drawing in place of a photo, and the art director at the time, Courtney Walter, went looking for the painter.</p><p>Lord Willin'' was released on 20 August 2002, produced entirely by the Neptunes, and its single "Grindin''" became one of the most imitated beats of the decade. The warm, painted cover gave a hard record a nostalgic, almost innocent face.</p>','#645F50','#D3CFBA','https://static.wixstatic.com/media/b519fa_3bdfaae4341747669638c09f302a7764~mv2.jpg',606,600,'1Q83nQO2QG81TVa10hW7LX','https://open.spotify.com/album/1Q83nQO2QG81TVa10hW7LX','https://music.apple.com/us/album/lord-willin/389140434','https://www.youtube.com/results?search_query=Clipse+Lord+Willin%27+full+album',false),
('82d915e8-68c6-466f-9e3d-7d1482f42bb7','original-pirate-material','Original Pirate Material','The Streets',2002,'2000s','Locked On','United Kingdom','27d91a37-0b27-477a-b65d-82e9697175da',array['UK garage','British hip-hop']::text[],null,'<p>The cover of Original Pirate Material is a photograph of a council tower block at night, its windows lit in warm yellow against the dark, with The Streets'' logo in white and red near the corner.</p><p>Mike Skinner, a young producer from Birmingham, rapped in his own accent about chips, kebabs, fights and nights out over garage beats he made at home. Released on 25 March 2002, the album carried "Has It Come to This?" and "Weak Become Heroes" and was nominated for the Mercury Prize.</p><p>The tower block, full of other people''s lit windows, is the ordinary British life the album describes. Original Pirate Material showed that British rap could sound like Britain, and grime and UK rap that followed owe much to its plain-spoken voice.</p>','#523426','#945C38','https://static.wixstatic.com/media/b519fa_a2b5130fefe54e4a87d5ec736ac6899e~mv2.jpg',1417,1417,'0hkZGxfsFypXbjq15hM6U9','https://open.spotify.com/album/0hkZGxfsFypXbjq15hM6U9','https://music.apple.com/gb/album/original-pirate-material/63836809','https://www.youtube.com/results?search_query=The+Streets+Original+Pirate+Material+full+album',false),
('2045ecb1-649e-47b1-892a-f82d11953840','party-music','Party Music','The Coup',2001,'2000s','75 Ark','United States','27d91a37-0b27-477a-b65d-82e9697175da',array['Political hip-hop','West Coast hip-hop']::text[],'Cover image by Victor Hall; package design by Brandon Arnovick (liner-note credits)','<p>In June 2001 the Oakland group The Coup shot a cover for Party Music that showed Boots Riley and DJ Pam the Funkstress apparently blowing up the twin towers of the World Trade Center. Riley held what looked like a detonator, which was actually an electronic guitar tuner. The image was meant as a symbol of bringing down capitalism, on an album full of anti-capitalist anthems.</p><p>The album''s release had already moved from September to November, and printing of the cover was scheduled to begin on 11 September 2001. After the attacks, 75 Ark halted the print run and commissioned new artwork over Riley''s objections. Riley argued for keeping the original, describing the album as "a way to have a platform to interrupt the stream of lies that are being told right now."</p><p>The released cover shows a hand raising a flaming cocktail glass in a dark room, close to a Molotov cocktail served as a drink. Party Music came out on 6 November 2001 and was widely praised by critics. In 2024, Rolling Stone ranked the withdrawn original at number 46 on its list of the worst album covers ever, mostly for the band''s attempt to keep it. The liner notes credit Victor Hall for the cover image and Brandon Arnovick for the package design.</p>','#141110','#D9822B','https://static.wixstatic.com/media/b519fa_2495ee1ffbb34bf5adb331183476cdff~mv2.jpg',1425,1425,'74HkRQNxwELlh9Ckv5716T','https://open.spotify.com/album/74HkRQNxwELlh9Ckv5716T','https://music.apple.com/us/album/party-music/1485046528','https://www.youtube.com/results?search_query=The+Coup+Party+Music+full+album',false),
('4164fbf7-047e-499c-a232-b46ac349e7fd','the-blueprint','The Blueprint','Jay-Z',2001,'2000s','Roc-A-Fella Records','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['East Coast hip-hop','Chipmunk soul']::text[],'Photography by Jonathan Mannion','<p>Jonathan Mannion, who had photographed Jay-Z since Reasonable Doubt, took the cover picture for The Blueprint. The composition was inspired by an image from The Firm, a series by photographer Jocelyn Bain Hogg about organised crime in Britain.</p><p>Mannion''s version adapts the original''s still life. Where Bain Hogg''s photograph showed a telephone and brass knuckles beside an ashtray, the Blueprint cover swaps in a cigar, a pack of cigars and a microphone, trading the tools of a gangster for the tools of a rapper while keeping the same cool, cinematic mood.</p><p>The understated cover matched an album that turned to soul samples and a more reflective tone. The Blueprint was released by Roc-A-Fella on 11 September 2001, the day of the attacks on New York and Washington.</p>','#303138','#798AA1','https://static.wixstatic.com/media/b519fa_e4469333f2514dc0810525d165e1609f~mv2.jpg',3000,3000,'54I5tDCMjnNVWSENHg8EDH','https://open.spotify.com/album/54I5tDCMjnNVWSENHg8EDH','https://music.apple.com/us/album/the-blueprint/1440935272','https://www.youtube.com/results?search_query=Jay-Z+The+Blueprint+full+album',false),
('1f156856-4d2f-4eb3-abe1-87f4dbcb457c','the-cold-vein','The Cold Vein','Cannibal Ox',2001,'2000s','Definitive Jux','United States','cac97ec2-47e9-4562-b1b0-ebb5ae534086',array['Underground hip-hop','Abstract hip-hop']::text[],'Illustration by Tyson Jones; art direction and design by Dan Ezra Lang','<p>Cannibal Ox, the Harlem duo of Vast Aire and Vordul Mega, made one of the defining albums of New York''s underground with El-P producing every track. The cover is as cold as the title: a pale grey and blue illustration under the album''s name and the group''s metallic logo.</p><p>The illustration is by Tyson Jones, with art direction and design by Dan Ezra Lang. Its icy palette fits El-P''s dense, science-fiction beats and the bleak city stories on songs like "Iron Galaxy" and "Vein."</p><p>The Cold Vein was released on 15 May 2001 on El-P''s label Definitive Jux and helped define the sound of 2000s indie rap. Its artwork reached an unexpected audience years later, when a poster of it appeared in Greta Gerwig''s 2017 film Lady Bird.</p>','#6D7186','#9BA6C0','https://static.wixstatic.com/media/b519fa_43739f28a99a4ba9b19e875e62040a17~mv2.jpg',1400,1400,'4fcXf7no3MntdfUr4HKbIc','https://open.spotify.com/album/4fcXf7no3MntdfUr4HKbIc','https://music.apple.com/us/album/the-cold-vein-deluxe-edition/1660711417','https://www.youtube.com/results?search_query=Cannibal+Ox+The+Cold+Vein+full+album',false),
('6445e2ed-0132-498d-a228-4d29cccfd167','black-bastards','Black Bastards','KMD',2000,'2000s','Readyrock Records','United States','cac97ec2-47e9-4562-b1b0-ebb5ae534086',array['East Coast hip-hop','Boom bap']::text[],'Cover illustration credited to The EMEF; visuals by Scotch 79th','<p>KMD, the Long Island group of Zev Love X and his younger brother Subroc, recorded Black Bastards between 1991 and 1993 at Chung King studios. Their cover is a rough pen drawing of a Sambo character, the racist minstrel caricature, hanging from a gallows. The group had already used the figure inside a "no" symbol as their logo, and here they went further and executed him.</p><p>For KMD it was an attack on the stereotype itself, a drawing that killed off the image white America had made of Black people. Elektra saw only a lynching. After Billboard columnist Terri Rossi criticised the artwork in 1994, the label shelved the album, which had been scheduled for that May, and dropped the group. Subroc had already been killed by a car while crossing a highway in 1993, before the record was finished.</p><p>The loss sent Zev Love X into years of silence, and he later returned behind a metal mask as MF DOOM. Black Bastards finally came out on 15 May 2000 through Readyrock, with reissues by Sub Verse in 2001 and DOOM''s own Metalface label in 2008. The cover drawing is credited to The EMEF, with visuals by Scotch 79th.</p>','#F1F7E3','#C8202E','https://static.wixstatic.com/media/b519fa_136d855598ff4bfda2c7e854173344ff~mv2.jpg',3000,3000,'2c1HbILCmMdS1LigScTWc8','https://open.spotify.com/album/2c1HbILCmMdS1LigScTWc8','https://music.apple.com/us/album/black-bastards-deluxe-edition/1681144037','https://www.youtube.com/results?search_query=KMD+Black+Bastards+full+album',false),
('37f193fa-0070-448d-bcf8-db455a8b1d1a','let-s-get-free','Let''s Get Free','dead prez',2000,'2000s','Loud Records','United States','dad05a73-56a1-4791-ba0a-64cfbc2ad929',array['Political hip-hop','East Coast hip-hop']::text[],'Concept by Stuart "Kamau" Lyle; art direction and design by Kerry DeBruce; illustration by Lorraine West; photography by Anthony Cutajar; archival images from Corbis','<p>dead prez, the duo of stic.man and M-1, made a debut album about Black liberation, and they chose a cover from history. The sleeve is a red-tinted archival photograph of a crowd of young South Africans raising rifles in the air, celebrating during the struggle against apartheid.</p><p>The concept came from Stuart "Kamau" Lyle, with art direction and design by Kerry DeBruce, illustration by Lorraine West and photography by Anthony Cutajar, while the archival images were licensed from Corbis. Placing armed African youth on the front of an American rap record tied the album''s songs about schools, police and food directly to liberation movements abroad.</p><p>Many American retailers refused to stock the album with that image, and it was sold in a number of outlets with a censored cover. Released by Loud Records on 8 February 2000, Let''s Get Free became a landmark of political hip-hop, and the photograph remains one of the boldest statements ever put on a major-label rap sleeve.</p>','#6D201F','#AB6040','https://static.wixstatic.com/media/b519fa_7b3a1591a9a64a7f9a6241710e4167b1~mv2.jpg',3000,3000,'7gXuElmegVReY7imkb5bf8','https://open.spotify.com/album/7gXuElmegVReY7imkb5bf8','https://music.apple.com/us/album/lets-get-free/219077856','https://www.youtube.com/results?search_query=dead+prez+Let''s+Get+Free+full+album',false),
('d55a9642-0991-4983-91aa-834995cd2297','like-water-for-chocolate','Like Water for Chocolate','Common',2000,'2000s','MCA Records','United States','dad05a73-56a1-4791-ba0a-64cfbc2ad929',array['Conscious hip-hop','Alternative hip-hop']::text[],'Photograph by Gordon Parks (1956)','<p>The cover of Like Water for Chocolate is a 1956 photograph by Gordon Parks, taken in Alabama during his work documenting life under segregation. It shows a young Black woman dressed for church, bending to drink from a fountain marked "Colored Only."</p><p>Writers have linked the image to the title: the fountain stands for the water and the woman for the chocolate. Some go further, reading it as a picture of how everyone drank the same water while Black Americans were made to reach it through separate and unequal facilities.</p><p>It was the first Common album cover without his own face, a choice that pointed the record towards bigger themes of race and history. Parks, the photographer and filmmaker behind Shaft, gave the album one of the most powerful images ever used on a rap sleeve. Like Water for Chocolate was released by MCA on 28 March 2000.</p>','#26442E','#526554','https://static.wixstatic.com/media/b519fa_b567cb3bb2d54b8991d6e090a029a62e~mv2.jpg',1425,1412,'0ZSwTSaR9VUe3uYsXNQgub','https://open.spotify.com/album/0ZSwTSaR9VUe3uYsXNQgub','https://music.apple.com/us/album/like-water-for-chocolate/1854231673','https://www.youtube.com/results?search_query=Common+Like+Water+for+Chocolate+full+album',false),
('3c2fdad8-8803-46dc-8078-3be2219204a4','proverbios-13','Provérbios 13','509-E',2000,'2000s','Atração','Brazil','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['Brazilian hip-hop','Gangsta rap']::text[],'Photography by João Wainer','<p>509-E is a rap group formed inside a prison. Its members, Dexter and Afro-X, met while serving time in the Casa de Detenção de São Paulo, better known as Carandiru, the huge prison where 111 inmates were killed by police during a riot in 1992, and they took their name from their cell number.</p><p>For the cover of their debut, the photographer João Wainer shot real inmates inside Carandiru, a crowd of men in the yard below the cell blocks, with the two rappers standing above them. The result has the raw, unpolished feel of a documentary photograph, and it shows prison life plainly, without any staging.</p><p>Provérbios 13 was released on 1 May 2000, and the songs, written and recorded from behind bars, made 509-E a voice for prisoners across Brazil. Carandiru was demolished in 2002, which makes the cover one of the last records of life inside it.</p>','#686A3F','#919569','https://static.wixstatic.com/media/b519fa_d906543b7c26415fb5cb2973964a7937~mv2.jpg',1500,1500,'6NoGigzafbVAzRZpDTNhL2','https://open.spotify.com/album/6NoGigzafbVAzRZpDTNhL2','https://music.apple.com/br/album/prov%C3%A9rbios-13/1150938161','https://www.youtube.com/results?search_query=509-E+Provérbios+13+full+album',false),
('257985ab-c04d-4342-aaaf-91dcaee32d93','stankonia','Stankonia','OutKast',2000,'2000s','LaFace Records','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['Southern hip-hop','Psychedelic rap']::text[],'Photography by Michael Lavine; art direction and design by Mike Rush','<p>On the cover of Stankonia, André 3000 and Big Boi stand in front of an enormous American flag drained to black and white and hung upside down. The flag is a real object: it hangs in the tracking room of the duo''s studio in northwest Atlanta, and OutKast still owns it.</p><p>The colourless, inverted flag suggests a separate America, the imaginary place called Stankonia where the album''s music comes from. NME described both the sound and the sleeve as "quietly subversive," pointing to songs that criticise America''s appetite for war and oil, and Paste ranked the image among the best album covers of the 2000s.</p><p>The photograph was taken by Michael Lavine, with art direction and design by Mike Rush. Stankonia was released by LaFace and Arista on 31 October 2000.</p>','#272625','#6C5145','https://static.wixstatic.com/media/b519fa_311ae07cfd494016b591344345e8425c~mv2.jpg',3000,3000,'2tm3Ht61kqqRZtIYsBjxEj','https://open.spotify.com/album/2tm3Ht61kqqRZtIYsBjxEj','https://music.apple.com/us/album/stankonia-deluxe-version/1536616104','https://www.youtube.com/results?search_query=OutKast+Stankonia+full+album',false),
('d2ab2df3-2f8d-42b4-948c-7d1c3d2486e8','the-marshall-mathers-lp','The Marshall Mathers LP','Eminem',2000,'2000s','Aftermath Entertainment','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Hardcore hip-hop','Horrorcore']::text[],'Photography by Jonathan Mannion; art direction and design by Jason Noto','<p>The album was first going to be called Amsterdam, and Jonathan Mannion''s first shoot took place there, on docks in freezing cold with Eminem in boxer shorts and a trench coat. When the plan changed, the team went to Detroit and photographed Eminem sitting on the porch of the house he had lived in as a teenager.</p><p>"It was all about the authenticity," Mannion said. "I could have put him on any steps, and it would have looked kind of cool." Eminem admitted he had "mixed feelings" about returning, because there were "a lot of good and bad memories in that house." The quiet, grey picture matches an album titled with his real name, the most personal record he had made.</p><p>An alternate cover shows him curled up beneath a loading dock with alcohol and pill bottles at his feet, which Entertainment Weekly''s Will Hermes compared to a "dysfunctional Little Rascal." Art direction and design were by Jason Noto. The Marshall Mathers LP was released on 23 May 2000.</p>','#76736F','#9A9592','https://static.wixstatic.com/media/b519fa_c3b96b6455da4180a9932cecd12b46b1~mv2.jpg',1500,1500,'6t7956yu5zYf5A829XRiHC','https://open.spotify.com/album/6t7956yu5zYf5A829XRiHC','https://music.apple.com/us/album/the-marshall-mathers-lp/1440866782','https://www.youtube.com/results?search_query=Eminem+The+Marshall+Mathers+LP+full+album',false),
('2cbe0b32-f615-426a-9b77-1228e47aefed','2001','2001','Dr. Dre',1999,'1990s','Aftermath / Interscope','United States','c0217d82-6644-4ea9-99d1-67b7e9dbe7a7',array['West Coast hip-hop','G-funk']::text[],'Art direction and design by Jason Clark; collage concept by Charis Henry; collage photography by Richard "Segal" Huredia; photography by Stan Musilik and Donn Thompson','<p>Seven years after The Chronic, Dr. Dre came back with a cover of almost nothing. It is pitch black, with his name in small green letters at the top and, in the bottom corner, the number 2001 beside a single green cannabis leaf.</p><p>The leaf is a joke about the album''s name. Dre first planned to call it Chronic 2000, then Chronic 2001: No Seeds, until a trademark dispute over The Chronic name forced a change. The final title dropped the word, and the leaf next to "2001" quietly kept it. The clean edition removes the leaf and adds a white "CENSORED VERSION" stamp. The liner notes credit art direction and design to Jason Clark, with the collage concept by Charis Henry, collage photography by Richard "Segal" Huredia and photography by Stan Musilik and Donn Thompson.</p><p>2001 was released on 16 November 1999 and became one of the best-selling rap albums ever, with "Still D.R.E." and "Forgot About Dre" proving that Dre and his new protégé Eminem could still set the sound of the West Coast.</p>','#020709','#295133','https://static.wixstatic.com/media/b519fa_be4f1b77b0824ab4a6467c87a8aee6eb~mv2.jpg',1424,1414,'7q2B4M5EiBkqrlsNW8lB7N','https://open.spotify.com/album/7q2B4M5EiBkqrlsNW8lB7N','https://music.apple.com/us/album/2001/1440782221','https://www.youtube.com/results?search_query=Dr.+Dre+2001+full+album',false),
('406f68d6-afd9-4df6-b307-f499dce3222b','a-lo-cubano','A lo cubano','Orishas',1999,'1990s','EMI','Cuba','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['Latin hip-hop','Cuban hip-hop']::text[],null,'<p>The four members of Orishas look up toward the light on the cover of their debut, their faces lit in warm gold and brown against a dark background, with the group''s name and the title in the centre.</p><p>Orishas, named after the gods of the Afro-Cuban Yoruba religion, were Cuban rappers who had moved to Paris. A lo cubano blended rap with son, rumba and Cuban guitar, and its single "537 C.U.B.A.," built on the melody of "Chan Chan" from the Buena Vista Social Club, became an international hit.</p><p>The upward gaze gives the cover a spiritual feeling that fits the group''s name. The album brought Cuban hip-hop to audiences across Europe and Latin America and showed how rap could carry a national tradition with it.</p>','#22212B','#DFA658','https://static.wixstatic.com/media/b519fa_909deb71844645778eefbf060086b233~mv2.jpg',1500,1500,'3zXdL8n7OMWKY156NgUZ4m','https://open.spotify.com/album/3zXdL8n7OMWKY156NgUZ4m','https://music.apple.com/es/album/a-lo-cubano/726238957','https://www.youtube.com/results?search_query=Orishas+A+lo+cubano+full+album',false),
('3bf46c1e-9200-4730-b077-9170985cbaea','black-on-both-sides','Black on Both Sides','Mos Def',1999,'1990s','Rawkus','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Conscious hip-hop','Alternative hip-hop']::text[],null,'<p>The cover of Mos Def''s solo debut is a tight close-up of his face in warm red and brown light, eyes looking straight into the camera, with nothing else in the frame beyond his name and the title in small type.</p><p>Released on 12 October 1999 on Rawkus, Black on Both Sides showed the Brooklyn rapper''s range: he rapped, sang and played instruments, and moved from the street politics of "Mathematics" and "Hip Hop" to the soul of "Umi Says" and the rock of "Rock N Roll." It became a defining album of the conscious rap movement.</p><p>The face-only portrait matches the title, a statement of Black identity, and an artist who preferred to stand plainly in front of the listener. Mos Def later took the name Yasiin Bey, and the album remains his most celebrated work.</p>','#110F10','#9D663E','https://static.wixstatic.com/media/b519fa_12424af71784408e9d4756c65d345918~mv2.jpg',3000,3000,'5gK2l2LgWY0BA4p9uy27z6','https://open.spotify.com/album/5gK2l2LgWY0BA4p9uy27z6','https://music.apple.com/us/album/black-on-both-sides/1444213589','https://www.youtube.com/results?search_query=Mos+Def+Black+on+Both+Sides+full+album',false)
insert into public.covers (id,slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,color,accent_color,image_url,image_width,image_height,spotify_album_id,spotify_url,apple_music_url,youtube_url,featured) values
('b1a98f5b-711e-46a9-a039-f4a519bed459','i-am','I Am...','Nas',1999,'1990s','Columbia Records','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['East Coast hip-hop','Hardcore hip-hop']::text[],'Photography by Daniel Hastings; creative direction by Ola Kudu; face mould by Dave Cortes','<p>For I Am..., photographer Daniel Hastings turned Nas into a pharaoh. "We came with the concept of making a King Tut sarcophagus piece," he said. Hastings saw it as the next step in a story told through the covers: Illmatic showed Nas as a young boy, It Was Written showed him older, and I Am... crowns him a king.</p><p>Making the gold mask was difficult. Sculptor Dave Cortes made a clay mould of Nas''s face, and the first attempt nearly suffocated him before a second one worked. Once Nas was painted gold, his face reflected everything in the studio, so Hastings used large black and white boards to shape the highlights and shadows. "I was essentially shooting a mirror," he said.</p><p>Hastings was hired for the job by creative director Ola Kudu. The album was released by Columbia on 6 April 1999.</p>','#582F1E','#9D6C39','https://static.wixstatic.com/media/b519fa_9e0e2b33af054ee9bef04b3af4c7c43d~mv2.jpg',3000,3000,'4UhEjfIRx4tE1XRY21vwNa','https://open.spotify.com/album/4UhEjfIRx4tE1XRY21vwNa','https://music.apple.com/us/album/i-am/216999742','https://www.youtube.com/results?search_query=Nas+I+Am...+full+album',false),
('6c126930-1b1f-4d1b-bb64-63528546e35b','operation-doomsday','Operation: Doomsday','MF DOOM',1999,'1990s','Fondle ''Em Records','United States','cac97ec2-47e9-4562-b1b0-ebb5ae534086',array['Underground hip-hop','Alternative hip-hop']::text[],'Artwork by MF DOOM, with colouring by KEO','<p>Operation: Doomsday was the comeback of Daniel Dumile, who had been Zev Love X of KMD until his brother''s death and the shelving of Black Bastards. He reappeared at open mics in New York with his face covered and a new name, MF DOOM, and his first album came out on Bobbito Garcia''s Fondle ''Em Records on 19 October 1999.</p><p>The cover is a comic-book panel: DOOM in his metal mask and a green hoodie, gripping a microphone against a lightning-streaked red sky, with the title bursting out in jagged lettering. DOOM did the drawing himself. "Yeah I did the art," he said. "All the album covers that we ever did, I did the artwork," adding that the graffiti artist "KEO helped me out with the album cover, the coloring."</p><p>The character was modelled on Marvel''s Doctor Doom, and the drawing turned that villain into DOOM''s permanent public face. Licensing issues complicated later reissues, and the 2011 edition used a new painting by Jason Jägel, but the original hand-drawn sleeve is the one that introduced the villain to the world.</p>','#4D6164','#B33833','https://static.wixstatic.com/media/b519fa_70147d74804946e4b7802e0af3cbd30b~mv2.jpg',1500,1500,'5bjUbZPVTEQcb6W3LquX1E','https://open.spotify.com/album/5bjUbZPVTEQcb6W3LquX1E','https://music.apple.com/us/album/operation-doomsday-complete/1654811465','https://www.youtube.com/results?search_query=MF+DOOM+Operation+Doomsday+full+album',false),
('0b4e4ac9-7a3b-40f0-9e3b-58a461254297','the-slim-shady-lp','The Slim Shady LP','Eminem',1999,'1990s','Aftermath / Interscope','United States','27d91a37-0b27-477a-b65d-82e9697175da',array['Horrorcore','Detroit hip-hop']::text[],null,'<p>A figure sits at the end of a long wooden pier at night under a huge moon on the cover of Eminem''s major-label debut, with an old car parked nearby and the title scrawled in bright, childish letters. The calm, moonlit scene hides something darker, as the car''s open trunk suggests.</p><p>The Detroit rapper''s major-label debut, made with Dr. Dre, introduced Slim Shady, a violent and funny alter ego who said whatever he liked. Released on 23 February 1999, it was led by "My Name Is," won the Grammy for Best Rap Album and made Eminem the most controversial star in music.</p><p>The original artwork upset some retailers, and a replacement cover was made for big stores. That split, a peaceful picture with a disturbing detail, matches an album that hid shocking lyrics inside catchy, cartoonish songs, and it launched rap''s best-selling artist.</p>','#585570','#D6D2DF','https://static.wixstatic.com/media/b519fa_a36352c5afff436ba26dad6d5910bc88~mv2.jpg',1455,1429,'0vE6mttRTBXRe9rKghyr1l','https://open.spotify.com/album/0vE6mttRTBXRe9rKghyr1l','https://music.apple.com/us/album/the-slim-shady-lp/1440871441','https://www.youtube.com/results?search_query=Eminem+The+Slim+Shady+LP+full+album',false),
('3e88100b-31ef-462c-b193-9c22bd042aa6','things-fall-apart','Things Fall Apart','The Roots',1999,'1990s','MCA Records','United States','dad05a73-56a1-4791-ba0a-64cfbc2ad929',array['Alternative hip-hop','Jazz rap']::text[],'Art direction by Kenny Gravillis; archival photograph, photographer unknown','<p>Things Fall Apart takes its title from Chinua Achebe''s novel, which borrowed the phrase from W.B. Yeats''s poem "The Second Coming." Art director Kenny Gravillis and The Roots wanted the cover to show what he called "visual failure in society," and they settled on five archival news photographs, sold for a limited time as five different front covers.</p><p>The main cover is a stark black-and-white photograph from the 1960s, taken during a riot in Bedford-Stuyvesant, Brooklyn, of police chasing two Black teenagers down the street. Its photographer is unknown. "This became the main artwork for a few reasons," Gravillis said, crediting MCA for agreeing to release it. The original plan had been an illustration of The Roots and Sean Combs sinking to the bottom of the ocean.</p><p>The alternate covers showed a murdered mob boss''s hand, a burned church, a baby in the bombed ruins of Shanghai''s South Railway Station in 1937, and a crying child during the 1992 famine in Somalia. The Bedford-Stuyvesant cover was later included in the book The Greatest Album Covers of All Time. The album was released on 23 February 1999.</p>','#151515','#B5B5B5','https://static.wixstatic.com/media/b519fa_c9597e4525d24c8e8d01e18575b8058a~mv2.jpg',1423,1416,'0qbl8aNaCUOvX8HGsZYLfh','https://open.spotify.com/album/0qbl8aNaCUOvX8HGsZYLfh','https://music.apple.com/us/album/things-fall-apart/1440632803','https://www.youtube.com/results?search_query=The+Roots+Things+Fall+Apart+full+album',false),
('31b0c0eb-baeb-4d3e-93e7-f0fe9537ef9b','400-degreez','400 Degreez','Juvenile',1998,'1990s','Cash Money / Universal','United States','464ed954-6e08-4d0e-84ab-1a736b658cd3',array['Southern hip-hop','Bounce']::text[],'Cover by Pen & Pixel Graphics (Shawn Brauch)','<p>Juvenile''s breakthrough album is pure Cash Money excess. The New Orleans rapper stands at the centre of a blazing gold and orange swirl, glittering with diamond effects, with his name in huge metallic capitals across the top.</p><p>The cover came from Pen & Pixel Graphics, the Houston studio run by the brothers Shawn and Aaron Brauch that designed most of the No Limit and Cash Money covers of the late 1990s. Shawn Brauch told uDiscover Music he did not think the cover was special at the time, calling it "another spiral job" built around one dominant colour and a diamond effect. He credited the success to the music: "Once the music got the momentum, people wanted to go and get it."</p><p>400 Degreez was released on 3 November 1998 and, carried by "Ha" and "Back That Azz Up," went multi-platinum. Its glittering, over-the-top cover is now one of the defining examples of the Pen & Pixel style that shaped the look of Southern rap.</p>','#C7994E','#955939','https://static.wixstatic.com/media/b519fa_30fb89285de746babae22955a13239ca~mv2.jpg',1411,1417,'4qhfUXCkyFaY6CO9Ksy7rs','https://open.spotify.com/album/4qhfUXCkyFaY6CO9Ksy7rs','https://music.apple.com/us/album/400-degreez/1440644146','https://www.youtube.com/results?search_query=Juvenile+400+Degreez+full+album',false),
('04840819-869f-4d32-bf11-a86fe8323557','aquemini','Aquemini','OutKast',1998,'1990s','LaFace Records','United States','cac97ec2-47e9-4562-b1b0-ebb5ae534086',array['Southern hip-hop','Alternative hip-hop']::text[],'Artwork by Greg Hawkins; art direction and design by D.L. Warfield; photography by Tom Smugala','<p>The title Aquemini joins the star signs of OutKast''s two members, André''s Gemini and Big Boi''s Aquarius, and the cover paints them as a matched pair. Greg Hawkins'' artwork shows the duo larger than life in a vivid, crowded scene, styled like the poster for a 1970s film.</p><p>David Browne of The New York Times read the cover as an homage to 1970s blaxploitation cinema, and the comparison fits: heroic poses, swirling colour and a supporting cast of characters around the two stars. Art direction and design were by D.L. Warfield, and photography by Tom Smugala.</p><p>The packaging played on the pairing too. A sticker on the release introduced Big Boi as "the playa" and André as "the poet," the two sides of a partnership the album celebrates. Aquemini was released by LaFace on 29 September 1998.</p>','#7E6D61','#B5A99F','https://static.wixstatic.com/media/b519fa_1f6b6a98d86a4c989c78b9f9ce1debbc~mv2.jpg',3000,3000,'5ceB3rxgXqIRpsOvVzTG28','https://open.spotify.com/album/5ceB3rxgXqIRpsOvVzTG28','https://music.apple.com/us/album/aquemini/266365274','https://www.youtube.com/results?search_query=OutKast+Aquemini+full+album',false),
('6b27a6af-bd51-4d91-ae21-382f89be1920','capital-punishment','Capital Punishment','Big Punisher',1998,'1990s','Loud / RCA','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['East Coast hip-hop','Hardcore hip-hop']::text[],'Photography by Daniel Hastings','<p>Big Pun, the Bronx rapper born Christopher Rios, fills the cover of his debut album. He faces the camera with a hard expression, wearing a pair of large blue-lensed goggles, his name stacked above him in huge yellow letters.</p><p>The photograph was taken by Daniel Hastings, who also shot the covers of Enter the Wu-Tang (36 Chambers) and Only Built 4 Cuban Linx. Writing for Muse by Clio, Hastings recalled that the cover was shot outside Sue''s Rendezvous, and that he focused on Pun''s face and his "mean mug," a look that became the signature of the album. The inside of the package shows Pun at landmarks across the boroughs.</p><p>Capital Punishment was released on 28 April 1998 and became the first album by a solo Latino rapper to go platinum. Pun died in February 2000 at the age of 28, and the cover remains the defining image of one of New York''s greatest lyricists.</p>','#0B0708','#ECEEEB','https://static.wixstatic.com/media/b519fa_cfe2e8d2d68b449988532cbb2f283367~mv2.jpg',600,600,'3IIHk2ZLXKWuVAjCbQ9g4Y','https://open.spotify.com/album/3IIHk2ZLXKWuVAjCbQ9g4Y','https://music.apple.com/us/album/capital-punishment/253530902','https://www.youtube.com/results?search_query=Big+Punisher+Capital+Punishment+full+album',false),
('268b28e5-6a66-463c-b685-3197af5bce64','flesh-of-my-flesh-blood-of-my-blood','Flesh of My Flesh, Blood of My Blood','DMX',1998,'1990s','Def Jam Recordings','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Hardcore hip-hop','East Coast hip-hop']::text[],'Photography by Jonathan Mannion; art direction and design by The Drawing Board; artwork by Estos and Sleep of the Ruff Ryders Art Department','<p>For DMX''s second album of 1998, Jonathan Mannion prepared 50 gallons of fake blood, mixed to have what he called "nice viscosity." The label gave him free rein and warned him he would be taking chances, agreeing to the risky idea as long as DMX was willing to go along with it.</p><p>DMX was reluctant at first and worried about ruining his pants. Mannion told him, "I''ve never steered you wrong, man," then offered to shoot in his own boxer shorts and dropped his trousers in front of the whole studio. DMX agreed, and the finished cover shows him rising from the blood, arms outstretched, his body soaked red against a stark white background.</p><p>Mannion knew exactly what the image would do. "That shock value. You want to look away, but you can''t," he said. Art direction and design were by The Drawing Board, with artwork by Estos and Sleep of the Ruff Ryders Art Department. The album was released on 22 December 1998.</p>','#FCFCFC','#BA4C54','https://static.wixstatic.com/media/b519fa_b2ccb8c1dc3d4c07aac9bbd43303c671~mv2.jpg',1446,1425,'3dNsHWAS8t7AiAqj9ofG5T','https://open.spotify.com/album/3dNsHWAS8t7AiAqj9ofG5T','https://music.apple.com/us/album/flesh-of-my-flesh-blood-of-my-blood/1440822279','https://www.youtube.com/results?search_query=DMX+Flesh+of+My+Flesh,+Blood+of+My+Blood+full+album',false),
('3fab853f-b142-41b9-a699-49b70118d760','le-combat-continue','Le Combat continue','Ideal J',1998,'1990s','Alariana','France','27d91a37-0b27-477a-b65d-82e9697175da',array['French hip-hop','Political hip-hop']::text[],'Photography and design by Armen','<p>Ideal J, the Orly group led by a young Kery James, wanted their second album to make a political statement about how France treated its Black and Arab citizens. The cover shows a dark-skinned hand clenched hard around the French tricolour, crumpling the blue, white and red cloth in its fist above the title in red capitals.</p><p>The first versions, shot by the photographer Armen, showed a model wrapped in the flag. Kery James turned them down as not strong enough. Armen then asked the model to grip the flag as tightly as possible, so the image became one of demand: communities who had helped build the country holding on to the rights and recognition they had earned.</p><p>The picture divided people, as Kery James knew it would. Released on 26 October 1998, Le Combat continue became one of the founding classics of hardcore French rap, and its fist became a lasting symbol of the anger of the banlieues.</p>','#030304','#A6312C','https://static.wixstatic.com/media/b519fa_15bfbe1d243b4d56b20466ce78b9d69b~mv2.jpg',3000,3000,'2xvsjf4z8QTDrGOGrhOqPb','https://open.spotify.com/album/2xvsjf4z8QTDrGOGrhOqPb','https://music.apple.com/fr/album/le-combat-continue/1536181840','https://www.youtube.com/results?search_query=Ideal+J+Le+Combat+continue+full+album',false),
('1f6c4d71-de91-4825-bb75-14ab128700ab','moment-of-truth','Moment of Truth','Gang Starr',1998,'1990s','Noo Trybe / Virgin','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['Boom bap','East Coast hip-hop']::text[],null,'<p>Guru and DJ Premier of Gang Starr pose in a warm, hazy orange photograph on the cover of their fifth album, both in light clothing, with the group''s logo at the top and the title in silver letters along the bottom.</p><p>The Boston-born rapper and the Houston-born producer had defined New York boom bap through the 1990s, and Moment of Truth, released on 31 March 1998, found them at their peak. Premier''s chopped samples and scratched hooks and Guru''s calm, steady voice on "You Know My Steez" and "Royalty" set the standard for the sound.</p><p>Its title and serious mood reflect a group taking stock. It became Gang Starr''s most successful record, and after Guru''s death in 2010 it is often named as the purest statement of what a rapper and a DJ could make together.</p>','#432B28','#D8AD79','https://static.wixstatic.com/media/b519fa_356a4e50fd114214b74e2aa278ea8e35~mv2.jpg',1400,1400,'5f6Nz2v1DESbpu1NerEql2','https://open.spotify.com/album/5f6Nz2v1DESbpu1NerEql2','https://music.apple.com/us/album/moment-of-truth/723351765','https://www.youtube.com/results?search_query=Gang+Starr+Moment+of+Truth+full+album',false),
('b0c6decb-25e1-40ac-99f6-f002337ce98d','money-power-respect','Money, Power & Respect','The LOX',1998,'1990s','Bad Boy / Arista','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['East Coast hip-hop','Hardcore hip-hop']::text[],'Photography by Daniel Hastings','<p>The LOX, the Yonkers trio of Jadakiss, Styles P and Sheek Louch, released their debut on Puff Daddy''s Bad Boy Records at the height of the label''s glossy, champagne-soaked era. The cover shows the three of them in sunglasses and shiny red and gold outfits, the look that defined that moment in New York rap.</p><p>The photographer Daniel Hastings, who shot three album sessions with the group, recalled for Muse by Clio that this one was taken in Yonkers, where they grew up. Puff Daddy brought the shiny suits to the end of the shoot, and Hastings says it was the first and last time the group wore that style.</p><p>Money, Power & Respect was released on 13 January 1998, and its title track with DMX and Lil'' Kim became a street anthem. The LOX later fought to leave Bad Boy with their "Free the LOX" campaign, which makes the cover a record of an image they quickly left behind.</p>','#B95D49','#DEAD62','https://static.wixstatic.com/media/b519fa_7c9e9df02be846ecbee800f6e4611b16~mv2.jpg',1444,1432,'1fkGVz3LWxjax7F0Mrj3f5','https://open.spotify.com/album/1fkGVz3LWxjax7F0Mrj3f5','https://music.apple.com/us/album/money-power-respect/80979079','https://www.youtube.com/results?search_query=The+LOX+Money%2C+Power+%26+Respect+full+album',false),
('9710ef71-8e43-4433-a45c-2613412a767c','mos-def-talib-kweli-are-black-star','Mos Def & Talib Kweli Are Black Star','Black Star',1998,'1990s','Rawkus','United States','c0217d82-6644-4ea9-99d1-67b7e9dbe7a7',array['Conscious hip-hop','East Coast hip-hop']::text[],'Cover design by Brent Rollins; art direction by Black Star; photography by Eddie Otchere and others','<p>Mos Def and Talib Kweli named their duo after the Black Star Line, the shipping company Marcus Garvey founded to connect Black people across the Atlantic. The cover looks like a vintage poster or label from that era: an ornate frame of red, gold and green, stars and banners, with the two rappers'' portraits at its centre and the name Black Star in bold script.</p><p>It was designed by Brent Rollins, the designer behind the Boyz n the Hood logo and covers for Blackalicious and Freeway. The art direction is credited to Black Star themselves, and the photography credits include the British photographer Eddie Otchere.</p><p>The album was released on 29 September 1998 on the independent Rawkus label, and songs like "Definition" and "Respiration" made it the cornerstone of the conscious rap scene of the late 1990s. Rollins''s design tied that scene''s ideas about Black history and pride to an image that looked like it came from Garvey''s own time.</p>','#CB9B54','#E05332','https://static.wixstatic.com/media/b519fa_3ababc8100004e298044cd722d305a4c~mv2.jpg',1422,1411,'6GRzmk9UGL7odxprOPop1Q','https://open.spotify.com/album/6GRzmk9UGL7odxprOPop1Q','https://music.apple.com/us/album/mos-def-talib-kweli-are-black-star/1440799801','https://www.youtube.com/results?search_query=Black+Star+Mos+Def+%26+Talib+Kweli+Are+Black+Star+full+album',false),
('b36972bd-7b09-4bcb-a3b8-f168d5b107e2','rza-as-bobby-digital-in-stereo','RZA as Bobby Digital in Stereo','RZA',1998,'1990s','Gee Street / V2','United States','cac97ec2-47e9-4562-b1b0-ebb5ae534086',array['East Coast hip-hop','Hardcore hip-hop']::text[],'Illustration by Bill Sienkiewicz','<p>RZA''s first solo album is built around a character, Bobby Digital, a hedonistic, fun-loving alter ego with a superhero''s swagger. RZA explained the split simply: "Bobby Digital is just me feeling my nuts. RZA is my heart." To bring that character to life, he went to a comic-book artist.</p><p>Bill Sienkiewicz, known for his expressive painted work on Marvel titles such as The New Mutants and Elektra: Assassin, drew the cover. It shows RZA as Bobby Digital holding a huge green futuristic gun, surrounded by a swirling collage of women, cars, explosions and city streets in Sienkiewicz''s loose, painterly style.</p><p>The image placed the Wu-Tang leader''s love of comics, kung fu films and pulp heroes front and centre, at a time when the Clan was building its own mythology. Released on 24 November 1998 through Wu-Tang, Gee Street and V2, the album was followed by more Bobby Digital projects, and the cover remains one of the clearest crossovers between hip-hop and comic art.</p>','#F8FBF6','#BE7B55','https://static.wixstatic.com/media/b519fa_0c0464a1180240f6a010952b8d346104~mv2.jpg',885,900,'2cvWktSYxIVVWxBrzGZsym','https://open.spotify.com/album/2cvWktSYxIVVWxBrzGZsym','https://music.apple.com/us/album/rza-as-bobby-digital/305562423','https://www.youtube.com/results?search_query=RZA+as+Bobby+Digital+in+Stereo+full+album',false),
('4c0fd6b1-0a91-4023-bd87-847b571e3a9c','the-miseducation-of-lauryn-hill','The Miseducation of Lauryn Hill','Lauryn Hill',1998,'1990s','Ruffhouse / Columbia','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['East Coast hip-hop','Neo soul']::text[],'Photography by Eric Johnson and Marc Baptiste; art direction by Lauryn Hill and Erwin Gorostiza','<p>The cover of Lauryn Hill''s only solo studio album shows her face as if it had been carved into the wooden top of a school desk, the kind of carving bored students scratch in during class. It fits an album whose interludes are recordings of a teacher talking with a real classroom of students.</p><p>The photographer Eric Johnson took Hill back to Columbia High School in Maplewood, New Jersey, the school she had attended, and shot her in classrooms, corridors and on a school bus. Johnson said he wanted something chic that regular people could also identify with. From that shoot, Hill picked one of his images of her face and had it turned into the desk carving. The package also credits photography by Marc Baptiste, with art direction by Lauryn Hill herself and Erwin Gorostiza.</p><p>The Miseducation of Lauryn Hill was released in August 1998, and in 1999 it became the first hip-hop album to win the Grammy for Album of the Year. The carved face has become one of the most recognisable images in music.</p>','#B06545','#CD9A6E','https://static.wixstatic.com/media/b519fa_851d16170f9f48cdb0066833d948c042~mv2.jpg',1500,1500,'1BZoqf8Zje5nGdwZhOjAtD','https://open.spotify.com/album/1BZoqf8Zje5nGdwZhOjAtD','https://music.apple.com/us/album/the-miseducation-of-lauryn-hill/1276760743','https://www.youtube.com/results?search_query=Lauryn+Hill+The+Miseducation+of+Lauryn+Hill+full+album',false),
('614e3aa0-b859-4f19-bb50-171caacf0462','vol-2-hard-knock-life','Vol. 2... Hard Knock Life','Jay-Z',1998,'1990s','Roc-A-Fella / Def Jam','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['East Coast hip-hop','Mafioso rap']::text[],null,'<p>Jay-Z stands on the cover of his third album in a sharp dark suit, leaning against a classic car, cool and composed against a clean white background, with his name in silver capitals at the top.</p><p>Vol. 2... Hard Knock Life, released on 29 September 1998, was Jay-Z''s commercial breakthrough. Its title track sampled the orphans'' song from the musical Annie and became a worldwide hit, and the album won the Grammy for Best Rap Album and became the best-selling record of his career.</p><p>The image of the businessman leaning on his car summed up the Jay-Z persona that took over rap in the years that followed. The polished look and confident pose turned the Brooklyn hustler of Reasonable Doubt into a star.</p>','#1A2929','#F8F9F9','https://static.wixstatic.com/media/b519fa_b86db8b0e2624b199159d87e9a2c057c~mv2.jpg',1429,1410,'3j1xCJdBMCl6wYQXurz2tb','https://open.spotify.com/album/3j1xCJdBMCl6wYQXurz2tb','https://music.apple.com/us/album/vol-2-hard-knock-life/1440914180','https://www.youtube.com/results?search_query=Jay-Z+Vol.+2...+Hard+Knock+Life+full+album',false),
('2bcf20e0-5675-4f05-974a-51b6d34455d9','ghetto-d','Ghetto D','Master P',1997,'1990s','No Limit Records','United States','464ed954-6e08-4d0e-84ab-1a736b658cd3',array['Southern hip-hop','Gangsta rap']::text[],'Design by Pen & Pixel Graphics (Aaron and Shawn Brauch)','<p>Pen & Pixel, the Houston design firm started in 1992 by brothers Aaron and Shawn Brauch, made the look of late-1990s Southern rap. Its covers piled Photoshop effects, chrome lettering, flames and luxury goods onto one image, and the studio turned out close to 20,000 of them before it closed in 2003. Ghetto D is one of the defining examples.</p><p>Master P''s name sits across the middle in huge sparkling letters made to look encrusted with diamonds, above a cracked, camouflage-patterned GHETTO D logo in a sea of fire. The top of the frame is packed with fragments of earlier No Limit covers. As Master P told The Fader, "I just kinda put everything into one thing, and then I blinged up my name on that," adding that he put "all the covers from all the other album covers in that."</p><p>The approach fit an independent label that sold its records through sheer volume and a constant flow of releases. Ghetto D came out on 2 September 1997 through No Limit and Priority, debuted at number one on the Billboard 200, and made the bling-and-explosions Pen & Pixel style the face of Southern hip-hop''s commercial breakthrough.</p>','#695B5B','#C7694B','https://static.wixstatic.com/media/b519fa_2bec2351e7894d238637cac279d7fc6f~mv2.jpg',897,891,'699xAzNxlXxgmkycTEqktC','https://open.spotify.com/album/699xAzNxlXxgmkycTEqktC','https://music.apple.com/us/album/ghetto-d/721278963','https://www.youtube.com/results?search_query=Master+P+Ghetto+D+full+album',false),
('34e632d5-1b44-4f34-b70a-624f40afeef0','l-ecole-du-micro-d-argent','L''École du micro d''argent','IAM',1997,'1990s','Delabel','France','6cbdce99-93a5-4ccd-adbc-b5e907e3ee7e',array['French hip-hop','Conscious hip-hop']::text[],null,'<p>The cover of IAM''s third album is a painted battle scene: an army of mounted warriors and banners crosses a dark landscape under a blood-red sky, with the group''s emblem at the top and the title in ornate letters at the bottom.</p><p>The Marseille group, led by Akhenaton and Shurik''n, built the album on samples of film scores and on rhymes drawing on ancient history, Asian martial arts and the struggles of the city''s neighbourhoods. Released in March 1997, it carried "Demain, c''est loin," "Petit frère" and "Nés sous la même étoile" and sold more than a million copies.</p><p>The epic, cinematic painting fits a group that saw rap as a battle and a school, as the title suggests: the school of the silver microphone. The album is often called the greatest French rap record ever made.</p>','#15100C','#A7281C','https://static.wixstatic.com/media/b519fa_03ec55c42e6c4002b3235f659a9beb4b~mv2.jpg',1401,1401,'2SPdngVJBI9rG3omxvp7yj','https://open.spotify.com/album/2SPdngVJBI9rG3omxvp7yj','https://music.apple.com/fr/album/l%C3%A9cole-du-micro-dargent/698793153','https://www.youtube.com/results?search_query=IAM+L%27%C3%89cole+du+micro+d%27argent+full+album',false),
('5ee93fe0-8a54-4c5f-a567-06b6178dd1fe','life-after-death','Life After Death','The Notorious B.I.G.',1997,'1990s','Bad Boy Records','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['East Coast hip-hop','Mafioso rap']::text[],'Photography by Michael Lavine; styling by Groovey Lew','<p>Michael Lavine got almost no brief for Life After Death. "I was told, ''Get a hearse.'' That''s all the direction I got," he said. Sean Combs rejected the first graveyard pictures as not dramatic enough, so Lavine drove around on his lunch break and found a spot at the top of Cypress Hills Cemetery on the Brooklyn and Queens border.</p><p>The shoot took place on 24 January 1997. Biggie wore a long black coat and a bowler hat and leaned on a cane, because his left leg had been shattered in a car accident months earlier. He stands beside a hearse with the licence plate B.I.G., and a smoke machine fills the space around him. Lavine shot in black and white because he wanted the picture to feel timeless and to make Biggie seem "bigger than life."</p><p>On 9 March 1997 the Notorious B.I.G. was shot and killed, and the album was released sixteen days later, on 25 March. Lavine said the death gave the photograph a deeper meaning and "changed the whole dynamic." Groovey Lew styled the shoot.</p>','#58403C','#AE9A99','https://static.wixstatic.com/media/b519fa_ac0d5c5817c84f3884a4c90c3afe4537~mv2.jpg',2000,2000,'4oVdpzxBJM1KrBm9cjyye7','https://open.spotify.com/album/4oVdpzxBJM1KrBm9cjyye7','https://music.apple.com/us/album/life-after-death-2014-remaster/906888433','https://www.youtube.com/results?search_query=The+Notorious+B.I.G.+Life+After+Death+full+album',false),
('3bae9e4b-9d3e-4ece-a004-9d6e8d4165b3','sobrevivendo-no-inferno','Sobrevivendo no Inferno','Racionais MC''s',1997,'1990s','Cosa Nostra','Brazil','c0217d82-6644-4ea9-99d1-67b7e9dbe7a7',array['Political hip-hop','Gangsta rap']::text[],'Art direction by Marcos Marques, based on Mano Brown''s cross tattoo','<p>The cover of Racionais MC''s 1997 album, whose title means Surviving in Hell, is almost entirely black. A golden cross sits in the middle, the group''s name runs across the top in red gothic letters, and a few lines of small text quote Psalm 23:3: "Refrigere minha alma e guia-me pelo caminho da justiça," restore my soul and guide me along the path of justice.</p><p>The first idea was a photograph of the group in front of a church with Edinho, the son of Pelé. That idea was dropped, and art director Marcos Marques based the design on the cross tattoo on Mano Brown''s arm, so the sleeve carries a mark the rapper wore on his own body. On a record about life and death in the periphery of São Paulo, the cross reads as faith, mourning and protection at once.</p><p>Released independently on the group''s Cosa Nostra label on 20 December 1997, it became the best-selling rap album in Brazilian history, with around 1.5 million copies sold by 2010. In 2018 the University of Campinas added it to its entrance exam reading list, the first album to be included, and Companhia das Letras published its lyrics as a book.</p>','#131110','#F4DB77','https://static.wixstatic.com/media/b519fa_89704ec6ba604d148839b14b782b5e52~mv2.jpg',1400,1400,'1UzrzuOmZfBgXyS3pgKD10','https://open.spotify.com/album/1UzrzuOmZfBgXyS3pgKD10','https://music.apple.com/br/album/sobrevivendo-no-inferno/1198315004','https://www.youtube.com/results?search_query=Racionais+MC''s+Sobrevivendo+no+Inferno+full+album',false),
('6a51353d-8e9b-48b2-8920-4d2bac0d3df0','supa-dupa-fly','Supa Dupa Fly','Missy Elliott',1997,'1990s','The Goldmind','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Alternative hip-hop','Avant-funk']::text[],'Photography by Kwaku Alston; design by Gregory Burke; art direction by Starr Foundation','<p>When stylist June Ambrose was brought onto the Supa Dupa Fly project, the label asked how she would sell Missy Elliott to mainstream America. Her answer was to make Missy a "modern day cartoon character," a bold and playful image.</p><p>The cover, photographed by Kwaku Alston, shows Missy reclining on a cream sofa against deep red curtains, relaxed and fully in charge, with the album title stacked in red beside her. The same campaign produced the inflatable black suit Ambrose built for the video to "The Rain," directed by Hype Williams, which became one of the defining looks of late-1990s hip-hop.</p><p>Missy has kept the image close. For Halloween in 2019 she recreated the cover twenty-two years later and posted the two photos side by side, and they looked so alike that, she joked, even her mother could not tell which was new. The album was released on 15 July 1997. Gregory Burke designed the package, with art direction by Starr Foundation.</p>','#856B3E','#910C23','https://static.wixstatic.com/media/b519fa_189eca15103445eab85fcef5889b9076~mv2.jpg',1448,1448,'6UkdyvPElK6JDkyeRClbI2','https://open.spotify.com/album/6UkdyvPElK6JDkyeRClbI2','https://music.apple.com/us/album/supa-dupa-fly/302943429','https://www.youtube.com/results?search_query=Missy+Elliott+Supa+Dupa+Fly+full+album',false),
('7cee8a57-4c63-4724-afb5-1f3650e30f7e','wu-tang-forever','Wu-Tang Forever','Wu-Tang Clan',1997,'1990s','Loud / RCA','United States','c0217d82-6644-4ea9-99d1-67b7e9dbe7a7',array['East Coast hip-hop','Hardcore hip-hop']::text[],null,'<p>The cover of Wu-Tang Forever is dominated by the Clan''s emblem, a silver Wu-Tang W set inside a globe, glowing over a dark background, while the members appear as small figures along the bottom, under the title in large silver letters.</p><p>Four years after Enter the Wu-Tang (36 Chambers) and a string of classic solo albums, the Clan returned with a double album of 29 tracks. Wu-Tang Forever was released on 3 June 1997 and debuted at number one, led by "Triumph," a nearly six-minute posse cut with no chorus.</p><p>The cover shows how big the group had become. The logo, first drawn by Mathematics for "Protect Ya Neck," now stood for a worldwide brand of records, clothing and solo careers, and the image of the W over the world turned that empire into a picture.</p>','#050605','#ABAAA7','https://static.wixstatic.com/media/b519fa_c05cf7826c1341b8bfb62d01f20ce363~mv2.jpg',600,600,'4r3TaXjF2b1qwCpxjIpW43','https://open.spotify.com/album/4r3TaXjF2b1qwCpxjIpW43','https://music.apple.com/us/album/wu-tang-forever/268503472','https://www.youtube.com/results?search_query=Wu-Tang+Clan+Wu-Tang+Forever+full+album',false),
('7325a2ab-9abe-4793-aac4-3b6280e1a8fb','all-eyez-on-me','All Eyez on Me','2Pac',1996,'1990s','Death Row / Interscope','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['West Coast hip-hop','Gangsta rap']::text[],'Photography by Ken Nahoum','<p>2Pac recorded All Eyez on Me straight after leaving prison and signing with Death Row Records, and the cover introduces the new Pac. He is shirtless except for the black leather strap of a Jean Paul Gaultier vest, his tattoos and jewellery on show, holding his Death Row pendant up towards the camera.</p><p>The photograph was taken by Ken Nahoum, Death Row''s photographer at the time and the man behind some of 2Pac''s most famous images. Juxtapoz described the result as flashier than his earlier style, with Pac staring into the lens in open defiance. In the magazine''s words, all eyes are on him, and he knows it.</p><p>All Eyez on Me was released on 13 February 1996 as a double album and was later certified Diamond in the United States. Seven months after its release 2Pac was shot in Las Vegas and died at 25, and the cover became the lasting image of his final year.</p>','#030305','#9A7069','https://static.wixstatic.com/media/b519fa_cea81cc607804d73be25d82a4e78b2f9~mv2.jpg',3000,3000,'78iX7tMceN0FsnmabAtlOC','https://open.spotify.com/album/78iX7tMceN0FsnmabAtlOC','https://music.apple.com/us/album/all-eyez-on-me/1588480719','https://www.youtube.com/results?search_query=2Pac+All+Eyez+on+Me+full+album',false),
('a8bbb76a-3c9c-4df6-9636-008b3c920012','atliens','ATLiens','OutKast',1996,'1990s','LaFace / Arista','United States','cac97ec2-47e9-4562-b1b0-ebb5ae534086',array['Southern hip-hop','Alternative hip-hop']::text[],'Creative direction and cover design by D.L. Warfield; comic story by Big Rube','<p>OutKast''s second album turned André 3000 and Big Boi into comic-book heroes. The cover shows the two of them braced for battle in a palette of deep blue, green and black, while dark forces reach towards them, an Afrofuturist superhero team from Atlanta.</p><p>The artwork was led by D.L. Warfield, then creative director at LaFace Records, who also oversaw a full comic booklet tucked inside the packaging. Its story was written by Big Rube, the Dungeon Family''s spoken-word poet. Warfield''s route to the job is part of the legend: after being passed over as too young, he reportedly mailed label boss L.A. Reid a fake bomb with a note reading "Hire D.L. Warfield or else," and got the job. Reid has said he has no recollection of it.</p><p>ATLiens was released on 27 August 1996 and confirmed OutKast as the most adventurous group in Southern rap. The comic-book cover has since inspired action figures, and it remains one of the defining images of the duo''s space-age phase.</p>','#1A2019','#ACC189','https://static.wixstatic.com/media/b519fa_24516dff3764432496bbbee4b4e51359~mv2.jpg',3000,3000,'1IaBCF26OjgYwUCEPaIyC0','https://open.spotify.com/album/1IaBCF26OjgYwUCEPaIyC0','https://music.apple.com/us/album/atliens/263570527','https://www.youtube.com/results?search_query=OutKast+ATLiens+full+album',false),
('649f8344-add0-4642-b774-cf799b8af5f8','hard-core','Hard Core','Lil'' Kim',1996,'1990s','Big Beat Records','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['East Coast hip-hop','Dirty rap']::text[],'Photography by Michael Lavine','<p>Michael Lavine photographed Lil'' Kim on 30 July 1996 in a rented brownstone at 24 West 10th Street in Manhattan. His notes from her management described her as "the other woman" and asked for a look that was "Not raunchy," listing "Classy, sexy, lush, lustful." For the cover set, flowers were arranged in front of the fireplace and a bearskin rug was brought in.</p><p>The cover shows Kim in a bikini on that rug, surrounded by furs and red roses. The same session produced the famous squat pose, which was never planned. "There was no layout for her to do that pose. It just was natural," Lavine said. That image became the "Lil Kim Coming Soon" poster, and Lavine believes it "put her on the map" even more than the sleeve did.</p><p>Lavine said he felt uncomfortable sexualising women and saw the pictures as empowering. The campaign introduced a rapper presenting her sexuality on her own terms. Hard Core was released on 12 November 1996 by Undeas, Big Beat and Atlantic.</p>','#C79A86','#A65B58','https://static.wixstatic.com/media/b519fa_b29dac0181ed4fc7b65740b0a7a6bffb~mv2.jpg',1429,1411,'39xHAZmTUSQJyXt6ebpjKT','https://open.spotify.com/album/39xHAZmTUSQJyXt6ebpjKT','https://music.apple.com/us/album/hard-core/321976585','https://www.youtube.com/results?search_query=Lil''+Kim+Hard+Core+full+album',false),
('44ce6679-008f-483e-96be-b0c2a97e6c0d','it-was-written','It Was Written','Nas',1996,'1990s','Columbia','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['East Coast hip-hop','Mafioso rap']::text[],'Art direction and design by Aimée Macauley; photography by Danny Clinch','<p>After Illmatic made him the most respected young rapper in New York, Nas returned with a bigger, glossier second album. Its cover is a warm, sepia-toned close-up of his face, blended with a faded image of city apartment blocks, under his name in metallic letters.</p><p>The art direction and design are credited to Aimée Macauley, with photography by Danny Clinch, the photographer known for his portraits of musicians from Bruce Springsteen to Tupac. The concept came from Nas himself. His manager Steve Stoute told Complex that the team worked on the cover together, "but it was Nas'' idea," and that it showed Nas as a kid and then as a man.</p><p>It Was Written was released on 2 July 1996 and debuted at number one, carried by "If I Ruled the World (Imagine That)" with Lauryn Hill. The image of the boy growing into the man matched an album about Nas stepping out of Queensbridge into stardom.</p>','#92664F','#C49972','https://static.wixstatic.com/media/b519fa_1537a9956f8f4d2eb1354ad3c4ba9cde~mv2.jpg',600,600,'78Fgb88MY0ECc4GVMejqTg','https://open.spotify.com/album/78Fgb88MY0ECc4GVMejqTg','https://music.apple.com/us/album/it-was-written/211507540','https://www.youtube.com/results?search_query=Nas+It+Was+Written+full+album',false),
('7c53aec2-1947-4369-9076-9fae201cb777','mucho-barato','Mucho Barato','Control Machete',1996,'1990s','Universal Latino','Mexico','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['Latin hip-hop','Mexican hip-hop']::text[],null,'<p>The members of Control Machete appear in front of a weathered building on the cover of their debut, in a warm, rounded photograph, with the group''s name in a green oval logo at the top left.</p><p>The trio from Monterrey, Fermín IV, Pato and Toy Selectah, mixed hard hip-hop beats with Mexican sounds, samples and slang on songs like "¿Comprendes Mendes?" and "Andamos armados." Mucho Barato sold widely across Latin America and is regarded as a seminal work in Spanish-language hip-hop.</p><p>The plain, street-level cover fits a record that put northern Mexico on the hip-hop map. Monterrey''s rap scene grew from the path Control Machete cut.</p>','#A37C6B','#D7D1AF','https://static.wixstatic.com/media/b519fa_ab7ed233e4a14fc6b72986f5568b8726~mv2.jpg',3000,3000,'12Fkvf2oi1B6yjDwkMrUog','https://open.spotify.com/album/12Fkvf2oi1B6yjDwkMrUog','https://music.apple.com/us/album/mucho-barato/1595217247','https://www.youtube.com/results?search_query=Control+Machete+Mucho+Barato+full+album',false),
('eb35f10e-cb54-4559-ac32-f58831418115','reasonable-doubt','Reasonable Doubt','Jay-Z',1996,'1990s','Roc-A-Fella Records','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Mafioso rap','East Coast hip-hop']::text[],'Photography by Jonathan Mannion; art direction and design by Adrien Vargas; artwork by Cey Adams','<p>Jonathan Mannion won the Reasonable Doubt job by quoting Damon Dash "$300 less than your lowest bid." The album was first titled Heir to the Throne, and when it was renamed Mannion shifted to old-school crime imagery. His advice to the team was direct: "Stay Brooklyn. Go John Gotti, mafia, surveillance."</p><p>Jay-Z, Dash and Kareem "Biggs" Burke agreed on black and white to make a statement. Mannion wanted to present Jay-Z "as this timeless character from Brooklyn, styled out, sharp, and clean," and to avoid the busy styles of the time: "Let''s create your own lane." The main shoot took place on the roof of Mannion''s building at West 72nd Street and Riverside Drive in Manhattan, where he shot about 30 rolls of film.</p><p>Art director Adrien Vargas designed the sleeve, noting that very few covers of the period were black and white. He said it was the first Roc-A-Fella release that truly stood out on store shelves. The album came out on 25 June 1996. Cey Adams contributed artwork to the package.</p>','#0C0B14','#3F3E45','https://static.wixstatic.com/media/b519fa_2584aa9514c047319489b29f133a1a6b~mv2.jpg',1500,1500,'3YPK0bNOuayhmSrs0sIIBR','https://open.spotify.com/album/3YPK0bNOuayhmSrs0sIIBR','https://music.apple.com/us/album/reasonable-doubt/1475940563','https://www.youtube.com/results?search_query=Jay-Z+Reasonable+Doubt+full+album',false),
('36ff6362-f7f0-41fc-b526-916bce93764d','ridin-dirty','Ridin'' Dirty','UGK',1996,'1990s','Jive','United States','27d91a37-0b27-477a-b65d-82e9697175da',array['Southern hip-hop','Texas rap']::text[],null,'<p>UGK''s third album shows Pimp C and Bun B in the back of a car at night, looking out over their shoulders, with the group''s red crest logo in the centre and the title in gold script below. Bun B told Complex that the cover is meant to be the two of them looking back as carjackers approach, and the inner sleeve shows the Botany Boyz playing the carjackers.</p><p>The duo from Port Arthur, Texas made Ridin'' Dirty with almost no radio play or video support, and it still sold strongly on word of mouth. Pimp C''s slow, soulful production and Bun B''s precise verses on songs like "One Day" and "Murder" made it the blueprint for Texas rap.</p><p>Ridin'' Dirty was released on 30 July 1996. The car on the cover belonged to their friend C-Note, and the image of the two men watching their backs fits an album full of danger, loss and survival. Pimp C died in 2007, and the record remains the most respected in Southern rap.</p>','#1E1C1F','#CCA332','https://static.wixstatic.com/media/b519fa_cb4c9971e0c14d9d84549ef309d612fc~mv2.jpg',3000,3000,'4jTPQq9PSlKMOm1yLx2ATN','https://open.spotify.com/album/4jTPQq9PSlKMOm1yLx2ATN','https://music.apple.com/us/album/ridin-dirty/268522887','https://www.youtube.com/results?search_query=UGK+Ridin%27+Dirty+full+album',false),
('d4095a57-8c76-4f16-84f5-607eb81e4639','the-don-killuminati-the-7-day-theory','The Don Killuminati: The 7 Day Theory','Makaveli',1996,'1990s','Death Row Records','United States','6cbdce99-93a5-4ccd-adbc-b5e907e3ee7e',array['Gangsta rap','West Coast hip-hop']::text[],'Painting by Ronald "Riskie" Brent','<p>Death Row''s Suge Knight introduced Tupac to Ronald "Riskie" Brent, a Compton artist known as Riskie Forever. After looking through his portfolio, Tupac asked him to paint the next album cover and told him he wanted to be shown on a cross.</p><p>Brent''s painting draws on Renaissance images of the crucifixion. Tupac hangs alone with his head tilted and a wound in his side, a bandana over his head and barbed wire around his hands and feet. A map on the cross links cities with large African-American populations, and light breaks through cracks in the wood that may stand for bullet holes. Near the bottom runs a disclaimer: "In no way is this portrait an expression of disrespect for Jesus Christ." It is signed Makaveli.</p><p>The image has been read as Tupac''s sense of being vilified by the media and his enemies, and its meaning darkened with events. Tupac died in September 1996, and the album, recorded under the name Makaveli, was released two months later, on 5 November 1996.</p>','#956F25','#5C4132','https://static.wixstatic.com/media/b519fa_999fbe8ae2e54c2fb73de38cb505612f~mv2.jpg',3000,3000,'2gWrUaBkh1uQARjbjvUGNp','https://open.spotify.com/album/2gWrUaBkh1uQARjbjvUGNp','https://music.apple.com/us/album/the-don-killuminati-the-7-day-theory/1588164338','https://www.youtube.com/results?search_query=Makaveli+The+Don+Killuminati:+The+7+Day+Theory+full+album',false),
('82399e52-5256-4b71-a04c-9fd53387150b','the-score','The Score','Fugees',1996,'1990s','Ruffhouse / Columbia','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['Alternative hip-hop','East Coast hip-hop']::text[],null,'<p>The cover of The Score shows the three Fugees, Lauryn Hill, Wyclef Jean and Pras Michel, in dark, close-up portraits, their faces emerging from deep shadow, with the title in gold at the bottom like the poster for a heist film.</p><p>The trio from New Jersey mixed rap with soul, reggae and Caribbean sounds, and their cover of Roberta Flack''s "Killing Me Softly" became a worldwide hit. Released on 13 February 1996, The Score won the Grammy for Best Rap Album and became one of the best-selling hip-hop albums of all time.</p><p>The film noir look fits the title and the group''s love of cinematic storytelling on songs like "Ready or Not" and "Fu-Gee-La." It was the group''s final album, and the cover is the lasting image of Lauryn Hill just before her solo career made her one of the most celebrated artists of her generation.</p>','#0D0F12','#A96846','https://static.wixstatic.com/media/b519fa_7e7f8b9cc4dd4442bccc918b8cac080c~mv2.jpg',3000,3000,'4z6F5s3RVaOsekuaegbLfD','https://open.spotify.com/album/4z6F5s3RVaOsekuaegbLfD','https://music.apple.com/us/album/the-score/1054461239','https://www.youtube.com/results?search_query=Fugees+The+Score+full+album',false),
('88561a6c-8dfa-49c8-960c-99e0b08a91a3','e-1999-eternal','E. 1999 Eternal','Bone Thugs-n-Harmony',1995,'1990s','Ruthless / Relativity','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['Midwest hip-hop','Melodic rap']::text[],'Cover by Quentin Frost; design and art direction by Don Cunningham','<p>Bone Thugs-n-Harmony, five rappers from Cleveland, Ohio, invented a rapid, harmonised flow that sounded like nothing else in rap. The cover of their second album shows the group standing together on a city street at dusk, washed in deep red and brown light under their name. The title points to East 99th Street, the corner in Cleveland where they came up.</p><p>The album credits the cover to Quentin Frost, with design and art direction by Don Cunningham. The dark, warm tones match the album''s mood of mourning and the supernatural, from its prayers to its songs about death.</p><p>The group had been signed by Eazy-E to his label Ruthless Records, and he died in March 1995, four months before the album came out on 25 July 1995. Its single "Tha Crossroads," a tribute to him and to friends they had lost, went to number one and won a Grammy, and the melodic style of E. 1999 Eternal still echoes through rap today.</p>','#3E2419','#A97B59','https://static.wixstatic.com/media/b519fa_637e0c7e00ff4eb1bd61aa2a503828cf~mv2.jpg',1500,1500,'4sypiS7IyD5hcjIeDMfAmy','https://open.spotify.com/album/4sypiS7IyD5hcjIeDMfAmy','https://music.apple.com/us/album/e-1999-eternal/1168166996','https://www.youtube.com/results?search_query=Bone+Thugs-n-Harmony+E.+1999+Eternal+full+album',false),
('2e65841c-d288-47df-8031-271643c7e76a','liquid-swords','Liquid Swords','GZA',1995,'1990s','Geffen Records','United States','cac97ec2-47e9-4562-b1b0-ebb5ae534086',array['Hardcore hip-hop','East Coast hip-hop']::text[],'Cover design by Denys Cowan; inks by Prentis Rollins; colour by Jason Scott Jones; concept by GZA','<p>GZA built the Liquid Swords cover around his love of chess. His concept was a chessboard where the pieces are sword-wielding warriors locked in battle, a fusion of chess strategy and the kung fu films that run through the Wu-Tang Clan''s music.</p><p>To draw it, GZA''s manager Geoffrey L. Garfield commissioned Denys Cowan, the comic book artist who founded Milestone Media. Cowan''s black-and-white line art was inked by Prentis Rollins and coloured digitally by Jason Scott Jones, Milestone''s colour editor, and the work was supervised through GZA GrafX, a company owned by GZA and Garfield.</p><p>Wu-Tang DJ Mathematics adapted the group''s famous W logo into a G for GZA. The result looks like the cover of a comic book, a style that matched the album''s cinematic tone. Liquid Swords was released by Geffen on 7 November 1995.</p>','#121215','#516768','https://static.wixstatic.com/media/b519fa_b0f748194ceb4e3d986f1bfdfd3c2e41~mv2.jpg',1800,1800,'3k8xoyOXkGgZxUKgpmxz4P','https://open.spotify.com/album/3k8xoyOXkGgZxUKgpmxz4P','https://music.apple.com/us/album/liquid-swords/1440835438','https://www.youtube.com/results?search_query=GZA+Liquid+Swords+full+album',false),
('4c0a9791-6f3e-44e2-855d-c448ab3d6c97','me-against-the-world','Me Against the World','2Pac',1995,'1990s','Interscope / Out da Gutta','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['West Coast hip-hop','Gangsta rap']::text[],'Art direction and design by Eric Altenburger','<p>2Pac''s third album is his most reflective, and the cover shows a quieter Pac. In a black-and-white photograph he leans against a wall, looking off to the side with a serious, faraway expression, with his name and the title in small type at the top.</p><p>The art direction and design are credited to Eric Altenburger. The cover''s calm contrasts with what was happening to 2Pac at the time: he had survived being shot five times in a New York studio lobby in November 1994, and he was in prison when the album came out. In 2021 the artist Umar Rashid repainted the cover in acrylic and spray paint, and LACMA in Los Angeles has featured the painting.</p><p>Me Against the World was released on 14 March 1995 and debuted at number one, making 2Pac the first artist to top the Billboard 200 while serving a prison sentence. Its song "Dear Mama" was later added to the Library of Congress''s National Recording Registry.</p>','#121414','#A18461','https://static.wixstatic.com/media/b519fa_d6b78f928afc4edcb863e734004fdaf6~mv2.jpg',1411,1411,'3OrucS4sHv6Bl9GS4rafEk','https://open.spotify.com/album/3OrucS4sHv6Bl9GS4rafEk','https://music.apple.com/us/album/me-against-the-world/1440509542','https://www.youtube.com/results?search_query=2Pac+Me+Against+the+World+full+album',false),
('058d93c4-8634-479b-a1b0-71dbde37f4b7','mystic-stylez','Mystic Stylez','Three 6 Mafia',1995,'1990s','Prophet','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['Memphis rap','Horrorcore']::text[],null,'<p>The cover of Three 6 Mafia''s debut looks like a horror film poster. The Memphis crew crowd together in dark hoods and shadows against a blood-red background, with the title in jagged yellow and red letters at the bottom and "DJ Paul & Juicy J" printed at the top.</p><p>Mystic Stylez, released on 23 May 1995, captured the sound DJ Paul and Juicy J had built on cassette tapes in Memphis: slow, menacing drum machines, eerie samples and chanted hooks about the occult and street violence. Songs like "Da Summa" and "Tear Da Club Up" spread hand to hand across the South.</p><p>The dark, occult imagery matched a sound that later generations would borrow again and again. Trap producers, Atlanta rappers and the internet''s phonk scene have all sampled or imitated the Memphis style that Mystic Stylez introduced, and Three 6 Mafia went on to win an Academy Award in 2006.</p>','#070607','#B36458','https://static.wixstatic.com/media/b519fa_c2ebc4c17f7b42a7b3d710d17dd4f033~mv2.jpg',1400,1400,'0UkKpqa0G6CpgFIpsiIgsX','https://open.spotify.com/album/0UkKpqa0G6CpgFIpsiIgsX','https://music.apple.com/us/album/mystic-stylez/332165657','https://www.youtube.com/results?search_query=Three+6+Mafia+Mystic+Stylez+full+album',false),
('12f0eed6-8895-45a1-94ec-e4beda38eaf6','only-built-4-cuban-linx','Only Built 4 Cuban Linx...','Raekwon',1995,'1990s','Loud Records','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['Mafioso rap','East Coast hip-hop']::text[],'Photography by Daniel Hastings; design by Miguel Rivera; set and logo design by Christian Cortes','<p>Raekwon asked for photographer Daniel Hastings, who had already shot the cover of Wu-Tang Clan''s Enter the Wu-Tang (36 Chambers). For his solo debut, Raekwon wanted the moment shared: he put himself and Ghostface Killah together on the front, two men in a haze of warm orange light, since Ghost was being introduced to listeners through the record.</p><p>Hastings said Raekwon "wanted a Last Supper where all the Wu-Tang members are there," and he claims to be one of the only photographers to get the whole Wu family into one picture. The session was tense, with the group''s success already straining relationships. "Not everyone was happy," Hastings recalled, and he tried to let that friction show.</p><p>The packaging gave the album its nickname. The original cassette was moulded in solid purple plastic, which Raekwon chose as a reference to the way drug dealers marked their product, and fans have called the record "The Purple Tape" ever since. It was released on 1 August 1995. Miguel Rivera designed the package, and Christian Cortes built the set and designed the logo.</p>','#2F1712','#CB853F','https://static.wixstatic.com/media/b519fa_5113df6c1c5f4efaa74ee760554273b8~mv2.jpg',3000,3000,'7btiyhWzUfzxN3ijSiBpC8','https://open.spotify.com/album/7btiyhWzUfzxN3ijSiBpC8','https://music.apple.com/us/album/only-built-4-cuban-linx/258634938','https://www.youtube.com/results?search_query=Raekwon+Only+Built+4+Cuban+Linx...+full+album',false),
('8a9c1406-ad13-46a1-96ed-27076384bc5f','paris-sous-les-bombes','Paris sous les bombes','Suprême NTM',1995,'1990s','Epic','France','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['French hip-hop','Hardcore hip-hop']::text[],null,'<p>JoeyStarr and Kool Shen of Suprême NTM press their heads together on the cover of their third album, in a cold blue photograph, with the giant letters NTM below them and the title in white across the middle.</p><p>The title means Paris under the bombs, a reference to graffiti "bombing," the culture in which the duo started. Released in 1995, the album carried "La Fièvre," "Qu''est-ce qu''on attend" and "Tout n''est pas si facile" and captured the anger of the Paris suburbs in the year of the film La Haine.</p><p>The two heads pressed together show a partnership at its tightest, and the cold colours match the mood of a France facing riots and racism. The album is widely considered the classic of Parisian rap.</p>','#11181C','#6B94A3','https://static.wixstatic.com/media/b519fa_447a98612d654d9baf5eb2800de837c6~mv2.jpg',1500,1500,'5xPygvHXQKEgpTt1Pm8Jbk','https://open.spotify.com/album/5xPygvHXQKEgpTt1Pm8Jbk','https://music.apple.com/fr/album/paris-sous-les-bombes/273708033','https://www.youtube.com/results?search_query=Supr%C3%AAme+NTM+Paris+sous+les+bombes+full+album',false),
('7efb228a-9104-45cd-8894-cf666c5b44e9','return-to-the-36-chambers-the-dirty-version','Return to the 36 Chambers: The Dirty Version','Ol'' Dirty Bastard',1995,'1990s','Elektra Records','United States','c0217d82-6644-4ea9-99d1-67b7e9dbe7a7',array['Hardcore hip-hop','East Coast hip-hop']::text[],'Art direction by Alli; photography by Danny Clinch','<p>Ol'' Dirty Bastard''s solo debut is packaged as a food stamp identification card. The cover reproduces a laminated welfare ID, complete with his photograph, his signature and the album title typed where the personal details should be, issued by the "City of Brooklyn Zoo."</p><p>The joke was rooted in his real life. Writers have pointed to the cover as proof of his humour and of how openly he lived his public persona. While the album was in the top ten, MTV filmed him riding to the welfare office to cash a check and collect food stamps, and his eligibility was later revoked, with the episode cited as an example of welfare abuse.</p><p>The card became so famous that a later deluxe box set included a laminated reproduction of it. Art direction was by Alli, with photography by Danny Clinch, and the album was released by Elektra on 28 March 1995.</p>','#AFADAC','#484953','https://static.wixstatic.com/media/b519fa_e93d380d4f884c92840064697d99fa10~mv2.jpg',1425,1425,'4tI4WJdTN5MzDMRMl2i7VR','https://open.spotify.com/album/4tI4WJdTN5MzDMRMl2i7VR','https://music.apple.com/us/album/return-to-the-36-chambers/332667010','https://www.youtube.com/results?search_query=Ol''+Dirty+Bastard+Return+to+the+36+Chambers:+The+Dirty+Version+full+album',false),
('2343ac24-2b73-4f70-ba3e-d22f2896ddb8','the-infamous','The Infamous','Mobb Deep',1995,'1990s','Loud / RCA','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['East Coast hip-hop','Hardcore hip-hop']::text[],'Photography by Chi Modu','<p>The cover of Mobb Deep''s second album is a tight, close portrait of Havoc and Prodigy, the Queensbridge duo, staring out from a plain black background. Nothing else is on it, only two young faces and the group''s name, and it set the cold, paranoid mood of the record before a note was played.</p><p>The photograph was taken by the late Chi Modu, one of the defining photographers of 1990s rap. He spent a day with Havoc and Prodigy in Queensbridge, shooting them in everyday moments, and ran a second session in the studio that produced the cover. Modu pushed the film to deepen the colours and split the focus, keeping Prodigy soft and Havoc sharp.</p><p>The Infamous was released on 25 April 1995 and became one of the cornerstones of East Coast hardcore rap. Havoc later told BET that "a huge part of our success was that cover."</p>','#1C171E','#9B604E','https://static.wixstatic.com/media/b519fa_7b384aa9887f4401a0acee4786cf98fb~mv2.jpg',1500,1500,'1cCAb1vN8uUsdfEylVmTLs','https://open.spotify.com/album/1cCAb1vN8uUsdfEylVmTLs','https://music.apple.com/us/album/the-infamous/255342338','https://www.youtube.com/results?search_query=Mobb+Deep+The+Infamous+full+album',false),
('ad13eeb5-71ec-449c-8492-5b81379ff97a','illmatic','Illmatic','Nas',1994,'1990s','Columbia Records','United States','52e1479f-82f9-46b7-86e4-f22d676e06cc',array['East Coast hip-hop','Hardcore hip-hop']::text[],'Design by Aimée Macauley; photography by Danny Clinch','<p>The first plan for the cover of Illmatic was a shock image: Nas holding Jesus Christ in a headlock, a nod to the religious provocations of his verse on "Live at the Barbeque". What Columbia released instead was quieter and far more powerful. Designer Aimée Macauley took a childhood photograph of Nas, taken around the time his father, the musician Olu Dara, came home from a tour, and laid it over a photograph of a city block, with photography credited to Danny Clinch.</p><p>Nas was about seven in the picture, an age he later described as "the year I started to acknowledge everything around me." His afro, he said, was inspired by Michael Jackson. The ghostly child superimposed on the streets turns the album into a memory of growing up in the Queensbridge housing projects, the same streets the lyrics map in detail. The idea may have had a model: Ego Trip reported that the design was reputedly inspired by the 1974 jazz album A Child Is Born, whose cover also places a child over an urban scene.</p><p>Illmatic was the first hip-hop album to put a child on its cover, and the idea spread fast. Within months The Notorious B.I.G.''s Ready to Die appeared with a baby on the front, and the comparison was made openly on record. NME later wrote that the image shows "how easily innocence is lost in NY''s neglected concrete jungles." The album was released on 19 April 1994.</p>','#684A3D','#A88E74','https://static.wixstatic.com/media/b519fa_761368c584774181bcd36dddcd8d54b4~mv2.jpg',3000,3000,'3kEtdS2pH6hKcMU9Wioob1','https://open.spotify.com/album/3kEtdS2pH6hKcMU9Wioob1','https://music.apple.com/us/album/illmatic/662324135','https://www.youtube.com/results?search_query=Nas+Illmatic+full+album',false),
('056d6488-5e92-4223-bce3-c2a65032e12c','ready-to-die','Ready to Die','The Notorious B.I.G.',1994,'1990s','Bad Boy Records','United States','52e1479f-82f9-46b7-86e4-f22d676e06cc',array['East Coast hip-hop','Gangsta rap']::text[],'Photography by Butch Belair; art direction and design by The Drawing Board','<p>The debut album of one of hip-hop''s most imposing figures has a baby on the front. Against a plain white background, an infant with a small afro sits in close-up, looking straight out of the frame, with the title spelled in lowercase beneath. The joke and the threat sit side by side: the record is called Ready to Die, and the cover shows the very beginning of a life.</p><p>That was the point of the concept, which follows the artist from birth to death. The album opens with the sound of a birth and ends with "Suicidal Thoughts", and the baby on the sleeve is the first chapter of that story. Butch Belair took the photograph, and The Drawing Board handled art direction and design for Bad Boy. The baby resembled the rapper, and fans long assumed it was a picture of Christopher Wallace himself. In 2011 the New York Daily News suggested the child was a Bronx teenager named Keithroy Yearwood, though Bad Boy could not confirm it.</p><p>The cover arrived on 13 September 1994, five months after Nas had put his own childhood photo on Illmatic, and other rappers noticed. A Raekwon track featuring Ghostface Killah the next year mocked the baby cover as a copy. The comparison did not hurt either record. The image has since been listed among the best covers in hip-hop.</p>','#FBFBFB','#90817F','https://static.wixstatic.com/media/b519fa_1ccd3fc504a4486eba229c4f671778fc~mv2.jpg',640,640,'5vzC8CgZMeaBubitu2rK6m','https://open.spotify.com/album/5vzC8CgZMeaBubitu2rK6m','https://music.apple.com/us/album/ready-to-die-the-remaster/204669326','https://www.youtube.com/results?search_query=The+Notorious+B.I.G.+Ready+to+Die+full+album',false),
('97d3bea9-bd72-4f9f-8175-6e4567499dee','resurrection','Resurrection','Common',1994,'1990s','Relativity','United States','c0217d82-6644-4ea9-99d1-67b7e9dbe7a7',array['Conscious hip-hop','Jazz rap']::text[],null,'<p>The cover of Common''s second album is split in two. On the left a shadowy figure stands in dark blue, and on the right a pale panel carries a thin green line like a growing vine, with his name and the title in small lowercase type.</p><p>Released in October 1994 under the name Common Sense, Resurrection paired the Chicago rapper with the producer No I.D., whose soulful jazz loops gave him room to stretch. Its centrepiece, "I Used to Love H.E.R.," tells the story of hip-hop as a woman who has drifted from her roots, one of the most famous extended metaphors in rap.</p><p>The quiet, minimal cover matched a record about reflection and growth. "I Used to Love H.E.R." set off a long-running feud with Ice Cube and established Common as one of the leading voices of conscious rap, and No I.D. later became a mentor to Kanye West.</p>','#0A1A14','#4886A8','https://static.wixstatic.com/media/b519fa_cab3d573975048e186b9b01c21be3963~mv2.jpg',600,600,'0JKjuvDUPrnlblAZyB1Aje','https://open.spotify.com/album/0JKjuvDUPrnlblAZyB1Aje','https://music.apple.com/us/album/resurrection/267707382','https://www.youtube.com/results?search_query=Common+Resurrection+full+album',false),
('c5f3608b-4f7b-40e9-be76-ecaed7a76133','southernplayalisticadillacmuzik','Southernplayalisticadillacmuzik','OutKast',1994,'1990s','LaFace / Arista','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['Southern hip-hop','Dirty South']::text[],'Artwork by Christopher Stern; photography by Timothy White','<p>OutKast''s debut introduced André 3000 and Big Boi, two teenagers from East Point, Atlanta. The cover shows them up close, outlined in orange with their shadows falling across a deep purple and red background, the group''s logo above them and the long title running along the bottom.</p><p>The album credits the artwork to Christopher Stern and the photography to Timothy White. The moody colours and dramatic shadows gave the young duo the look of a classic soul record, a fitting start for a group that would mix funk, soul and rap more freely than anyone. A copy of the LP is now held by the Smithsonian''s National Museum of African American History and Culture.</p><p>Southernplayalisticadillacmuzik was released on 26 April 1994 and carried the single "Player''s Ball." When OutKast won Best New Rap Group at the 1995 Source Awards and the New York crowd booed, André answered with the line that announced Southern rap: "The South got something to say."</p>','#410E10','#8F2E2E','https://static.wixstatic.com/media/b519fa_6a4414bf0bf54c6d8fda1f2ebb5b4000~mv2.jpg',3000,3000,'3l5AwLKqQ42VJbc5lTuP8G','https://open.spotify.com/album/3l5AwLKqQ42VJbc5lTuP8G','https://music.apple.com/us/album/southernplayalisticadillacmuzik/266365233','https://www.youtube.com/results?search_query=OutKast+Southernplayalisticadillacmuzik+full+album',false),
('1c78fc41-daf2-4352-a637-70ff86cc85f2','the-diary','The Diary','Scarface',1994,'1990s','Rap-A-Lot','United States','27d91a37-0b27-477a-b65d-82e9697175da',array['Southern hip-hop','Gangsta rap']::text[],null,'<p>The cover of Scarface''s third solo album is bleak and quiet: a gritty, grey photograph of a bare interior, with the rapper''s name in heavy red letters at the top and the title in bold white at the bottom.</p><p>Scarface, already famous as a member of the Geto Boys, made The Diary into Southern rap''s most respected storytelling album. Songs like "I Seen a Man Die" and "Hand of the Dead Body" mixed street violence with paranoia, guilt and grief, and his deep, weary voice made him one of the most admired lyricists in rap.</p><p>The Diary was released on 18 October 1994 on Rap-A-Lot. The empty, colourless cover reads like the inside of a mind under pressure, a fitting image for an album that spends as much time on regret and depression as it does on bravado.</p>','#B4B3AD','#84665B','https://static.wixstatic.com/media/b519fa_26b5e03c5d31438eb8ff7238faba26f4~mv2.jpg',1400,1400,'6o5xjudCBr9hAdESwKtOZQ','https://open.spotify.com/album/6o5xjudCBr9hAdESwKtOZQ','https://music.apple.com/us/album/the-diary/1812986267','https://www.youtube.com/results?search_query=Scarface+The+Diary+full+album',false),
('c5172e2c-1a46-4006-ac05-7ec43280b1ae','93-til-infinity','93 ''til Infinity','Souls of Mischief',1993,'1990s','Jive','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['West Coast hip-hop','Underground hip-hop']::text[],null,'<p>The four members of Souls of Mischief appear in a hazy, layered green and gold photograph on the cover of their debut, their figures half dissolved into the background, with the group''s yellow logo in the top corner.</p><p>Souls of Mischief, part of Oakland''s Hieroglyphics crew, were teenagers when they made the album. A-Plus, Opio, Phesto and Tajai traded fast, intricate verses over jazzy, mellow beats, and the title track became one of the most loved songs of the decade, a laid-back anthem for a West Coast scene that had little to do with gangsta rap.</p><p>The dreamy, faded image suits the song''s mood of hanging out and looking ahead. Released in 1993, the album gave the Bay Area underground its classic and inspired generations of independent rappers who saw it as proof that skill and style could thrive outside the major-label mainstream.</p>','#665345','#968152','https://static.wixstatic.com/media/b519fa_44592087922746d8ade9e116053887b9~mv2.jpg',600,608,'7aSjaEi3OQ2aZemcJDhMb1','https://open.spotify.com/album/7aSjaEi3OQ2aZemcJDhMb1','https://music.apple.com/us/album/93-til-infinity/369570847','https://www.youtube.com/results?search_query=Souls+of+Mischief+93+%27til+Infinity+full+album',false),
('f879e2ae-333c-4ac3-85c2-d6821ea6d436','doggystyle','Doggystyle','Snoop Doggy Dogg',1993,'1990s','Death Row Records','United States','cac97ec2-47e9-4562-b1b0-ebb5ae534086',array['G-funk','West Coast hip-hop']::text[],'Artwork by Darryl "Joe Cool" Daniel','<p>The Doggystyle cover was drawn by Snoop''s cousin, Darryl "Joe Cool" Daniel. Snoop first saw Daniel''s drawings while Daniel was in prison, and after his release Daniel appeared on "Murder Was the Case" and drew the artwork for the album.</p><p>The cartoon fills the frame with Snoop''s world: a brick wall topped with dogs whose speech bubbles quote George Clinton''s 1982 single "Atomic Dog," a song Snoop sampled often, in a busy comic-book scene. Some critics argued that the drawing objectifies women, reading it as a match for the album''s lyrics about drugs, cars, sex and money.</p><p>Daniel never expected the attention. "I didn''t think it would be iconic," he said of the sleeve. Released on 23 November 1993 by Death Row and Interscope, Doggystyle debuted at the top of the Billboard 200, and Daniel''s drawing became one of the best-known illustrated covers in rap. He died in July 2024.</p>','#A44F48','#D4BD37','https://static.wixstatic.com/media/b519fa_95bb027c901444d398b09cac3fe5fc90~mv2.jpg',3000,3000,'5IFOummNcGXY3qCBWRchqP','https://open.spotify.com/album/5IFOummNcGXY3qCBWRchqP','https://music.apple.com/us/album/doggystyle/1676306182','https://www.youtube.com/results?search_query=Snoop+Doggy+Dogg+Doggystyle+full+album',false),
('619faef2-5318-41b4-b2ce-cbde69874c87','enter-the-wu-tang-36-chambers','Enter the Wu-Tang (36 Chambers)','Wu-Tang Clan',1993,'1990s','Loud / RCA Records','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['East Coast hip-hop','Hardcore hip-hop','Boom bap']::text[],'Photography by Daniel Hastings','<p>The masks on the cover of Enter the Wu-Tang were a practical solution that became a legend. When photographer Daniel Hastings set up the shoot, two members of the nine-man group could not be there. U-God was in jail for a parole violation, and Method Man had been arrested earlier that same day for marijuana possession. So the six who did turn up, RZA, GZA, Ol'' Dirty Bastard, Inspectah Deck, Ghostface Killah and Raekwon, pulled stocking masks over their faces, and nobody could tell who was missing.</p><p>The setting made it look like a horror film. Hastings shot them inside the Angel Orensanz Center in Manhattan, at the time an abandoned and ruined synagogue, standing in front of a huge foamcore version of the group''s W logo. He lit the scene with tungsten lights, strobes and candles, so the hooded figures seem to emerge from smoke and darkness. Hastings also photographed the group under the Queensboro Bridge, and those pictures appear inside the packaging.</p><p>The result matched a record that sounded like nothing else in 1993: grimy beats, kung fu film samples and a crew of rappers who seemed to come from another world. Released on 9 November 1993, the album launched one of hip-hop''s most influential groups, and the masked portrait and the yellow W logo became symbols of Staten Island rap that are still printed on T-shirts and tattoos today.</p>','#4B3736','#B69134','https://static.wixstatic.com/media/b519fa_20a9c17255f64d9098aff524d95ef742~mv2.jpg',3000,3000,'6acGx168JViE5LLFR1rGRE','https://open.spotify.com/album/6acGx168JViE5LLFR1rGRE','https://music.apple.com/us/album/enter-the-wu-tang-36-chambers/1746566237','https://www.youtube.com/results?search_query=Wu-Tang+Clan+Enter+the+Wu-Tang+(36+Chambers)+full+album',false),
('ca31170f-4ba5-40f4-be49-74693bc67f6c','midnight-marauders','Midnight Marauders','A Tribe Called Quest',1993,'1990s','Jive Records','United States','2a9002ef-8700-4b4b-bc97-eae22cc36802',array['Jazz rap','Alternative hip-hop']::text[],'Art direction by Nick Gamma; concept by Jean Kelly','<p>At the centre of the Midnight Marauders cover is a woman painted in red, black and green, wearing headphones, the same Afrocentric figure that appeared on The Low End Theory two years earlier. Around her, row after row of faces fill the frame, most of them wearing headphones too.</p><p>Those faces are a roll call of hip-hop in 1993. According to Ego Trip''s Book of Rap Lists, 71 artists and radio DJs appear across the album''s covers, among them the Beastie Boys and Dr. Dre, and the group used the artwork to salute the peers it respected. Critics have read the painted woman as a nod to rap''s African roots and to the colourful mix of sounds on the record.</p><p>Art director Nick Gamma later described an earlier idea that Q-Tip came up with and then dropped: a woman in bed in a loft window, wearing headphones, with the Manhattan skyline and a full moon behind her. The final design, credited to Gamma with Jive Records'' Jean Kelly as the concept''s driving force, was released on 9 November 1993.</p>','#756D59','#3B1F18','https://static.wixstatic.com/media/b519fa_e0e49e28d7a14cca9c2c4ca15044c32a~mv2.jpg',3000,3000,'4v5x3Oo3UjQ9YmF3hRAip5','https://open.spotify.com/album/4v5x3Oo3UjQ9YmF3hRAip5','https://music.apple.com/us/album/midnight-marauders/265670545','https://www.youtube.com/results?search_query=A+Tribe+Called+Quest+Midnight+Marauders+full+album',false),
('99997d0e-e13f-4518-baff-60c8d1976fa2','reachin-a-new-refutation-of-time-and-space','Reachin'' (A New Refutation of Time and Space)','Digable Planets',1993,'1990s','Pendulum / Elektra','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['Jazz rap','Alternative hip-hop']::text[],null,'<p>The three members of Digable Planets, Butterfly, Ladybug Mecca and Doodlebug, stand inside a glowing purple circle on the cover of their debut, with a tangle of roots hanging beneath them against a deep blue background, as if they were growing from the earth.</p><p>Their debut leaned hard into jazz, sampling records by Art Blakey and other jazz greats, and wrapped bohemian, Afrocentric rhymes in a relaxed, cool style. Its single "Rebirth of Slick (Cool Like Dat)" became a crossover hit and won the Grammy for Best Rap Performance by a Duo or Group.</p><p>Reachin'' was released on 9 February 1993. The roots and the cosmic circle match a group whose name joined insects and outer space and whose music joined rap to the jazz tradition, and the album remains one of the defining records of jazz rap.</p>','#32509F','#975893','https://static.wixstatic.com/media/b519fa_968010d8417348f38a7d5895f7cf9241~mv2.jpg',1400,1400,'5snUbps5KleLIP0cVI72lP','https://open.spotify.com/album/5snUbps5KleLIP0cVI72lP','https://music.apple.com/us/album/reachin-a-new-refutation-of-time-and-space/725211790','https://www.youtube.com/results?search_query=Digable+Planets+Reachin%27+%28A+New+Refutation+of+Time+and+Space%29+full+album',false),
('45618351-243c-42df-9534-f46b9a9c0058','return-of-the-boom-bap','Return of the Boom Bap','KRS-One',1993,'1990s','Jive','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['East Coast hip-hop','Boom bap']::text[],'Photography by Daniel Hastings','<p>After seven years leading Boogie Down Productions, KRS-One made his first solo album, and its title gave a name to a whole style of hard New York drums. The cover shows the Teacha in a basement studio, wearing headphones, washed in warm orange and cold blue light.</p><p>It was the first album cover shot by the photographer Daniel Hastings, who went on to shoot many of the defining covers of 1990s New York rap. Hastings explained to Muse by Clio that the concept used the headphones as an inverted microphone. He shot on Fuji 64T reversal film with a daylight strobe and cross-processed it to get the strange colours, and a Heineken bottle sits in the background.</p><p>Return of the Boom Bap was released on 28 September 1993 with production from DJ Premier, Kid Capri and Showbiz. The phrase in its title became the standard name for the sound it celebrated.</p>','#232024','#B96F30','https://static.wixstatic.com/media/b519fa_6d0d7a66c4184bf685a472370c5e75d5~mv2.jpg',1405,1405,'64ub4SfdC8wvPjdUXw8QY9','https://open.spotify.com/album/64ub4SfdC8wvPjdUXw8QY9','https://music.apple.com/us/album/return-of-the-boom-bap/267251596','https://www.youtube.com/results?search_query=KRS-One+Return+of+the+Boom+Bap+full+album',false),
('6e137c2c-ed2b-491b-b5f4-d92fe4c39032','check-your-head','Check Your Head','Beastie Boys',1992,'1990s','Grand Royal / Capitol','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['Alternative hip-hop','Rap rock']::text[],'Photography by Glen E. Friedman','<p>After the dense sample collage of Paul''s Boutique, the Beastie Boys went back to the instruments they had played as teenage punks, with Mike D on drums, MCA on bass and Ad-Rock on guitar. Check Your Head was the sound of the trio becoming a band again.</p><p>The cover was shot by their longtime friend Glen E. Friedman, the photographer famous for his skateboarding and punk pictures. Seeing the group return to their own instruments, he photographed them with their instrument cases, and one of those black-and-white street shots became the cover, under the title in big hand-drawn letters.</p><p>Check Your Head was released on 21 April 1992 on Capitol and the band''s own Grand Royal imprint. The casual, gritty photo marked the start of the Beastie Boys'' second life, and the album''s mix of rap, punk and funk shaped much of the alternative music of the decade.</p>','#252329','#D9D9DC','https://static.wixstatic.com/media/b519fa_783663c12ba444d38c681092cf69e4ee~mv2.jpg',1401,1401,'0cXrT5A2aHEQEG0f1ZBS05','https://open.spotify.com/album/0cXrT5A2aHEQEG0f1ZBS05','https://music.apple.com/us/album/check-your-head/724690226','https://www.youtube.com/results?search_query=Beastie+Boys+Check+Your+Head+full+album',false)
insert into public.covers (id,slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,color,accent_color,image_url,image_width,image_height,spotify_album_id,spotify_url,apple_music_url,youtube_url,featured) values
('6d92bfd2-ed62-4b96-9233-8b38a5290e59','mecca-and-the-soul-brother','Mecca and the Soul Brother','Pete Rock & CL Smooth',1992,'1990s','Elektra','United States','27d91a37-0b27-477a-b65d-82e9697175da',array['Jazz rap','East Coast hip-hop']::text[],null,'<p>The cover of Pete Rock & CL Smooth''s debut is a moody black-and-white night shot of the duo by a car, with their round gold logo glowing at the top like a seal or a medallion.</p><p>The duo from Mount Vernon, New York made the album that defined the jazz and soul sample sound of early-1990s New York. Pete Rock''s warm horn loops and filtered basslines, paired with CL Smooth''s calm, thoughtful rhymes, peaked on "They Reminisce Over You (T.R.O.Y.)," a tribute to their friend Trouble T Roy of Heavy D & the Boyz, who died in 1990.</p><p>Mecca and the Soul Brother was released on 9 June 1992. The understated, nocturnal cover fits a record often described as nostalgic and soulful, and "T.R.O.Y." remains one of the most beloved songs in hip-hop.</p>','#111313','#887A5C','https://static.wixstatic.com/media/b519fa_4714c600e8a54c7ab0165df91b882da4~mv2.jpg',1425,1425,'2AgTKAULjbHpqqtyI53hdp','https://open.spotify.com/album/2AgTKAULjbHpqqtyI53hdp','https://music.apple.com/us/album/mecca-and-the-soul-brother/217508870','https://www.youtube.com/results?search_query=Pete+Rock+%26+CL+Smooth+Mecca+and+the+Soul+Brother+full+album',false),
('cb541fd4-feb5-47b8-8d09-b02b4104fdc5','the-chronic','The Chronic','Dr. Dre',1992,'1990s','Death Row Records','United States','c0217d82-6644-4ea9-99d1-67b7e9dbe7a7',array['G-funk','West Coast hip-hop']::text[],'Art direction and graphic design by Kimberly Holt; photography by Daniel Jordan','<p>The Chronic borrows its look from a packet of rolling papers. The cover is an homage to Zig-Zag, with Dr. Dre''s portrait set inside the ornate border where the brand''s bearded mascot usually sits, a fitting design for an album named after slang for high-grade cannabis.</p><p>The idea had a recent precedent: the cover was heavily inspired by the artwork for Eazy-E''s "We Want Eazy" single, which had also been designed as a tribute to Zig-Zag. Art direction and graphic design were by Kimberly Holt, and the photograph of Dre was taken by Daniel Jordan.</p><p>The Zig-Zag mascot comes with its own legend, retold by NME: a soldier at the siege of Sevastopol in the 1850s had his clay pipe shot out and rolled his tobacco in paper torn from a gunpowder bag. Released on 15 December 1992 by Death Row, the album popularised G-funk and made its papery sleeve one of the most recognised images of West Coast rap.</p>','#FCFCFC','#D0D0CA','https://static.wixstatic.com/media/b519fa_f5ee880f139d4cb6851fb4091ecebe21~mv2.jpg',3000,3000,'2V5rhszUpCudPcb01zevOt','https://open.spotify.com/album/2V5rhszUpCudPcb01zevOt','https://music.apple.com/us/album/the-chronic/1668460963','https://www.youtube.com/results?search_query=Dr.+Dre+The+Chronic+full+album',false),
('719b2f0a-0e55-4093-815e-a1694840acc7','vier-gewinnt','Vier gewinnt','Die Fantastischen Vier',1992,'1990s','Columbia','Germany','818f66a4-a51e-4b8b-b515-691d9aba254d',array['German hip-hop','Pop rap']::text[],null,'<p>The cover of Die Fantastischen Vier''s second album frames one member in a round window on a bright blue background, wearing a yellow jacket and oversized sunglasses, with the title in small type at the top. The round frame echoes the title, the German name for the game Connect Four.</p><p>The Stuttgart group rapped in German at a time when most German rap was in English, and their single "Die da!?!" became a top-ten hit in 1992, one of the first German-language rap songs to break into the mainstream.</p><p>The playful, game-like cover matched a group that brought humour and pop hooks to rap. Die Fantastischen Vier proved that rap in German could sell, and the German rap scenes that followed, up to Aggro Berlin, grew in the space they opened.</p>','#406891','#BE5E3B','https://static.wixstatic.com/media/b519fa_1a0bf4652e4f4725b1da70b74f0a91ae~mv2.jpg',600,600,'54tcacygP8sbOOtQZrVVC6','https://open.spotify.com/album/54tcacygP8sbOOtQZrVVC6','https://music.apple.com/us/album/vier-gewinnt/267706467','https://www.youtube.com/results?search_query=Die+Fantastischen+Vier+Vier+gewinnt+full+album',false),
('6edeaa0c-45dc-4144-8eb8-9662ebe03526','cypress-hill','Cypress Hill','Cypress Hill',1991,'1990s','Ruffhouse / Columbia','United States','c0217d82-6644-4ea9-99d1-67b7e9dbe7a7',array['West Coast hip-hop','Latin hip-hop']::text[],'Art direction by Stacy Drummond; logo design by Dante Ariola; photography by Michael Miller','<p>Cypress Hill''s debut is split in two. On the left runs a narrow panel carrying the group''s logo in red, and on the right is a hazy photograph of B-Real, Sen Dog and DJ Muggs standing around a fire burning in a trash can, according to the description held by the Museum of Pop Culture in Seattle.</p><p>Discogs credits the art direction to Stacy Drummond, the logo to Dante Ariola and the photography to Michael Miller. The logo became the group''s lasting trademark and has been reworked on their records for decades.</p><p>Cypress Hill was released on 13 August 1991 on Ruffhouse and Columbia. It introduced B-Real''s nasal flow and Muggs''s dusty, menacing beats, and in 2016 the group marked its 25th anniversary with a box set packaged inside a resin skull.</p>','#A7847C','#7B5554','https://static.wixstatic.com/media/b519fa_8f0b3c9991a341a782327482eb355bae~mv2.jpg',600,600,'4tQSV1ZGpwlo3dBiTRuKvM','https://open.spotify.com/album/4tQSV1ZGpwlo3dBiTRuKvM','https://music.apple.com/us/album/cypress-hill/192754650','https://www.youtube.com/results?search_query=Cypress+Hill+Cypress+Hill+full+album',false),
('1bfa75f0-8af4-49d3-9bda-a94ec1b436d0','death-certificate','Death Certificate','Ice Cube',1991,'1990s','Priority Records','United States','27d91a37-0b27-477a-b65d-82e9697175da',array['West Coast hip-hop','Political hip-hop']::text[],'Photography by Mario Castellanos; art direction by Kevin Hosmann','<p>Ice Cube''s second solo album is split into two halves, the Death Side and the Life Side, one describing the state of Black America and the other a way out of it. Mario Castellanos photographed the cover in a morgue, with Kevin Hosmann directing the art for Priority Records.</p><p>Cube stands in the shadows, scowling over a corpse laid out on a gurney beneath an American flag. Only the bare feet are visible, and a tag hanging from one toe reads "Uncle Sam." The message was blunt: the album would perform an autopsy on the country that had failed the neighbourhoods Cube was rapping about.</p><p>Released on 29 October 1991, months after the Rodney King beating and only months before the Los Angeles riots, the record went platinum and drew fierce criticism for several of its lyrics. The cover''s dead Uncle Sam has since become one of the most quoted political images in West Coast rap.</p>','#030302','#AC957F','https://static.wixstatic.com/media/b519fa_8f0d527e38ca41caaa586a5f30a8249f~mv2.jpg',3000,3000,'0VoorTgcwMRROTmmZlxPSG','https://open.spotify.com/album/0VoorTgcwMRROTmmZlxPSG','https://music.apple.com/us/album/death-certificate/1590072758','https://www.youtube.com/results?search_query=Ice+Cube+Death+Certificate+full+album',false),
('5eefb465-fbcd-416a-902f-4185f3c146f8','qui-seme-le-vent-recolte-le-tempo','Qui sème le vent récolte le tempo','MC Solaar',1991,'1990s','Polydor','France','818f66a4-a51e-4b8b-b515-691d9aba254d',array['French hip-hop','Jazz rap']::text[],null,'<p>MC Solaar reclines beside a record player on the cover of his debut album, his head tilted back as if lost in the music, in a cool black-and-white and teal photograph, with his name in bold capitals at the bottom.</p><p>Born in Dakar and raised in the suburbs of Paris, Solaar brought jazz samples and playful, literary wordplay to French rap. Released in October 1991, the album''s title turns the proverb "he who sows the wind reaps the storm" into a pun on tempo, and singles like "Bouge de là" and "Caroline" made him a national star.</p><p>The relaxed pose beside the turntable suits an artist who made rap sound gentle and poetic. The album proved French rap could reach the mainstream and made Solaar one of the first French rappers to find success abroad.</p>','#060505','#BFBFBF','https://static.wixstatic.com/media/b519fa_99477b56a92848d7bbfa01f1aaa72e17~mv2.jpg',3000,3000,'5hM61fBUA5OIMJUUuMrzyH','https://open.spotify.com/album/5hM61fBUA5OIMJUUuMrzyH','https://music.apple.com/fr/album/qui-s%C3%A8me-le-vent-r%C3%A9colte-le-tempo/1572971729','https://www.youtube.com/results?search_query=MC+Solaar+Qui+s%C3%A8me+le+vent+r%C3%A9colte+le+tempo+full+album',false),
('2f9a0495-ecc6-4ec6-9fc4-1f8d6ce88873','the-low-end-theory','The Low End Theory','A Tribe Called Quest',1991,'1990s','Jive Records','United States','27d91a37-0b27-477a-b65d-82e9697175da',array['Jazz rap','East Coast hip-hop','Alternative hip-hop']::text[],'Photography by Joe Grant; concept by Jean Kelly and Ann Carli; lettering by Nick Gamma (Zombart)','<p>The Low End Theory has one of the strangest and most beautiful covers in hip-hop: the outline of a kneeling woman, drawn only in glowing red and green lines against pure black. The idea came from Q-Tip, who loved the covers of the Ohio Players and their glamorous models. "He knew he wanted this painted lady," as one account of the cover put it.</p><p>The effect was created for real. Jean Kelly, Jive''s vice president of artist development, and Ann Carli developed the concept and hired the Brooklyn photographer Joe Grant. A nude model was painted with neon paint and photographed under black light, so that only the painted lines show up in the darkness. The red, black and green palette is the colour scheme of the Pan-African flag, which made the image feel Afrocentric as well as sensual, and the title rests along the figure''s lower body, a visual joke on the album''s obsession with bass.</p><p>It was the group''s third idea. A bedroom scene with a woman listening to the record at midnight was rejected by the label, and a shoot of fans in headphones at the Flatiron Building in the snow went nowhere. Designer Nick Gamma of Jive''s Zombart art department then hand-lettered the type. The album came out on 24 September 1991, and Complex later ranked its cover the greatest hip-hop album cover of all time.</p>','#040602','#7B3134','https://static.wixstatic.com/media/b519fa_85e605054a1b4332859f4e9d6e0b57e9~mv2.jpg',2815,2815,'1p12OAWwudgMqfMzjMvl2a','https://open.spotify.com/album/1p12OAWwudgMqfMzjMvl2a','https://music.apple.com/us/album/the-low-end-theory/278911460','https://www.youtube.com/results?search_query=A+Tribe+Called+Quest+The+Low+End+Theory+full+album',false),
('731192ac-3c11-45b6-9bb2-05ec3e121dfa','we-can-t-be-stopped','We Can''t Be Stopped','Geto Boys',1991,'1990s','Rap-A-Lot','United States','27d91a37-0b27-477a-b65d-82e9697175da',array['Southern hip-hop','Horrorcore']::text[],'Photograph by Cliff Blodget','<p>In 1991 Bushwick Bill of the Houston group Geto Boys was shot in the eye after a night of PCP and Everclear. While he was still in hospital, his bandmates Willie D and Scarface wheeled him down a corridor on a gurney, and Bill pulled off his own eye bandage for the camera. The picture became the cover of their next album.</p><p>The photograph was taken by Cliff Blodget, co-owner of the group''s label Rap-A-Lot Records. According to Andscape, when Blodget raised the question of a cover, Willie D answered that Bill was alive and they could shoot it right there. Bill, heavily sedated, said he did not care. He later called the decision "pretty wrong," and Scarface said he never wanted to put Bill out there like that, which shows in his uneasy face in the frame.</p><p>We Can''t Be Stopped came out in July 1991 and went platinum the following year. Shocking, raw and uncomfortable to look at, its cover remains one of the most notorious images in rap history, and a document of how far the Houston scene was willing to go.</p>','#6F5E4F','#AB9478','https://static.wixstatic.com/media/b519fa_fc2b76f7e8dd4227adec9c6e135b8dfa~mv2.jpg',1400,1400,'2MJEvcUvsLPjsvVgqn8xa4','https://open.spotify.com/album/2MJEvcUvsLPjsvVgqn8xa4','https://music.apple.com/us/album/we-cant-be-stopped/1813058345','https://www.youtube.com/results?search_query=Geto+Boys+We+Can%27t+Be+Stopped+full+album',false),
('d579956f-1835-4965-878e-f444d4ab2069','fear-of-a-black-planet','Fear of a Black Planet','Public Enemy',1990,'1990s','Def Jam Recordings','United States','cac97ec2-47e9-4562-b1b0-ebb5ae534086',array['Political hip-hop','East Coast hip-hop']::text[],'Cover art by B.E. Johnson; concept by Chuck D; art direction by The Drawing Board','<p>For Fear of a Black Planet, Chuck D wanted an image of two worlds: a "Black" planet and Earth, eclipsing one another. To paint it, Public Enemy enlisted B.E. Johnson, an illustrator who had worked for NASA, and the result looks like a frame from a space mission, one planet sliding across the face of the other.</p><p>Cey Adams, then creative director at Def Jam, remembered how unusual the choice was: "It was so interesting to me that a black hip-hop act did an illustration for their album cover."</p><p>The cosmic picture turns the album''s subject, racial fear, into an astronomical event that nothing can stop. Art direction was by The Drawing Board, and the record was released by Def Jam on 10 April 1990.</p>','#3B5270','#B3793B','https://static.wixstatic.com/media/b519fa_7a373eca72fe41bb9fdd97104cdf6340~mv2.jpg',3000,3000,'0aFNb4RDk2hmKKLa0bzXNz','https://open.spotify.com/album/0aFNb4RDk2hmKKLa0bzXNz','https://music.apple.com/us/album/fear-of-a-black-planet/1440837282','https://www.youtube.com/results?search_query=Public+Enemy+Fear+of+a+Black+Planet+full+album',false),
('54fdc581-cc40-4853-9f3d-ec5a9e7a1f15','mama-said-knock-you-out','Mama Said Knock You Out','LL Cool J',1990,'1990s','Def Jam','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['East Coast hip-hop','Hardcore hip-hop']::text[],null,'<p>LL Cool J appears shirtless on the cover of his fourth album, his chest and arms lit in warm, gritty tones, a heavy chain around his neck and his fists raised in front of him like a boxer waiting for the bell.</p><p>By 1990 critics had written LL off as a pop rapper past his peak. With Marley Marl producing, he answered with a hard comeback record, and its title track, inspired by his grandmother''s advice to knock his doubters out, opened with "Don''t call it a comeback, I been here for years." The song won a Grammy, and the album became one of the biggest of his career.</p><p>The boxing pose turned the title into a picture. The cover presented LL as a fighter returning to the ring, and the image of the bare-chested rapper with his fists up became one of the most recognisable in early-1990s rap.</p>','#151D1D','#B2A9A7','https://static.wixstatic.com/media/b519fa_e33197d7af234f91ab25abf42e9fdc4f~mv2.jpg',1445,1431,'7p7kcsrdoJ8DKQIMouujcb','https://open.spotify.com/album/7p7kcsrdoJ8DKQIMouujcb','https://music.apple.com/us/album/mama-said-knock-you-out/1443811286','https://www.youtube.com/results?search_query=LL+Cool+J+Mama+Said+Knock+You+Out+full+album',false),
('dc132969-985d-48e9-98d9-fcfc0dd31b80','people-s-instinctive-travels-and-the-paths-of-rhythm','People''s Instinctive Travels and the Paths of Rhythm','A Tribe Called Quest',1990,'1990s','Jive','United States','cac97ec2-47e9-4562-b1b0-ebb5ae534086',array['Jazz rap','Alternative hip-hop']::text[],'Cover art by Paije Hunyady and Bryant Peters; photography by Ari Marcopoulos and Justin Herz','<p>A Tribe Called Quest''s debut announced a gentler, more playful kind of rap, and the cover sets the mood. Painted, colour-blocked figures and shapes in bright blues, reds, greens and yellows fill the frame like a patchwork city, with the long title hand-lettered across the middle.</p><p>The cover art is credited to Paije Hunyady and Bryant Peters, with photography by Ari Marcopoulos and Justin Herz. The People''s Graphic Design Archive describes the figures as moving through a dreamlike, cosmic landscape, an image of the album''s bohemian and inclusive message. A 25th anniversary edition of the album followed in 2015.</p><p>People''s Instinctive Travels and the Paths of Rhythm was released on 17 April 1990 on Jive. With songs like "Can I Kick It?" and "Bonita Applebum," it set out the jazz-loving sound of the Native Tongues collective and led straight to The Low End Theory.</p>','#556678','#B97751','https://static.wixstatic.com/media/b519fa_0b11ea7e197442e6b878ed8c15cb336c~mv2.jpg',640,640,'4Qt1ZvWZ3DoKDimDMesZd5','https://open.spotify.com/album/4Qt1ZvWZ3DoKDimDMesZd5','https://music.apple.com/us/album/peoples-instinctive-travels-and-the-paths-of/1806751228','https://www.youtube.com/results?search_query=A+Tribe+Called+Quest+People%27s+Instinctive+Travels+and+the+Paths+of+Rhythm+full+album',false),
('ea60c187-60f6-44a5-9613-46ec71065550','3-feet-high-and-rising','3 Feet High and Rising','De La Soul',1989,'1980s','Tommy Boy Records','United States','2a9002ef-8700-4b4b-bc97-eae22cc36802',array['Alternative hip-hop','Jazz rap','Psychedelic hip-hop']::text[],'Cover design by Toby Mott of the Grey Organisation','<p>In 1989 most rap covers were built on toughness: gold chains, scowls, cars and guns. De La Soul''s debut arrived covered in flowers. The cover was designed by Toby Mott of the Grey Organisation, a British art collective that had moved to New York after being prosecuted for an attack on the art galleries of Cork Street in London. Mott later described the design as a deliberate move away from the macho visual codes of hip-hop at the time.</p><p>He made it by hand. Mott laid the three members on the floor of his loft, face up, with their heads forming a triangle, and photographed them from above while hanging off a stepladder. The idea was that the cover would have no right way up. He then drew bright flowers on sheets of acetate with Posca paint pens, laid them over the black-and-white photograph and copied the result with a rostrum camera. It was, he noted, the era before Apple Macs and digital scanning.</p><p>The daisies carried the group''s message. They called their outlook the D.A.I.S.Y. Age, short for "Da Inner Sound, Y''all," and Posdnuos said the flowers signalled the group''s sunnier, more playful spirit. Their own first idea had been an elevator halfway up with just their faces showing. Released on 6 February 1989, the album was later added to the Library of Congress National Recording Registry, and its fluorescent flowers still stand out among the hard images of late 1980s rap.</p>','#C0C51E','#6A6B51','https://static.wixstatic.com/media/b519fa_1b7beb8f8c8e417dae8d5e6182eb351f~mv2.jpg',3000,3000,'34LxHI9x14qXUOS8AWRrYD','https://open.spotify.com/album/34LxHI9x14qXUOS8AWRrYD','https://music.apple.com/us/album/3-feet-high-and-rising/1657705063','https://www.youtube.com/results?search_query=De+La+Soul+3+Feet+High+and+Rising+full+album',false),
('fe432930-e67e-46bf-8056-99f0188cc1ef','paul-s-boutique','Paul''s Boutique','Beastie Boys',1989,'1980s','Capitol Records','United States','27d91a37-0b27-477a-b65d-82e9697175da',array['Alternative hip-hop','Sampledelia']::text[],'Photograph by Jeremy Shatan (credited as Nathanial Hörnblowér)','<p>Paul''s Boutique is named after a shop that never existed. For the cover, the Beastie Boys hung a "Paul''s Boutique" sign over a real clothing store, Lee''s Sportswear, on the corner of Rivington and Ludlow Streets on Manhattan''s Lower East Side, then photographed the block as if the boutique had always been there.</p><p>The panoramic picture, which wraps across the front and the gatefold, was taken from 99 Rivington Street looking down Ludlow Street. The sleeve credits it to Nathanial Hörnblowér, an alias of Adam Yauch, but the photograph was actually taken by Jeremy Shatan, the group''s original bassist from the days when they were called the Young Aborigines.</p><p>Like the album''s dense collage of samples, the image rewards long looking at its ordinary street detail. The corner became a pilgrimage site for fans, and after years of debate the intersection was officially named Beastie Boys Square on 9 September 2023. The album was released on 25 July 1989.</p>','#191C21','#775E56','https://static.wixstatic.com/media/b519fa_332cbb74721c42ae8149107eecec7c8e~mv2.jpg',3000,3000,'4DfmPm17Nz6a60BlEpGGKU','https://open.spotify.com/album/4DfmPm17Nz6a60BlEpGGKU','https://music.apple.com/us/album/pauls-boutique/723654366','https://www.youtube.com/results?search_query=Beastie+Boys+Paul''s+Boutique+full+album',false),
('cbdd9ed1-71c6-4dbe-b333-84567c654e98','straight-outta-compton','Straight Outta Compton','N.W.A',1989,'1980s','Ruthless Records','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['Gangsta rap','West Coast hip-hop']::text[],'Photograph by Ithaka Darin Pappas (album credits list Eric Poppleton); art direction by Helane Freeman','<p>The Straight Outta Compton cover was shot from the ground up. The members of N.W.A crowd around the lens and stare down at it, and one of them points a gun straight at the viewer, so the person holding the record is placed in the position of a victim.</p><p>Photographer Ithaka Darin Pappas took the picture on 11 November 1988 in his studio apartment in Los Angeles'' Miracle Mile district, and he calls it "The Miracle Mile Shot." The album credits name Eric Poppleton for photography, and Helane Freeman handled art direction. Arabian Prince appears on the cover even though he had left the group by the time the record came out.</p><p>The photograph took on a life of its own. It ran on the cover of The Source in May 1989, was reused for the 2015 documentary Kings of Compton, hung in a 2017 exhibition at the Musée d''art contemporain de Marseille, and served as the backdrop when N.W.A was inducted into the Rock and Roll Hall of Fame in 2016.</p>','#2D2123','#BED4DE','https://static.wixstatic.com/media/b519fa_59642bb05da04159b679c60d891204e0~mv2.jpg',1404,1404,'0Y7qkJVZ06tS2GUCDptzyW','https://open.spotify.com/album/0Y7qkJVZ06tS2GUCDptzyW','https://music.apple.com/us/album/straight-outta-compton/1440816032','https://www.youtube.com/results?search_query=N.W.A+Straight+Outta+Compton+full+album',false),
('e6aab9f1-861f-42ab-8d11-aeebc24b9fb9','critical-beatdown','Critical Beatdown','Ultramagnetic MCs',1988,'1980s','Next Plateau','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['Golden age hip-hop','East Coast hip-hop']::text[],null,'<p>The four members of Ultramagnetic MCs stand in front of a brick building on the cover of their debut, dressed in bright patterned outfits and sportswear, with the group''s name in bold green capitals above them and the title in yellow below.</p><p>Critical Beatdown, released on 4 October 1988, was a sampling landmark. Ced-Gee''s chopped, layered drums and James Brown breaks sounded years ahead of their time, and Kool Keith''s abstract, science-fiction rhymes on songs like "Ego Trippin''" introduced one of rap''s strangest and most influential voices.</p><p>The cover looks like a typical late-1980s group shot, which makes the record inside even more surprising. Kool Keith went on to create Dr. Octagon and dozens of other alter egos, and the album''s dense production is often described as years ahead of its time.</p>','#BF9151','#7C6A4D','https://static.wixstatic.com/media/b519fa_ec2a4c2777ad423bb96ecce95dc63b83~mv2.jpg',1425,1425,'7JKJGhEcQPmEVhULUZZKKE','https://open.spotify.com/album/7JKJGhEcQPmEVhULUZZKKE','https://music.apple.com/us/album/critical-beatdown/307597231','https://www.youtube.com/results?search_query=Ultramagnetic+MCs+Critical+Beatdown+full+album',false),
('1051f209-64ba-4850-8f59-d02177b7a377','it-takes-a-nation-of-millions-to-hold-us-back','It Takes a Nation of Millions to Hold Us Back','Public Enemy',1988,'1980s','Def Jam Recordings','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['Political hip-hop','East Coast hip-hop']::text[],'Photography by Glen E. Friedman','<p>The cover of It Takes a Nation of Millions to Hold Us Back puts Chuck D and Flavor Flav behind bars. Photographed by Glen E. Friedman, who shot many of Public Enemy''s covers, the pair stand inside a jail cell and look straight out at the viewer, with the group''s crosshair logo above them.</p><p>The image fits an album concerned with confinement and resistance, including "Black Steel in the Hour of Chaos," a song that tells the story of a prison escape. Writing for The Root, one critic called it "a powerful, powerful image" and read the cell as a statement of defiance, a space that cannot hold them down.</p><p>Busta Rhymes, recalling the record''s impact, put it simply: "The artwork was amazing." Released by Def Jam on 28 June 1988, the album and its stark cover helped set the visual tone for political rap at the end of the decade.</p>','#144337','#AD834E','https://static.wixstatic.com/media/b519fa_5d18277f3f374910bdb2525d7b82e094~mv2.jpg',3000,3000,'1Rj1daFzMlYzLv7lJl14hz','https://open.spotify.com/album/1Rj1daFzMlYzLv7lJl14hz','https://music.apple.com/us/album/it-takes-a-nation-of-millions-to-hold-us-back/1440837788','https://www.youtube.com/results?search_query=Public+Enemy+It+Takes+a+Nation+of+Millions+to+Hold+Us+Back+full+album',false),
('c140066e-7369-4ec0-bf68-8eedca4c3c6b','long-live-the-kane','Long Live the Kane','Big Daddy Kane',1988,'1980s','Cold Chillin'' / Warner Bros.','United States','27d91a37-0b27-477a-b65d-82e9697175da',array['Golden age hip-hop','East Coast hip-hop']::text[],null,'<p>Big Daddy Kane sits like a king on the cover of his debut, in a rich purple setting, surrounded by women in white dresses who feed him grapes. The image is part Roman emperor, part soul-era lover man, with Kane''s name in gold letters at the top.</p><p>Kane, from Bedford-Stuyvesant, Brooklyn, was the smoothest and fastest rapper of the Juice Crew, and Long Live the Kane, produced by Marley Marl and released on 21 June 1988, showed it off on songs like "Ain''t No Half-Steppin''" and "Raw." His mix of speed, wordplay and charm set a standard for golden age lyricists.</p><p>The cover sold the persona as much as the music. Kane presented himself as a romantic, regal figure at a time when rap covers were mostly street photographs, and the grapes-and-servants image has been parodied and paid homage to ever since as a symbol of rap''s swaggering golden age.</p>','#48343B','#BBA27D','https://static.wixstatic.com/media/b519fa_cf5af778684540f78e6a2631aacb15c0~mv2.jpg',1425,1425,'5STvD2F7IQ51f4Cd2y5r3z','https://open.spotify.com/album/5STvD2F7IQ51f4Cd2y5r3z','https://music.apple.com/us/album/long-live-the-kane/442164816','https://www.youtube.com/results?search_query=Big+Daddy+Kane+Long+Live+the+Kane+full+album',false),
('30576fbc-ce98-49c7-929b-19552e4e5aad','power','Power','Ice-T',1988,'1980s','Sire Records','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['West Coast hip-hop','Gangsta rap']::text[],'Photography by Glen E. Friedman; design by Kav DeLuxe','<p>Glen E. Friedman, the photographer behind classic skateboarding and punk images, shot the cover of Ice-T''s second album against a plain white backdrop. Ice-T stands in the middle with DJ Evil E, and beside them is Darlene Ortiz, his girlfriend, in a white cut-out swimsuit and red pumps, holding a shotgun. Kav DeLuxe set the title in huge gold block letters across the bottom.</p><p>The styling was Ice-T''s idea. He chose the swimsuit, the shoes and the earrings, and Ortiz went out and bought five swimsuits for the shoot. She later said she felt a woman holding a gun made "a powerful statement," a woman standing armed and equal beside the men.</p><p>Critics read it differently. Reviewers at the Chicago Sun-Times and the Sydney Morning Herald attacked the sleeve as violence-glorifying and demeaning to women, and the debate made the image famous. By 1989 the Los Angeles Daily News noted that Ortiz had become as much a part of Ice-T''s public image as gangs, guns and boom boxes. Sire released the album on 13 September 1988.</p>','#FBFBF8','#B36346','https://static.wixstatic.com/media/b519fa_fb2a9ea10b3a4427b144586ad6b7e706~mv2.jpg',2400,2400,'2KaB2rHtdBvocspgjm1bnN','https://open.spotify.com/album/2KaB2rHtdBvocspgjm1bnN','https://music.apple.com/us/album/power/268496485','https://www.youtube.com/results?search_query=Ice-T+Power+full+album',false),
('bffaa905-59b0-4828-83d1-cd0615954f5e','strictly-business','Strictly Business','EPMD',1988,'1980s','Fresh / Sleeping Bag','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['Golden age hip-hop','East Coast hip-hop']::text[],null,'<p>Erick Sermon and Parrish Smith of EPMD appear in a dim, moody photograph on the cover of their debut, with the title punched out in big yellow and blue letters inside a tilted box, like the stamp on a business deal.</p><p>The duo from Brentwood, Long Island took their name from Erick and Parrish Making Dollars, and Strictly Business, released on 7 June 1988, matched their laid-back, mumbled flows with funk and rock samples, from Zapp on "You Gots to Chill" to Eric Clapton''s "I Shot the Sheriff" on the title track. Its loose, heavy grooves became a template for East Coast production.</p><p>The cover''s corporate joke fits a group that treated rap as a trade. The block lettering announced EPMD''s long-running "business" theme, carried through every album title that followed, from Unfinished Business to Business Never Personal.</p>','#181C1C','#188EB8','https://static.wixstatic.com/media/b519fa_12abac913bc54a508719c1ff822ef263~mv2.jpg',1500,1500,'6hXUK907sBWQaH6x71ycwi','https://open.spotify.com/album/6hXUK907sBWQaH6x71ycwi','https://music.apple.com/us/album/strictly-business/721248274','https://www.youtube.com/results?search_query=EPMD+Strictly+Business+full+album',false),
('4e068c41-6276-4c17-9f5d-d062b7566cfb','the-great-adventures-of-slick-rick','The Great Adventures of Slick Rick','Slick Rick',1988,'1980s','Def Jam / Columbia','United States','2a9002ef-8700-4b4b-bc97-eae22cc36802',array['East Coast hip-hop','Golden age hip-hop']::text[],'Photography by Glen E. Friedman','<p>Slick Rick, the London-born storyteller raised in the Bronx, made his solo debut with a cover as flamboyant as his rhymes. Dressed head to toe in red, he strikes a pose in front of a glowing night view of the Manhattan skyline, with his name blazing across the top in bold yellow letters.</p><p>The photography is credited to Glen E. Friedman, the photographer known for his punk and skateboarding pictures and for early Def Jam images. The cut-out figure set against the bright city turns Rick into a cartoon hero of his own stories, a fitting picture for a record built around narratives such as "Children''s Story."</p><p>The Great Adventures of Slick Rick was released on 1 November 1988 on Def Jam. It is regarded as one of the great albums of rap''s golden age, and "Children''s Story" remains one of the best-known storytelling songs in hip-hop.</p>','#217EB9','#D8CDA9','https://static.wixstatic.com/media/b519fa_051803c152384b3a9e1c638ba4fd864f~mv2.jpg',3000,3000,'71mmTJdWvpkzQNmVfFbRdN','https://open.spotify.com/album/71mmTJdWvpkzQNmVfFbRdN','https://music.apple.com/us/album/the-great-adventures-of-slick-rick/1440834648','https://www.youtube.com/results?search_query=Slick+Rick+The+Great+Adventures+of+Slick+Rick+full+album',false),
('e5558eac-bec9-4b65-ba58-45e4699025e3','paid-in-full','Paid in Full','Eric B. & Rakim',1987,'1980s','4th & B''way Records','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['Golden age hip-hop','East Coast hip-hop']::text[],'Art direction by Ruth Kaplan; photography by Ron Contarsy','<p>Paid in Full turns its title into a picture. Eric B. and Rakim stand side by side, weighed down with heavy gold chains, wearing custom Gucci-patterned outfits made by Dapper Dan, the Harlem tailor famous for his unlicensed takes on luxury fashion.</p><p>The photograph was taken by Ron Contarsy, with art direction by Ruth Kaplan, for 4th & B''way, the Island Records label that released the album on 7 July 1987.</p><p>The picture fixed a style that came to define late-1980s rap: tailored luxury, heavy gold and total composure. It suits Rakim''s calm, unhurried delivery, and the Dapper Dan outfits on the sleeve are still pointed to as an early meeting point of hip-hop and high fashion.</p>','#2E2A2A','#6BA984','https://static.wixstatic.com/media/b519fa_40fa6c73f49248669444177bafce9932~mv2.jpg',3000,3000,'5GSidytcItIkYvD0GVQ68m','https://open.spotify.com/album/5GSidytcItIkYvD0GVQ68m','https://music.apple.com/us/album/paid-in-full/1440841577','https://www.youtube.com/results?search_query=Eric+B.+and+Rakim+Paid+in+Full+full+album',false),
('7934a72a-5c6e-463a-b816-e32107fa00c7','licensed-to-ill','Licensed to Ill','Beastie Boys',1986,'1980s','Def Jam Recordings','United States','cac97ec2-47e9-4562-b1b0-ebb5ae534086',array['Rap rock','East Coast hip-hop']::text[],'Concept by Rick Rubin; art direction by Steve Byram; cover art by David Gambale (credited as World B. Omés)','<p>The idea for the Licensed to Ill cover came from the album''s producer, Rick Rubin, after he read Hammer of the Gods, the Led Zeppelin biography. The artwork shows an American Airlines Boeing 727 with the Beastie Boys logo on its tail, and it is meant to be read across the gatefold from front to back.</p><p>Read that way, the joke lands. The jet has flown nose-first into the side of a mountain, and its crumpled body looks like a stubbed-out joint. Small details reward a closer look: the tail carries the Def Jam logo and the registration number 3MTA3, which spells EATME in a mirror.</p><p>The cover art was created by David Gambale, credited under the pun World B. Omés, with art direction by Stephen Byram. Storm Thorgerson and Aubrey Powell later included it in their book 100 Best Album Covers, and Eminem modelled the cover of his 2018 album Kamikaze closely on it. Licensed to Ill was released on 15 November 1986. Steve Byram was the art director.</p>','#E2D3B9','#9E9788','https://static.wixstatic.com/media/b519fa_bafbb9aa229b45a2891bd7e8cd9aeebd~mv2.jpg',1474,1451,'11oR0ZuqB3ucZwb5TGbZxb','https://open.spotify.com/album/11oR0ZuqB3ucZwb5TGbZxb','https://music.apple.com/us/album/licensed-to-ill/1440912031','https://www.youtube.com/results?search_query=Beastie+Boys+Licensed+to+Ill+full+album',false),
('5f58ffac-8372-42f0-96a1-0c48b27bcdf7','raising-hell','Raising Hell','Run-DMC',1986,'1980s','Profile Records','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['East Coast hip-hop','Rap rock']::text[],'Art direction and design by Janet Perr; photography by Caroline Greyshock','<p>Janet Perr, who designed Raising Hell, has been candid about how simple the brief was. "I hate to admit it but there wasn''t a ''concept'' concept for that album," she said. Profile Records wanted the three members on the front, the group arrived in their own clothes, and Perr brought in photographer Caroline Greyshock, whose soft black-and-white pictures she admired for the way they caught motion.</p><p>Greyshock photographed Run, DMC and Jam Master Jay in her Lower Manhattan studio with a strobe and a large window behind them, tilting some frames to a Dutch angle for a contemporary feel. Perr then printed the black-and-white images in flat colour, a purple photograph with green type on the front, and ran the album title vertically against the horizontal group name. She described the period as her "Russian Constructivist phase."</p><p>The deliberate outlaw street look came straight from the way Jam Master Jay already dressed every day. The stacked RUN over DMC lettering, boxed between parallel lines, went on to become the group''s best-known logo. Raising Hell was released on 15 May 1986.</p>','#6F518B','#769C79','https://static.wixstatic.com/media/b519fa_3958d6be13fc4c669c7665ecbcb30ce7~mv2.jpg',893,900,'7AFsTiojVaB2I58oZ1tMRg','https://open.spotify.com/album/7AFsTiojVaB2I58oZ1tMRg','https://music.apple.com/us/album/raising-hell/254344779','https://www.youtube.com/results?search_query=Run-DMC+Raising+Hell+full+album',false),
('86a9ad88-943d-4449-9814-a2952a5957da','radio','Radio','LL Cool J',1985,'1980s','Def Jam Recordings','United States','27d91a37-0b27-477a-b65d-82e9697175da',array['East Coast hip-hop','New school hip-hop']::text[],'Cover design by Steve Byram','<p>The front of Radio shows a single machine and no people. Steve Byram designed the sleeve around a straight-on photograph of a JVC RC-M90 boombox, framed so tightly that its speakers, dials and cassette deck fill the square from edge to edge, with LL Cool J''s name printed across the top like a manufacturer''s badge.</p><p>The choice suited the record. The beats on Radio are famously spare, and the back cover sums up Rick Rubin''s production with the line "Reduced by Rick Rubin." A portable stereo was the instrument this music was built for, loud, mobile and owned by the listener, so the cover makes the album look as if it is already playing on a street corner.</p><p>Reviewer Ira Robbins singled out "the monster boombox on the cover," and the image became one of the defining pictures of mid-1980s rap. The boombox model on the sleeve, the JVC RC-M90, is now displayed at the Rock and Roll Hall of Fame in Cleveland, Ohio. The album was released on 18 November 1985 by Def Jam and Columbia.</p>','#888A8C','#2D3A3C','https://static.wixstatic.com/media/b519fa_1b0b842514b2441db4b95d1d2f2deaab~mv2.jpg',1500,1500,'3BKvVQ3g673SWAgY4ef9z9','https://open.spotify.com/album/3BKvVQ3g673SWAgY4ef9z9','https://music.apple.com/us/album/radio/1443530975','https://www.youtube.com/results?search_query=LL+Cool+J+Radio+full+album',false),
('43d47870-d6f9-4bfc-9eb5-15cac5d3ea13','run-d-m-c','Run-D.M.C.','Run-DMC',1984,'1980s','Profile','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['Hardcore hip-hop','Rap rock']::text[],null,'<p>The cover of Run-DMC''s debut is a stark black-and-white photograph of Joseph "Run" Simmons and Darryl "D.M.C." McDaniels in hats, one of them in thick-rimmed glasses, staring straight out at the viewer under the group''s name in bold red.</p><p>The Hollis, Queens trio, with Jam Master Jay on the turntables, stripped rap down to booming drum machines, scratches and shouted rhymes, and added rock guitar on "Rock Box." Run-D.M.C. was released on 27 March 1984 and became the first rap album certified gold.</p><p>The photo introduced a new image for rap. In place of the costumes of the disco era, the group wore what young men in Queens wore every day, and that plain, tough street style, soon completed by Adidas, fedoras and gold chains, became the uniform of hip-hop for the rest of the decade.</p>','#25201C','#A98D7D','https://static.wixstatic.com/media/b519fa_17733afc1df4401cb6a3c73f931bdedd~mv2.jpg',1416,1416,'05n0d2kfwGPhKpTonLHRpY','https://open.spotify.com/album/05n0d2kfwGPhKpTonLHRpY','https://music.apple.com/us/album/run-d-m-c/256097651','https://www.youtube.com/results?search_query=Run-DMC+Run-D.M.C.+full+album',false),
('e9a9cef8-f239-4fe5-b951-6c45d888ba57','the-message','The Message','Grandmaster Flash and the Furious Five',1982,'1980s','Sugar Hill','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['Old-school hip-hop','Political hip-hop']::text[],null,'<p>Grandmaster Flash and the Furious Five pose together on a city street on the cover of their debut album, six young men in bright streetwear, striking confident poses beneath the group''s name and the album title.</p><p>The title track changed what rap could say. Over a slow, heavy groove, Melle Mel and Duke Bootee described broken glass, junkies, debt and a city closing in, ending with the famous warning, "Don''t push me ''cause I''m close to the edge." In 2002 "The Message" became the first hip-hop recording added to the Library of Congress''s National Recording Registry.</p><p>The cover shows the group as party stars of the Bronx scene, flashy and proud, while the record inside turned toward the streets they came from. That gap between the sharp outfits and the grim lyrics is the moment rap grew up and learned it could report on the world as well as move a room.</p>','#918590','#634553','https://static.wixstatic.com/media/b519fa_8da80bd57cc54e57bb79726281c9553d~mv2.jpg',1500,1500,'4dEczweFPXeLMMVD1zIdi7','https://open.spotify.com/album/4dEczweFPXeLMMVD1zIdi7','https://music.apple.com/us/album/the-message/59389719','https://www.youtube.com/results?search_query=Grandmaster+Flash+and+the+Furious+Five+The+Message+full+album',false),
('8c35e8ab-89cf-433e-8ffe-2e0ee439e9d2','sugarhill-gang','Sugarhill Gang','The Sugarhill Gang',1980,'1980s','Sugar Hill','United States','27d91a37-0b27-477a-b65d-82e9697175da',array['Old-school hip-hop','Disco rap']::text[],null,'<p>The cover of the Sugarhill Gang''s debut is all party. A crowd of dancers fills the frame in silhouette, lit from behind in hot orange and red as if caught under a club''s stage lights, with the group''s name curving across the top in glowing gold letters.</p><p>The album is built around "Rapper''s Delight," the 1979 single that took rap out of Bronx block parties and onto the radio. Assembled by Sylvia Robinson for her Sugar Hill label, the trio of Wonder Mike, Big Bank Hank and Master Gee rode a replayed groove from Chic''s "Good Times" for nearly fifteen minutes, and the song reached the Billboard Top 40, the first rap record to do so.</p><p>The image matches what the music was in 1980: dance music for a crowd. Before rap had its own visual language of street corners and gold chains, this cover sold it the way disco records were sold, as a night out, which is exactly how most of the world first heard hip-hop.</p>','#201D1D','#BC8347','https://static.wixstatic.com/media/b519fa_b37cec4a310f4f3db9a6b51977097a3b~mv2.jpg',2000,2000,'1cbO3L6JK5M6LxaVMUrUBC','https://open.spotify.com/album/1cbO3L6JK5M6LxaVMUrUBC','https://music.apple.com/us/album/sugarhill-gang/549037069','https://www.youtube.com/results?search_query=The+Sugarhill+Gang+Sugarhill+Gang+full+album',false)
